        ) : (
            <div className="text-center p-10 text-lg text-text-muted">لم يتم العثور على نتائج.</div>
        )}
        </div>
      </main>

       {wordPopoverState && (
         <div 
            ref={wordPopoverRef}
            className="absolute p-3 bg-surface rounded-lg shadow-lg border border-border-default flex items-center gap-2 z-20 animate-fade-in flex-wrap leading-loose"
            style={(() => {
                if (!wordPopoverState.triggerElement) return { opacity: 0, top: 0, left: 0 };
                const rect = wordPopoverState.triggerElement.getBoundingClientRect();
                return {
                    top: `${rect.bottom + window.scrollY + 5}px`,
                    left: `${rect.left + window.scrollX + rect.width / 2}px`,
                    transform: 'translateX(-50%)',
                };
            })()}
        >
            {wordPopoverState.simpleText.split(' ').map((word, wordIndex) => {
                const originalAyah = displayedResults[wordPopoverState.resultIndex];
                if (!originalAyah?.surah) return null;

                return (
                    <button
                        key={wordIndex}
                        onClick={() => {
                            onNewSearch(word, 'quran-simple-clean', { surah: originalAyah.surah!.number, ayah: originalAyah.numberInSurah, wordIndex: wordIndex });
                            setWordPopoverState(null);
                        }}
                        className="px-2 py-1 bg-surface-subtle rounded-md hover:bg-primary/20 transition-colors"
                    >
                        {word}
                    </button>
                );
            })}
        </div>
      )}

       {activePopover && (
            <AyahActionPopover 
                activePopover={activePopover}
                onClose={() => setActivePopover(null)}
                onSave={handleSaveClick}
                onCopy={handleCopyAyah}
                onSearchText={handleSearchByAyahText}
                onSearchNumber={onSearchByAyahNumber}
                onPlayFrom={handlePlayFromAyah}
                copiedAyah={copiedAyah}
            />
       )}

    </div>
  );
};

import React, { useMemo } from 'react';
import type { Ayah, SurahData, QuranEdition, FontSize } from '../types';
import { SparklesIcon } from './icons';
import { normalizeArabicText } from '../utils/text';

interface SearchResultItemProps {
  ayah: Ayah;
  queryWords: string[];
  onNewSearch: (word: string, sourceEdition?: string, position?: { surah: number, ayah: number, wordIndex: number }) => void;
  displayEdition: QuranEdition;
  displayEditionData: SurahData[];
  searchEdition: string;
  fontSize: FontSize;
  searchType: 'text' | 'number';
  isCurrentlyPlaying: boolean;
  itemRef: React.RefObject<HTMLLIElement>;
  pulsingWordIndex: number;
  resultIndex: number;
  simpleAyahText: string;
  onUthmaniWordClick: (event: React.MouseEvent<HTMLButtonElement>, resultIndex: number, simpleAyahText: string) => void;
  onOpenPopover: (ayah: Ayah, triggerElement: HTMLElement) => void;
}

const SearchResultItem: React.FC<SearchResultItemProps> = ({ 
    ayah, queryWords, onNewSearch, displayEdition, displayEditionData, 
    fontSize, searchType, isCurrentlyPlaying, itemRef, pulsingWordIndex,
    resultIndex, simpleAyahText, onUthmaniWordClick, onOpenPopover
}) => {

    const displayAyah = useMemo(() => {
        if (displayEditionData?.length > 0 && ayah.surah) {
            const displaySurah = displayEditionData.find(s => s.number === ayah.surah!.number);
            const displayAyahData = displaySurah?.ayahs.find(a => a.numberInSurah === ayah.numberInSurah);
            if (displayAyahData && displaySurah) {
                return { 
                    ...displayAyahData,
                    surah: {
                        number: displaySurah.number,
                        name: displaySurah.name,
                        englishName: displaySurah.englishName,
                        englishNameTranslation: displaySurah.englishNameTranslation,
                        revelationType: displaySurah.revelationType,
                    }
                };
            }
        }
        return ayah;
    }, [ayah, displayEditionData]);

    const handleSelectResult = (e: React.MouseEvent<HTMLAnchorElement>) => {
        e.preventDefault();
        if(ayah.surah) {
            window.location.hash = e.currentTarget.getAttribute('href')!;
        }
    };

    const getQuranTextStyle = () => {
        const isImlaei = displayEdition.identifier.includes('simple-clean');

        if (displayEdition.type === 'quran' && displayEdition.direction === 'rtl') {
          if (isImlaei) {
            return {
              className: `imlai-font quran-text-${fontSize}`,
              style: { fontFamily: `sans-serif` } // Browser default
            };
          } else { // Uthmani
            return {
              className: `uthmani-font quran-text-${fontSize}`,
              style: { fontFamily: `'Scheherazade New', 'Uthman', serif` }
            };
          }
        }

        // For translations or other text formats
        return { className: 'font-quran text-2xl', style: {} };
    };

    const { className: quranTextClass, style: quranTextStyle } = getQuranTextStyle();

    const renderAyahWithHighlight = () => {
        if (displayEdition.format === 'audio') {
            return <span className="text-sm text-text-muted">[مصدر صوتي، لا يتوفر عرض نصي هنا]</span>
        }

        if (!displayAyah.text) {
            return '';
        }
        const textToRender = displayAyah.text;
        const isImlaei = displayEdition.identifier.includes('simple-clean');

        const wordElements = textToRender.split(' ').map((word, index) => {
            const isPulsing = index === pulsingWordIndex;

            if (searchType === 'number') { // No highlighting for number search
                 return (
                    <button 
                        type="button" 
                        key={index} 
                        onClick={(e) => {
                            e.stopPropagation();
                            if (isImlaei) {
                                if (word && ayah.surah) {
                                    onNewSearch(word, displayEdition.identifier, { surah: ayah.surah.number, ayah: ayah.numberInSurah, wordIndex: index });
                                }
                            } else {
                                if (simpleAyahText) {
                                    onUthmaniWordClick(e, resultIndex, simpleAyahText);
                                }
                            }
                        }} 
                        className="word-trigger bg-transparent border-none p-0 font-inherit cursor-pointer hover:bg-primary/10 rounded-md px-1 transition-colors"
                        aria-label={`إظهار خيارات البحث لكلمة: ${word}`}
                    >
                        <span className={isPulsing ? 'animate-highlight-pulse rounded-sm' : ''}>{word}</span>
                    </button>
                 );
            }

            const normalizedWord = normalizeArabicText(word);
            const isMatch = queryWords.some(queryWord => normalizedWord.includes(queryWord));

            return (
                <button
                    type="button"
                    key={index}
                    onClick={(e) => {
                        e.stopPropagation();
                        if (isImlaei) {
                            if (word && ayah.surah) {
                                onNewSearch(word, displayEdition.identifier, { surah: ayah.surah.number, ayah: ayah.numberInSurah, wordIndex: index });
                            }
                        } else {
                            if (simpleAyahText) {
                                onUthmaniWordClick(e, resultIndex, simpleAyahText);
                            }
                        }
                    }}
                    className="word-trigger bg-transparent border-none p-0 font-inherit cursor-pointer hover:bg-primary/10 rounded-md px-1 transition-colors"
                    aria-label={`إظهار خيارات البحث لكلمة: ${word}`}
                >
                    {isMatch ? (
                        <mark className={`bg-yellow-400/40 text-text-primary rounded-sm ${isPulsing ? 'animate-highlight-pulse' : ''}`}>{word}</mark>
                    ) : (
                        <span className={isPulsing ? 'animate-highlight-pulse rounded-sm' : ''}>{word}</span>
                    )}
                </button>
            );
        });

        return wordElements.reduce((prev, curr, index) => <>{prev}{index > 0 ? ' ' : ''}{curr}</>, <></>);
    };

    return (
        <li
            ref={itemRef}
            className={`p-4 rounded-xl shadow-sm transition-all duration-300 hover:shadow-lg ${isCurrentlyPlaying ? 'bg-primary/20 ring-2 ring-primary' : 'bg-surface-subtle'}`}
        >
            <div className="flex justify-between items-center mb-2 gap-4">
                 <a
                    href={`#/surah/${displayAyah.surah?.number}?ayah=${displayAyah.numberInSurah}`}
                    onClick={handleSelectResult}
                    className="text-primary-text font-bold cursor-pointer rounded-md p-1 -m-1 hover:bg-surface-hover transition-colors"
                    aria-label={`الانتقال إلى ${displayAyah.surah?.name} الآية ${displayAyah.numberInSurah}`}
                >
                    <span className="font-quran-title">{displayAyah.surah?.name} - الآية {displayAyah.numberInSurah}</span>
                </a>

                <div className="flex items-center gap-2 flex-shrink-0">
                    <button
                        onClick={(e) => onOpenPopover(displayAyah, e.currentTarget)}
                        className="p-2 -m-2 rounded-full text-text-subtle hover:text-primary hover:bg-surface-hover transition-colors focus:outline-none focus:ring-2 focus:ring-primary/50"
                        aria-label="إجراءات الآية"
                        title="إجراءات الآية"
                    >
                        <SparklesIcon className="w-5 h-5" />
                    </button>
                </div>
            </div>
            <p
                dir={displayEdition.direction}
                style={quranTextStyle}
                aria-label={`نص الآية ${displayAyah.numberInSurah} من سورة ${displayAyah.surah?.name}`}
                className={`${quranTextClass} text-text-primary ${displayEdition.direction === 'ltr' ? 'text-left' : 'text-right'}`}
            >
               {renderAyahWithHighlight()}
            </p>
        </li>
    );
};

export default SearchResultItem;

import React, { useState, useMemo, useEffect } from 'react';
import type { QuranFont, QuranEdition, SurahData } from '../types';
import { CheckIcon, TrashIcon, PlusIcon, CopyIcon, SpinnerIcon, UploadIcon, DownloadIcon, RefreshIcon, SparklesIcon } from './icons';

interface TadabburGatewayProps {
    onExportNotebook: () => Promise<string>;
    onImportNotebook: (code: string) => Promise<void>;
}

const TadabburGateway: React.FC<TadabburGatewayProps> = ({ onExportNotebook, onImportNotebook }) => {
    const [exportCode, setExportCode] = useState<string | null>(null);
    const [isExporting, setIsExporting] = useState(false);
    const [exportError, setExportError] = useState<string | null>(null);

    const [importCode, setImportCode] = useState('');
    const [isImporting, setIsImporting] = useState(false);
    const [importMessage, setImportMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

    const handleExport = async () => {
        setIsExporting(true);
        setExportError(null);
        setExportCode(null);
        setImportMessage(null);
        try {
            const code = await onExportNotebook();
            setExportCode(code);
        } catch (err) {
            setExportError(err instanceof Error ? err.message : 'حدث خطأ غير متوقع');
        } finally {
            setIsExporting(false);
        }
    };

    const handleImport = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsImporting(true);
        setImportMessage(null);
        setExportError(null);
        setExportCode(null);
        try {
            await onImportNotebook(importCode);
            setImportMessage({ type: 'success', text: 'تم استيراد الدفتر بنجاح وحذف النسخة من الخادم.' });
            setImportCode('');
        } catch (err) {
            setImportMessage({ type: 'error', text: err instanceof Error ? err.message : 'حدث خطأ غير متوقع' });
        } finally {
            setIsImporting(false);
        }
    };

    return (
        <div className="animate-fade-in">
            <h2 className="text-2xl font-semibold mb-2 text-gray-800 dark:text-gray-200">بوابة دفتر التدبر</h2>
            <p className="text-gray-600 dark:text-gray-400 mb-8">استخدم هذه الواجهة لنقل بياناتك المحفوظة بين الأجهزة المختلفة.</p>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="p-5 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-700 flex flex-col">
                    <h3 className="text-xl font-semibold mb-2 text-gray-800 dark:text-gray-100">تصدير دفتر التدبر</h3>
                    <p className="text-sm text-gray-600 dark:text-gray-400 mb-4 flex-grow">
                        أنشئ كوداً مؤقتاً لنقل دفترك إلى جهاز آخر. عند إنشاء كود جديد، يتم حذف أي كود قديم.
                    </p>
                    <button
                        onClick={handleExport}
                        disabled={isExporting}
                        className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white font-semibold rounded-md hover:bg-blue-700 disabled:bg-blue-400 dark:disabled:bg-blue-800 transition-colors"
                    >
                        {isExporting ? <SpinnerIcon className="w-5 h-5"/> : <UploadIcon className="w-5 h-5" />}
                        <span>{isExporting ? 'جاري إنشاء الكود...' : 'إنشاء كود تصدير'}</span>
                    </button>
                    {exportCode && (
                        <div className="mt-4 p-4 bg-green-50 dark:bg-green-900/40 border border-green-200 dark:border-green-700 rounded-md text-center">
                            <p className="text-sm text-green-800 dark:text-green-200">انسخ الكود التالي وضعه في جهازك الجديد:</p>
                            <div className="my-2 text-3xl font-mono font-bold tracking-widest text-green-700 dark:text-green-300 select-all">
                                {exportCode}
                            </div>
                        </div>
                    )}
                    {exportError && (
                        <div className="mt-4 p-3 bg-red-50 dark:bg-red-900/40 text-red-700 dark:text-red-200 rounded-md text-sm">
                            {exportError}
                        </div>
                    )}
                </div>
                <div className="p-5 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-700 flex flex-col">
                    <h3 className="text-xl font-semibold mb-2 text-gray-800 dark:text-gray-100">استيراد دفتر التدبر</h3>
                    <p className="text-sm text-gray-600 dark:text-gray-400 mb-4 flex-grow">
                        أدخل الكود المكون من 6 رموز (3 أحرف ثم 3 أرقام) الذي حصلت عليه من جهازك القديم.
                    </p>
                    <form onSubmit={handleImport}>
                        <input
                            type="text"
                            value={importCode}
                            onChange={(e) => setImportCode(e.target.value.toUpperCase())}
                            maxLength={6}
                            placeholder="XYZ123"
                            className="w-full p-3 text-2xl font-mono tracking-widest text-center border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-green-500"
                            required
                        />
                        <button
                            type="submit"
                            disabled={isImporting || importCode.length !== 6}
                            className="w-full mt-3 flex items-center justify-center gap-2 px-4 py-2 bg-green-600 text-white font-semibold rounded-md hover:bg-green-700 disabled:bg-green-400 dark:disabled:bg-green-800 transition-colors"
                        >
                            {isImporting ? <SpinnerIcon className="w-5 h-5"/> : <DownloadIcon className="w-5 h-5" />}
                            <span>{isImporting ? 'جاري الاستيراد...' : 'استيراد الدفتر'}</span>
                        </button>
                    </form>
                    {importMessage && (
                        <div className={`mt-4 p-3 rounded-md text-sm ${importMessage.type === 'success' ? 'bg-green-50 dark:bg-green-900/40 text-green-700 dark:text-green-200' : 'bg-red-50 dark:bg-red-900/40 text-red-700 dark:text-red-200'}`}>
                            {importMessage.text}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};


