                </p>
                <div className="flex items-center gap-3 mt-4">
                    <button onClick={handleSave} className="flex-grow flex items-center justify-center gap-2 px-4 py-2 bg-green-600 text-white font-semibold rounded-md hover:bg-green-700 transition-colors">
                        <CheckIcon className="w-5 h-5"/>
                        <span>حفظ المفتاح</span>
                    </button>
                    {apiKey && (
                        <button onClick={handleDelete} className="flex-shrink-0 flex items-center justify-center gap-2 px-4 py-2 bg-red-600 text-white font-semibold rounded-md hover:bg-red-700 transition-colors">
                            <TrashIcon className="w-5 h-5"/>
                            <span>حذف</span>
                        </button>
                    )}
                </div>
                 {saveSuccess && (
                    <p className="text-green-600 dark:text-green-400 text-sm mt-3 text-center">تم حفظ المفتاح بنجاح.</p>
                )}
            </div>
        </div>
    );
};

interface SettingsViewProps {
    activeEditions: QuranEdition[];
    availableEditions: QuranEdition[];
    onAddEdition: (identifier: string) => void;
    onDeleteEdition: (identifier: string) => void;
    allQuranData: { [key: string]: SurahData[] } | null;
    loadingEditions: string[];
    onExportNotebook: () => Promise<string>;
    onImportNotebook: (code: string) => Promise<void>;
    getEditionUrl: (edition: QuranEdition) => string;
}

const SettingsView: React.FC<SettingsViewProps> = ({ 
    activeEditions, availableEditions, onAddEdition, onDeleteEdition,
    allQuranData, loadingEditions, onExportNotebook, onImportNotebook,
    getEditionUrl
}) => {
    type Tab = 'mushaf' | 'tadabbur' | 'export_format' | 'api_key';
    const [activeTab, setActiveTab] = useState<Tab>('mushaf');
    const [customUrl, setCustomUrl] = useState('');
    const [copySuccess, setCopySuccess] = useState('');

    // --- Filters State ---
    const [searchFilter, setSearchFilter] = useState('');
    const [languageFilter, setLanguageFilter] = useState('all');
    const [typeFilter, setTypeFilter] = useState('all');

    useEffect(() => {
        const params = new URLSearchParams(window.location.hash.split('?')[1]);
        const tabParam = params.get('tab');
        if (tabParam === 'tadabbur' || tabParam === 'mushaf' || tabParam === 'export_format' || tabParam === 'api_key') {
            setActiveTab(tabParam as Tab);
        }
    }, [window.location.hash]);

    const handleAddFromUrl = () => {
        if(customUrl.trim()){
            onAddEdition(customUrl.trim());
            setCustomUrl('');
        }
    }

    const handleCopy = (identifier: string, url: string) => {
        navigator.clipboard.writeText(url).then(() => {
            setCopySuccess(identifier);
            setTimeout(() => setCopySuccess(''), 2000);
        });
    };

    const allDisplayEditions = useMemo(() => {
        const textEditions = availableEditions.filter(e => e.format === 'text');
        const editionMap = new Map<string, QuranEdition>();
        textEditions.forEach(e => editionMap.set(e.identifier, e));
        activeEditions.forEach(e => {
            if (e.format === 'text' && !editionMap.has(e.identifier) && e.identifier.startsWith('http')) {
                editionMap.set(e.identifier, e);
            }
        });
        return Array.from(editionMap.values()).sort((a,b) => a.name.localeCompare(b.name, 'ar'));
    }, [availableEditions, activeEditions]);

    const filterOptions = useMemo(() => {
        const languages = new Map<string, string>();
        const types = new Map<string, string>();

        const languageNames: { [key: string]: string } = {
            ar: 'العربية', en: 'الإنجليزية', fr: 'الفرنسية', es: 'الإسبانية', ru: 'الروسية', de: 'الألمانية', tr: 'التركية', ur: 'الأردية',
            id: 'الإندونيسية', ms: 'الماليزية', bn: 'البنغالية', fa: 'الفارسية', ha: 'الهوسا', so: 'الصومالية', sq: 'الألبانية', sv: 'السويدية',
            sw: 'السواحيلية', ta: 'التاميلية', tg: 'الطاجيكية', tt: 'التترية', ug: 'الأويغورية', uz: 'الأوزبكية', zh: 'الصينية',
        };

        const typeNames: { [key: string]: string } = {
            quran: 'قرآن', tafsir: 'تفسير', translation: 'ترجمة',
        };

        allDisplayEditions.forEach(e => {
            languages.set(e.language, languageNames[e.language] || e.language.toUpperCase());
            types.set(e.type, typeNames[e.type] || e.type);
        });

        return {
            languages: Array.from(languages.entries()).sort((a,b) => a[1].localeCompare(b[1], 'ar')),
            types: Array.from(types.entries()).sort((a,b) => a[1].localeCompare(b[1], 'ar'))
        };
    }, [allDisplayEditions]);

    const filteredEditions = useMemo(() => {
        return allDisplayEditions.filter(edition => {
            const searchLower = searchFilter.toLowerCase().trim();
            if (searchLower) {
                const nameMatch = edition.name.toLowerCase().includes(searchLower);
                const englishNameMatch = edition.englishName.toLowerCase().includes(searchLower);
                const identifierMatch = edition.identifier.toLowerCase().includes(searchLower);
                if (!nameMatch && !englishNameMatch && !identifierMatch) {
                    return false;
                }
            }
            if (languageFilter !== 'all' && edition.language !== languageFilter) return false;
            if (typeFilter !== 'all' && edition.type !== typeFilter) return false;
            return true;
        });
    }, [allDisplayEditions, searchFilter, languageFilter, typeFilter]);


    return (
        <div className="animate-fade-in w-full max-w-5xl mx-auto px-4">
            <main className="bg-white dark:bg-gray-800 p-6 sm:p-8 rounded-lg shadow-md transition-colors duration-300 relative">
                <div className="flex border-b border-gray-200 dark:border-gray-700 mb-6 overflow-x-auto">
                    <button
                        onClick={() => setActiveTab('mushaf')}
                        className={`flex-shrink-0 px-4 py-3 text-lg font-semibold transition-colors ${
                            activeTab === 'mushaf'
                                ? 'border-b-2 border-green-600 text-green-600 dark:text-green-400'
                                : 'text-gray-500 hover:text-gray-800 dark:hover:text-gray-200'
                        }`}
                        aria-current={activeTab === 'mushaf'}
                    >
                        المصادر
                    </button>
                    <button
                        onClick={() => setActiveTab('tadabbur')}
                        className={`flex-shrink-0 px-4 py-3 text-lg font-semibold transition-colors ${
                            activeTab === 'tadabbur'
                                ? 'border-b-2 border-green-600 text-green-600 dark:text-green-400'
                                : 'text-gray-500 hover:text-gray-800 dark:hover:text-gray-200'
                        }`}
                        aria-current={activeTab === 'tadabbur'}
                    >
                        دفتر التدبر
                    </button>
                     <button
                        onClick={() => setActiveTab('api_key')}
                        className={`flex-shrink-0 px-4 py-3 text-lg font-semibold transition-colors flex items-center gap-2 ${
                            activeTab === 'api_key'
                                ? 'border-b-2 border-green-600 text-green-600 dark:text-green-400'
                                : 'text-gray-500 hover:text-gray-800 dark:hover:text-gray-200'
                        }`}
                        aria-current={activeTab === 'api_key'}
                    >
                        <SparklesIcon className="w-5 h-5" />
                        الذكاء الاصطناعي
                    </button>
                    <button
                        onClick={() => setActiveTab('export_format')}
                        className={`flex-shrink-0 px-4 py-3 text-lg font-semibold transition-colors ${
                            activeTab === 'export_format'
                                ? 'border-b-2 border-green-600 text-green-600 dark:text-green-400'
                                : 'text-gray-500 hover:text-gray-800 dark:hover:text-gray-200'
                        }`}
                        aria-current={activeTab === 'export_format'}
                    >
                        تنسيق التصدير
                    </button>
                </div>

                <div>
                    {activeTab === 'mushaf' && (
                        <div className="animate-fade-in">
                            <h2 className="text-2xl font-semibold mb-2 text-gray-800 dark:text-gray-200">
                                إدارة المصادر النصية (التفاسير والترجمات)
                            </h2>
                            <p className="text-gray-600 dark:text-gray-400 mb-6">
                                أضف أو أزل نسخ القرآن والتفاسير. المصادر النشطة تظهر في قائمة الاختيار في الصفحة الرئيسية.
                            </p>

                            <div className="mb-6 p-4 bg-gray-50 dark:bg-gray-900/50 rounded-lg border border-gray-200 dark:border-gray-700">
                                <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 items-end">
                                    <div className="sm:col-span-1">
                                        <label htmlFor="search-filter" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">بحث</label>
                                        <input
                                            type="text"
                                            id="search-filter"
                                            value={searchFilter}
                                            onChange={e => setSearchFilter(e.target.value)}
                                            placeholder="ابحث بالاسم أو المعرّف..."
                                            className="w-full p-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        />
                                    </div>
                                    <div>
                                        <label htmlFor="lang-filter" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">اللغة</label>
                                        <select
                                            id="lang-filter"
                                            value={languageFilter}
                                            onChange={e => setLanguageFilter(e.target.value)}
                                            className="w-full p-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        >
                                            <option value="all">كل اللغات</option>
                                            {filterOptions.languages.map(([code, name]) => <option key={code} value={code}>{name}</option>)}
                                        </select>
                                    </div>
                                    <div>
                                        <label htmlFor="type-filter" className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">النوع</label>
                                        <select
                                            id="type-filter"
                                            value={typeFilter}
                                            onChange={e => setTypeFilter(e.target.value)}
                                            className="w-full p-2 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-green-500"
                                        >
                                            <option value="all">كل الأنواع</option>
                                            {filterOptions.types.map(([code, name]) => <option key={code} value={code}>{name}</option>)}
                                        </select>
                                    </div>
                                </div>
                                <div className="mt-4 flex justify-end">
                                    <button
                                        onClick={() => {
                                            setSearchFilter('');
                                            setLanguageFilter('all');
                                            setTypeFilter('all');
                                        }}
                                        className="flex items-center gap-2 px-4 py-2 bg-gray-200 dark:bg-gray-600 text-sm font-semibold rounded-md hover:bg-gray-300 dark:hover:bg-gray-500 transition-colors"
                                    >
                                        <RefreshIcon className="w-4 h-4" />
                                        <span>إعادة تعيين الفلاتر</span>
                                    </button>
                                </div>
                            </div>

                            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-5">
                                {filteredEditions.map((edition) => {
                                    const isActive = activeEditions.some(e => e.identifier === edition.identifier);
                                    const isDefault = edition.identifier === 'quran-simple-clean' || edition.identifier === 'quran-uthmani';
                                    const isLoading = loadingEditions.includes(edition.identifier);

                                    const editionData = allQuranData && isActive ? allQuranData[edition.identifier] : null;
                                    const surahBaqarah = editionData ? editionData.find(s => s.number === 2) : null;
                                    const ayah125 = surahBaqarah ? surahBaqarah.ayahs.find(a => a.numberInSurah === 125) : null;
                                    const previewText = ayah125 ? (ayah125.text || '').replace(/\s*﴿\d+﴾\s*/g, ' ').trim() : "أضف المصدر لرؤية المعاينة";

                                    return (
                                        <div key={edition.identifier} className={`border-2 rounded-lg flex flex-col justify-between transition-all duration-200 ${isActive ? 'border-green-500 bg-green-50/50 dark:bg-green-900/30' : 'border-gray-200 dark:border-gray-700 bg-gray-50 dark:bg-gray-900/50'}`}>
                                            <div className="p-4">
                                                <div className={`text-right text-lg text-gray-800 dark:text-gray-100 min-h-[120px] p-2 rounded-md bg-white dark:bg-gray-800 overflow-auto flex items-center justify-center`}>
                                                    {isLoading ? <SpinnerIcon className="w-8 h-8 text-green-600"/> : <p className={!isActive ? 'opacity-50' : ''}>{previewText}</p>}
                                                </div>
                                            </div>
                                            <div className="p-4 border-t-2 border-gray-200 dark:border-gray-700 space-y-3">
                                                <div>
                                                    <h3 className="text-md font-bold text-gray-800 dark:text-gray-200">{edition.name}</h3>
                                                    <p className="text-xs text-gray-500 dark:text-gray-400">{edition.englishName}</p>
                                                </div>
                                                <div className="flex items-center gap-1">
                                                    <div className="w-full text-xs bg-gray-200 dark:bg-gray-700 p-2 rounded-md break-all">{edition.identifier}</div>
                                                    <button onClick={() => handleCopy(edition.identifier, getEditionUrl(edition))} className="flex-shrink-0 p-2 text-gray-500 hover:bg-gray-300 dark:hover:bg-gray-600 rounded-md">
                                                        {copySuccess === edition.identifier ? <CheckIcon className="w-4 h-4 text-green-500" /> : <CopyIcon className="w-4 h-4" />}
                                                    </button>
                                                </div>
                                                {isActive ? (
                                                    <button onClick={() => onDeleteEdition(edition.identifier)} disabled={isDefault} className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-red-600 text-white font-semibold rounded-md hover:bg-red-700 disabled:bg-red-400 dark:disabled:bg-red-800 disabled:cursor-not-allowed transition-colors">
                                                        <TrashIcon className="w-5 h-5"/>
                                                        <span>حذف</span>
                                                    </button>
                                                ) : (
                                                    <button onClick={() => onAddEdition(edition.identifier)} className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-green-600 text-white font-semibold rounded-md hover:bg-green-700 transition-colors">
                                                        <PlusIcon className="w-5 h-5"/>
                                                        <span>إضافة</span>
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    );
                                })}
                                <div className="border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg p-4 flex flex-col justify-center">
                                    <h3 className="text-md font-bold text-gray-800 dark:text-gray-200 mb-2 text-center">إضافة مصدر مخصص</h3>
                                    <p className="text-xs text-gray-500 dark:text-gray-400 mb-4 text-center">أضف رابط URL لملف JSON متوافق.</p>
                                    <input type="url" value={customUrl} onChange={(e) => setCustomUrl(e.target.value)} placeholder="https://example.com/quran.json" className="w-full text-xs bg-gray-100 dark:bg-gray-700 p-2 rounded-md border border-gray-300 dark:border-gray-600 mb-3 focus:ring-green-500 focus:border-green-500" />
                                    <button onClick={handleAddFromUrl} className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white font-semibold rounded-md hover:bg-blue-700 transition-colors">
                                        <PlusIcon className="w-5 h-5"/>
                                        <span>إضافة الرابط</span>
                                    </button>
                                </div>
                            </div>
                            {filteredEditions.length === 0 && (
                                <div className="mt-6 text-center py-10 text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-gray-900/50 rounded-lg">
                                    <p className="text-lg font-semibold">لم يتم العثور على مصادر تطابق معايير الفلترة.</p>
                                    <p>حاول تغيير البحث أو إعادة تعيين الفلاتر.</p>
                                </div>
                            )}
                        </div>
                    )}
                    {activeTab === 'tadabbur' && (
                        <TadabburGateway 
                            onExportNotebook={onExportNotebook}
                            onImportNotebook={onImportNotebook}
                        />
                    )}
                    {activeTab === 'api_key' && <ApiKeySettings />}
                    {activeTab === 'export_format' && (
                        <ExportFormatSettings />
                    )}
                </div>
            </main>
        </div>
    );
};

export default SettingsView;

import React, { useState, useEffect, useRef } from 'react';
import type { QuranFont, QuranEdition, FontSize, BrowsingMode } from '../types';
import { ArrowLeftIcon, ArrowRightIcon, HomeIcon, TextSizeIcon, PlusIcon, MinusIcon, SparklesIcon, BookOpenIcon, CheckIcon, DocumentDuplicateIcon, QueueListIcon } from './icons';

interface ToolboxProps {
    // Font Size
    fontSize: FontSize;
    onFontSizeChange: (size: FontSize) => void;
    // Editions
    activeEditions: QuranEdition[];
    selectedEdition: string;
    onEditionChange: (id: string) => void;
    isAudioPlayerVisible: boolean;
    // Browsing Mode
    browsingMode: BrowsingMode;
    onBrowsingModeChange: (mode: BrowsingMode) => void;
}

const Toolbox: React.FC<ToolboxProps> = ({
    fontSize, onFontSizeChange,
    activeEditions, selectedEdition, onEditionChange,
    isAudioPlayerVisible,
    browsingMode, onBrowsingModeChange
}) => {
    type Popover = 'size' | 'edition';
    const [openPopover, setOpenPopover] = useState<Popover | null>(null);
    const [isShown, setIsShown] = useState(true);
    const popoverRef = useRef<HTMLDivElement>(null);
    const lastScrollY = useRef(0);

    // Effect to handle toolbox visibility on scroll
    useEffect(() => {
        const handleScroll = () => {
            const currentScrollY = window.scrollY;
            const scrollThreshold = 20;

            // Do nothing if scroll change is insignificant
            if (Math.abs(currentScrollY - lastScrollY.current) < scrollThreshold) {
                return;
            }

            if (currentScrollY < 100) { // Always show near the top
                setIsShown(true);
            } else if (currentScrollY > lastScrollY.current) { // Scrolling down
                setIsShown(false);
                setOpenPopover(null); // Hide popovers when toolbar hides
            } else { // Scrolling up
                setIsShown(true);
            }
            lastScrollY.current = currentScrollY;
        };

        window.addEventListener('scroll', handleScroll, { passive: true });
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    // Close popover on outside click
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (popoverRef.current && !popoverRef.current.contains(event.target as Node)) {
                setOpenPopover(null);
            }
        };
        if (openPopover) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [openPopover]);

    const handleTogglePopover = (popover: Popover) => {
        setOpenPopover(prev => (prev === popover ? null : popover));
    };

    const handleSelectAndClose = (setter: (value: string) => void) => (event: React.MouseEvent<HTMLButtonElement>) => {
        setter(event.currentTarget.value);
        setOpenPopover(null);
    };

    const ToolButton: React.FC<{ onClick: () => void; label: string; children: React.ReactNode; isActive?: boolean }> = ({ onClick, label, children, isActive }) => (
        <button
            onClick={onClick}
            aria-label={label}
            title={label}
            className={`p-3 rounded-full transition-colors ${isActive ? 'bg-surface-active text-primary-text-strong' : 'text-text-muted hover:bg-surface-hover'}`}
        >
            {children}
        </button>
    );

    const PopoverContainer: React.FC<{ children: React.ReactNode; popoverId: Popover, title: string, widthClass?: string }> = ({ children, popoverId, title, widthClass = 'w-72' }) => (
        openPopover === popoverId ? (
            <div ref={popoverRef} className={`absolute bottom-full left-1/2 -translate-x-1/2 mb-3 ${widthClass} bg-surface rounded-lg shadow-2xl ring-1 ring-black/5 animate-fade-in`}
                role="dialog" aria-labelledby={`${popoverId}-title`}>
                <div className="p-3 border-b border-border-default">
                    <h3 id={`${popoverId}-title`} className="font-semibold text-text-primary">{title}</h3>
                </div>
                <div className="p-3 max-h-64 overflow-y-auto">
                    {children}
                </div>
                <div className={`absolute left-1/2 -translate-x-1/2 bottom-[-8px] w-4 h-4 bg-surface rotate-45 -z-10`}></div>
            </div>
        ) : null
    );

    return (
        <div className={`fixed left-1/2 -translate-x-1/2 z-20 transition-all duration-300 ${isAudioPlayerVisible ? 'bottom-28' : 'bottom-8'}`}>
            <div className={`relative flex items-center gap-1 bg-surface/80 backdrop-blur-md p-2 rounded-full shadow-lg border border-border-default transition-all duration-300 ${
                isShown ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-16 pointer-events-none'
            }`}>

                {/* Navigation Group */}
                <ToolButton onClick={() => window.history.back()} label="الخلف"><ArrowRightIcon className="w-5 h-5" /></ToolButton>
                <ToolButton onClick={() => window.location.hash = '#/'} label="الرئيسية"><HomeIcon className="w-5 h-5" /></ToolButton>
                <ToolButton onClick={() => window.history.forward()} label="الأمام"><ArrowLeftIcon className="w-5 h-5" /></ToolButton>

                <div className="h-6 w-px bg-border-default mx-2"></div>

                {/* Settings Group */}
                <div className="relative">
                    <ToolButton onClick={() => handleTogglePopover('size')} label="حجم الخط" isActive={openPopover === 'size'}>
                        <TextSizeIcon className="w-5 h-5" />
                    </ToolButton>
                    <PopoverContainer popoverId="size" title="تغيير حجم الخط" widthClass="w-auto">
                        <div className="flex items-center justify-center gap-2">
                            <button
                                onClick={() => onFontSizeChange('sm')}
                                className={`p-3 w-16 h-12 flex items-center justify-center rounded-lg transition-colors ${fontSize === 'sm' ? 'bg-surface-active text-primary-text-strong' : 'bg-surface-subtle hover:bg-surface-hover'}`}
                                aria-pressed={fontSize === 'sm'}
                                title="صغير"
                            >
                                <span className="text-sm font-bold">A</span>
                            </button>
                            <button
                                onClick={() => onFontSizeChange('md')}
                                className={`p-3 w-16 h-12 flex items-center justify-center rounded-lg transition-colors ${fontSize === 'md' ? 'bg-surface-active text-primary-text-strong' : 'bg-surface-subtle hover:bg-surface-hover'}`}
                                aria-pressed={fontSize === 'md'}
                                title="متوسط"
                            >
                                <span className="text-lg font-bold">A</span>
                            </button>
                            <button
                                onClick={() => onFontSizeChange('lg')}
                                className={`p-3 w-16 h-12 flex items-center justify-center rounded-lg transition-colors ${fontSize === 'lg' ? 'bg-surface-active text-primary-text-strong' : 'bg-surface-subtle hover:bg-surface-hover'}`}
                                aria-pressed={fontSize === 'lg'}
                                title="كبير"
                            >
                                <span className="text-xl font-bold">A</span>
                            </button>
                        </div>
                    </PopoverContainer>
                </div>

                 <div className="relative">
                    <ToolButton onClick={() => handleTogglePopover('edition')} label="تغيير المصحف" isActive={openPopover === 'edition'}>
                        <BookOpenIcon className="w-5 h-5" />
                    </ToolButton>
                     <PopoverContainer popoverId="edition" title="اختر نسخة العرض">
                        <div className="space-y-1">
                            {activeEditions.map(edition => (
                                <button key={edition.identifier} onClick={handleSelectAndClose(onEditionChange)} value={edition.identifier}
                                    className="w-full text-right p-2 rounded-md flex justify-between items-center text-text-primary hover:bg-surface-hover transition-colors">
                                    <span>{edition.name}</span>
                                    {selectedEdition === edition.identifier && <CheckIcon className="w-5 h-5 text-primary" />}
                                </button>
                            ))}
                        </div>
                    </PopoverContainer>
                </div>

                <div className="h-6 w-px bg-border-default mx-2"></div>

                {/* Browsing Mode Group */}
                <ToolButton
                    onClick={() => onBrowsingModeChange(browsingMode === 'full' ? 'page' : 'full')}
                    label={browsingMode === 'full' ? 'التحويل إلى عرض الصفحات' : 'التحويل إلى العرض الكامل'}
                >
                    {browsingMode === 'full' ? <DocumentDuplicateIcon className="w-5 h-5" /> : <QueueListIcon className="w-5 h-5" />}
                </ToolButton>

            </div>
        </div>
    );
};

export default Toolbox;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import type { Ayah, QuranEdition, SurahData, FontSize, QuranFont } from '../types';
import { useTheme } from '../hooks/useTheme';
import { 
    SpinnerIcon, PlayIcon, PauseIcon, ForwardIcon, BackwardIcon, 
    HomeIcon,
    CogIcon, ClearIcon, CheckIcon, BookOpenIcon, TextSizeIcon, QueueListIcon,
    ComputerDesktopIcon, JuzOneIcon
} from './icons';
import AudioEditionSelector from './AudioEditionSelector';

// --- Types ---
type PlaybackMode = 'continuous' | 'single' | 'selection';

interface AudioKhatmiyahViewProps {
    allAyahs: Ayah[];
    allAudioEditions: QuranEdition[];
    initialAyahNumber: number;
    onSaveProgress: (ayahNumber: number) => void;
    selectedAudioEdition: string;
    onAudioEditionChange: (id: string) => void;
    allQuranData: { [key: string]: SurahData[] } | null;
    fetchCustomEditionData: (id: string) => void;
    fontSize: FontSize;
    onFontSizeChange: (size: FontSize) => void;
    activeEditions: QuranEdition[];
    selectedEdition: string;
    onEditionChange: (id: string) => void;
}

// --- Helper: Get Audio URL ---
const getAudioUrl = (ayah: Ayah, audioEditionDetails: QuranEdition): string | undefined => {
    const { sourceApi, reciterIdentifier, identifier } = audioEditionDetails;
    if (!ayah.surah?.number) return undefined;

    switch (sourceApi) {
        case 'versebyversequran.com':
        if (!reciterIdentifier) return undefined;
        const surahNumPad = ayah.surah.number.toString().padStart(3, '0');
        const ayahNumPad = ayah.numberInSurah.toString().padStart(3, '0');
        return `https://everyayah.com/data/${reciterIdentifier}/${surahNumPad}${ayahNumPad}.mp3`;

        case 'islamic-network':
        if (!ayah.number) return undefined;
        return `https://cdn.islamic.network/quran/audio/128/${identifier}/${ayah.number}.mp3`;

        default:
        return undefined;
    }
};

// --- Juz Selection Modal ---
interface JuzSelectionModalProps {
    onClose: () => void;
    juzStartAyahs: { juz: number, ayahNumber: number }[];
    onJuzSelect: (ayahNumber: number) => void;
    onSelectionConfirm: (selectedJuzs: number[]) => void;
    mode: 'jump' | 'selection';
}

const JuzSelectionModal: React.FC<JuzSelectionModalProps> = ({ onClose, juzStartAyahs, onJuzSelect, onSelectionConfirm, mode }) => {
    const [selectedJuzs, setSelectedJuzs] = useState<number[]>([]);

    const handleJuzClick = (juz: number, ayahNumber: number) => {
        if (mode === 'jump') {
            onJuzSelect(ayahNumber);
            onClose();
        } else { // selection mode
            setSelectedJuzs(prev => 
                prev.includes(juz) ? prev.filter(j => j !== juz) : [...prev, juz]
            );
        }
    };

    const handleConfirm = () => {
        if (selectedJuzs.length > 0) {
            onSelectionConfirm(selectedJuzs.sort((a,b) => a-b));
            onClose();
        }
    };

    const title = mode === 'jump' ? "الانتقال إلى جزء" : "اختر الأجزاء";

    return (
        <div 
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center animate-fade-in p-4"
            onClick={onClose}
        >
            <div 
                className="bg-surface rounded-lg shadow-xl w-full max-w-lg mx-auto flex flex-col"
                onClick={e => e.stopPropagation()}
            >
                <div className="p-4 border-b border-border-default flex justify-between items-center">
                    <h2 className="text-xl font-bold text-text-primary">{title}</h2>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-surface-hover">
                        <ClearIcon className="w-5 h-5" />
                    </button>
                </div>
                <div className="p-4 overflow-y-auto">
                    <div className="grid grid-cols-6 gap-2">
                        {juzStartAyahs.map(({ juz, ayahNumber }) => {
                            const isSelected = mode === 'selection' && selectedJuzs.includes(juz);
                            return (
                                <button
                                    key={juz}
                                    onClick={() => handleJuzClick(juz, ayahNumber)}
                                    className={`p-3 rounded-lg text-center font-mono font-bold text-lg text-text-secondary transition-colors focus:outline-none focus:ring-2 focus:ring-primary
                                        bg-surface-subtle hover:bg-surface-hover
                                        ${isSelected ? 'ring-2 ring-primary bg-surface-active' : ''}
                                    `}
                                >
                                    {juz}
                                </button>
                            );
                        })}
                    </div>
                </div>
                {mode === 'selection' && (
                    <div className="p-4 border-t border-border-default">
                        <button 
                            onClick={handleConfirm}
                            disabled={selectedJuzs.length === 0}
                            className="w-full px-4 py-3 bg-primary text-white font-semibold rounded-md hover:bg-primary-hover disabled:bg-primary/50 transition-colors"
                        >
                            بدء القراءة ({selectedJuzs.length})
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

