// --- Main Component ---
const AudioKhatmiyahView: React.FC<AudioKhatmiyahViewProps> = ({
    allAyahs, allAudioEditions, initialAyahNumber, onSaveProgress,
    selectedAudioEdition, onAudioEditionChange, allQuranData, fetchCustomEditionData,
    fontSize,
    activeEditions, selectedEdition
}) => {
    const [currentAyahNumber, setCurrentAyahNumber] = useState(initialAyahNumber);
    const [currentAyah, setCurrentAyah] = useState<Ayah | null>(null);
    const [uthmaniText, setUthmaniText] = useState<string>('');
    const [displayedText, setDisplayedText] = useState<string>('');

    const [isPlaying, setIsPlaying] = useState(false);
    const [audioDuration, setAudioDuration] = useState(0);
    const [audioProgress, setAudioProgress] = useState(0);

    const [isLoading, setIsLoading] = useState(true);

    const [controlsVisible, setControlsVisible] = useState(true);
    const [isJuzSelectorOpen, setIsJuzSelectorOpen] = useState(false);
    const [isModeSelectorOpen, setIsModeSelectorOpen] = useState(false);

    // --- New State for Playback Modes ---
    const [playbackMode, setPlaybackMode] = useState<PlaybackMode>('continuous');
    const [playbackSelection, setPlaybackSelection] = useState<number[] | null>(null);
    const [juzModalMode, setJuzModalMode] = useState<'jump' | 'selection'>('jump');

    const audioRef = useRef<HTMLAudioElement>(null);

    const audioEditionDetails = useMemo(() => allAudioEditions.find(e => e.identifier === selectedAudioEdition), [selectedAudioEdition, allAudioEditions]);
    const displayEditionDetails = useMemo(() => activeEditions.find(e => e.identifier === selectedEdition), [activeEditions, selectedEdition]);

    const handleScreenTap = () => {
        // Only allow toggling visibility if the audio is playing.
        if (isPlaying) {
            setControlsVisible(prev => !prev);
        }
    };

    useEffect(() => {
        // When playback stops, controls must become visible.
        if (!isPlaying) {
            setControlsVisible(true);
        }
    }, [isPlaying]);

    const juzStartAyahs = useMemo(() => {
        if (!allAyahs || allAyahs.length === 0) return [];
        const juzMap = new Map<number, number>();
        for (const ayah of allAyahs) {
            if (ayah.juz && !juzMap.has(ayah.juz)) {
                juzMap.set(ayah.juz, ayah.number);
            }
        }
        return Array.from(juzMap.entries())
            .sort((a, b) => a[0] - b[0])
            .map(([juz, ayahNumber]) => ({ juz, ayahNumber }));
    }, [allAyahs]);

    const handleJuzSelect = (ayahNumber: number) => {
        setCurrentAyahNumber(ayahNumber);
        setIsJuzSelectorOpen(false);
        if (!isPlaying) setIsPlaying(true);
    };

    const handleSelectionConfirm = (selectedJuzs: number[]) => {
        if (selectedJuzs.length === 0) return;
        setPlaybackMode('selection');
        setPlaybackSelection(selectedJuzs);
        const startAyahNumber = juzStartAyahs.find(j => j.juz === selectedJuzs[0])?.ayahNumber;
        if (startAyahNumber) {
            setCurrentAyahNumber(startAyahNumber);
        }
        setIsJuzSelectorOpen(false);
        if (!isPlaying) setIsPlaying(true);
    };

    useEffect(() => {
        if (!allQuranData?.[selectedEdition]) {
            fetchCustomEditionData(selectedEdition);
        }
    }, [selectedEdition, allQuranData, fetchCustomEditionData]);

    useEffect(() => {
        const foundAyah = allAyahs.find(a => a.number === currentAyahNumber);
        if (foundAyah) {
            setCurrentAyah(foundAyah);
            const uthmaniData = allQuranData?.['quran-uthmani-quran-academy'];
            const uthmaniSurah = uthmaniData?.find(s => s.number === foundAyah.surah?.number);
            const uthmaniAyah = uthmaniSurah?.ayahs.find(a => a.numberInSurah === foundAyah.numberInSurah);
            setUthmaniText(uthmaniAyah?.text || foundAyah.text || '');

            const displayData = allQuranData?.[selectedEdition];
            const displaySurah = displayData?.find(s => s.number === foundAyah.surah?.number);
            const displayAyah = displaySurah?.ayahs.find(a => a.numberInSurah === foundAyah.numberInSurah);
            setDisplayedText(displayAyah?.text || foundAyah.text || '');
        }
    }, [currentAyahNumber, allAyahs, allQuranData, selectedEdition]);

    useEffect(() => {
        if (currentAyah && audioEditionDetails) {
            const url = getAudioUrl(currentAyah, audioEditionDetails);
            if (url && audioRef.current) {
                // If url is different or audio is ended/paused
                if (audioRef.current.src !== url) {
                    setIsLoading(true);
                    audioRef.current.src = url;
                    audioRef.current.load();
                    if (isPlaying) {
                        audioRef.current.play().catch(e => {
                            console.error("Play error", e);
                            setIsPlaying(false);
                        });
                    }
                }
            } else {
                setIsLoading(false);
            }
        }
    }, [currentAyah, audioEditionDetails, isPlaying]);

    const handleAudioEnded = () => {
        if (playbackMode === 'single') {
            setIsPlaying(false);
            return;
        }

        const nextNum = currentAyahNumber + 1;

        if (playbackMode === 'selection' && playbackSelection) {
             const nextAyah = allAyahs.find(a => a.number === nextNum);
             if (nextAyah && nextAyah.juz && playbackSelection.includes(nextAyah.juz)) {
                 setCurrentAyahNumber(nextNum);
                 onSaveProgress(nextNum);
             } else {
                 setIsPlaying(false);
             }
        } else {
             // Continuous
             if (nextNum <= 6236) {
                 setCurrentAyahNumber(nextNum);
                 onSaveProgress(nextNum);
             } else {
                 setIsPlaying(false);
             }
        }
    };

    const handleNext = () => {
        const nextNum = currentAyahNumber + 1;
        if (allAyahs.some(a => a.number === nextNum)) {
            setCurrentAyahNumber(nextNum);
            onSaveProgress(nextNum);
        }
    };

    const handlePrev = () => {
        const prevNum = currentAyahNumber - 1;
        if (prevNum > 0) {
            setCurrentAyahNumber(prevNum);
            onSaveProgress(prevNum);
        }
    };

    const handlePlayPause = () => {
        const audio = audioRef.current;
        if (!audio) return;

        if (isPlaying) {
            audio.pause();
            setIsPlaying(false);
        } else {
            audio.play().catch(console.error);
            setIsPlaying(true);
        }
    };

    return (
        <div className={`fixed inset-0 z-50 flex flex-col bg-background text-text-primary ${!controlsVisible ? 'cursor-none' : ''}`} onClick={handleScreenTap}>
            {/* Audio Element */}
            <audio
                ref={audioRef}
                onEnded={handleAudioEnded}
                onTimeUpdate={(e) => setAudioProgress(e.currentTarget.currentTime)}
                onDurationChange={(e) => setAudioDuration(e.currentTarget.duration)}
                onWaiting={() => isPlaying && setIsLoading(true)}
                onCanPlay={() => setIsLoading(false)}
                onPlay={() => setIsPlaying(true)}
                onPause={() => setIsPlaying(false)}
            />

            {/* Modals */}
            {isJuzSelectorOpen && (
                <JuzSelectionModal 
                    onClose={() => setIsJuzSelectorOpen(false)}
                    juzStartAyahs={juzStartAyahs}
                    onJuzSelect={handleJuzSelect}
                    onSelectionConfirm={handleSelectionConfirm}
                    mode={juzModalMode}
                />
            )}

            {isModeSelectorOpen && (
                <PlaybackModeModal 
                    onClose={() => setIsModeSelectorOpen(false)}
                    onModeSelect={(mode) => { setPlaybackMode(mode); setIsModeSelectorOpen(false); }}
                    onCustomSelectionStart={() => {
                        setIsModeSelectorOpen(false);
                        setJuzModalMode('selection');
                        setIsJuzSelectorOpen(true);
                    }}
                />
            )}

            {/* Top Bar */}
            <div className={`absolute top-0 left-0 right-0 p-4 flex justify-between items-start transition-transform duration-300 z-20 ${controlsVisible ? 'translate-y-0' : '-translate-y-full'}`} onClick={(e) => e.stopPropagation()}>
                <a href="#/" className="p-2 bg-surface/80 backdrop-blur rounded-full shadow-sm hover:bg-surface-hover transition-colors">
                    <HomeIcon className="w-6 h-6" />
                </a>

                <div className="flex gap-2">
                     <button onClick={() => { setJuzModalMode('jump'); setIsJuzSelectorOpen(true); }} className="p-2 bg-surface/80 backdrop-blur rounded-full shadow-sm hover:bg-surface-hover transition-colors">
                        <QueueListIcon className="w-6 h-6" />
                    </button>
                    <button onClick={() => setIsModeSelectorOpen(true)} className="p-2 bg-surface/80 backdrop-blur rounded-full shadow-sm hover:bg-surface-hover transition-colors">
                        <CogIcon className="w-6 h-6" />
                    </button>
                </div>
            </div>

            {/* Main Content (Ayah Display) */}
            <div className="flex-grow flex flex-col justify-center items-center p-6 text-center space-y-8 animate-fade-in relative">
                {isLoading && (
                    <div className="absolute inset-0 flex items-center justify-center bg-background/50 z-10">
                        <SpinnerIcon className="w-12 h-12 text-primary" />
                    </div>
                )}

                <div className="max-w-3xl w-full space-y-6">
                    {/* Surah Info */}
                    {currentAyah && (
                        <div className={`text-sm text-text-muted transition-opacity duration-500 ${controlsVisible ? 'opacity-100' : 'opacity-50'}`}>
                            سورة {currentAyah.surah?.name} - الآية {currentAyah.numberInSurah} - الجزء {currentAyah.juz}
                        </div>
                    )}

                    {/* Uthmani Text */}
                    <p className={`font-quran leading-loose text-primary-text-strong transition-all duration-500 quran-text-${fontSize}`} dir="rtl">
                        {uthmaniText}
                    </p>

                    {/* Translation/Tafsir Text (if different and selected) */}
                    {displayedText && displayedText !== uthmaniText && (
                        <p className={`text-text-secondary text-lg leading-relaxed transition-all duration-500 ${controlsVisible ? 'opacity-100' : 'opacity-0'}`} dir={displayEditionDetails?.direction || 'rtl'}>
                            {displayedText}
                        </p>
                    )}
                </div>
            </div>

            {/* Bottom Controls */}
            <div className={`absolute bottom-0 left-0 right-0 p-6 bg-surface/90 backdrop-blur-md shadow-lg rounded-t-2xl transition-transform duration-300 z-20 ${controlsVisible ? 'translate-y-0' : 'translate-y-full'}`} onClick={(e) => e.stopPropagation()}>
                {/* Progress Bar */}
                <div className="w-full bg-surface-subtle h-1.5 rounded-full mb-6 overflow-hidden">
                    <div className="h-full bg-primary transition-all duration-100" style={{ width: `${(audioProgress / (audioDuration || 1)) * 100}%` }}></div>
                </div>

                <div className="flex flex-col gap-4">
                    {/* Player Controls */}
                    <div className="flex items-center justify-center gap-8">
                        <button onClick={handleNext} className="p-3 text-text-secondary hover:text-primary transition-colors">
                            <ForwardIcon className="w-8 h-8" />
                        </button>

                        <button 
                            onClick={handlePlayPause}
                            className="w-16 h-16 bg-primary text-white rounded-full flex items-center justify-center shadow-xl hover:scale-105 transition-transform"
                        >
                            {isLoading ? <SpinnerIcon className="w-8 h-8" /> : (isPlaying ? <PauseIcon className="w-8 h-8" /> : <PlayIcon className="w-8 h-8 ml-1" />)}
                        </button>

                        <button onClick={handlePrev} className="p-3 text-text-secondary hover:text-primary transition-colors">
                            <BackwardIcon className="w-8 h-8" />
                        </button>
                    </div>

                    {/* Audio Edition Selector */}
                    <div className="max-w-md mx-auto w-full">
                        <AudioEditionSelector 
                            audioEditions={allAudioEditions}
                            selectedAudioEdition={selectedAudioEdition}
                            onSelect={onAudioEditionChange}
                            size="sm"
                        />
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AudioKhatmiyahView;

if (pathParts[0] === 'audio-khatmiyah') {
    return <AudioKhatmiyahView
        allAyahs={simpleSearchableAyahs}
        allAudioEditions={ALL_AUDIO_EDITIONS}
        initialAyahNumber={audioKhatmiyahProgress?.ayahNumber || 1}
        onSaveProgress={handleSaveAudioKhatmiyahProgress}
        selectedAudioEdition={selectedAudioEdition}
        onAudioEditionChange={setSelectedAudioEdition}
        allQuranData={allQuranData}
        fetchCustomEditionData={fetchCustomEditionData}
        fontSize={fontSize} onFontSizeChange={setFontSize}
        activeEditions={activeEditions} selectedEdition={selectedEdition} onEditionChange={setSelectedEdition}
        onOpenSidePanel={() => setIsSidePanelOpen(true)}
    />;
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import type { Ayah, QuranEdition, SurahData, FontSize } from '../types';
import { 
    SpinnerIcon, PlayIcon, PauseIcon, ForwardIcon, BackwardIcon, 
    MenuIcon,
    CogIcon, ClearIcon, BookOpenIcon, QueueListIcon,
    JuzOneIcon
} from './icons';
import AudioEditionSelector from './AudioEditionSelector';

// --- Types ---
type PlaybackMode = 'continuous' | 'single' | 'selection';

interface AudioKhatmiyahViewProps {
    allAyahs: Ayah[];
    allAudioEditions: QuranEdition[];
    initialAyahNumber: number;
    onSaveProgress: (ayahNumber: number) => void;
    selectedAudioEdition: string;
    onAudioEditionChange: (id: string) => void;
    allQuranData: { [key: string]: SurahData[] } | null;
    fetchCustomEditionData: (id: string) => void;
    fontSize: FontSize;
    onFontSizeChange: (size: FontSize) => void;
    activeEditions: QuranEdition[];
    selectedEdition: string;
    onEditionChange: (id: string) => void;
    onOpenSidePanel: () => void;
}

// --- Helper: Get Audio URL ---
const getAudioUrl = (ayah: Ayah, audioEditionDetails: QuranEdition): string | undefined => {
    const { sourceApi, reciterIdentifier, identifier } = audioEditionDetails;
    if (!ayah.surah?.number) return undefined;

    switch (sourceApi) {
        case 'versebyversequran.com':
        if (!reciterIdentifier) return undefined;
        const surahNumPad = ayah.surah.number.toString().padStart(3, '0');
        const ayahNumPad = ayah.numberInSurah.toString().padStart(3, '0');
        return `https://everyayah.com/data/${reciterIdentifier}/${surahNumPad}${ayahNumPad}.mp3`;

        case 'islamic-network':
        if (!ayah.number) return undefined;
        return `https://cdn.islamic.network/quran/audio/128/${identifier}/${ayah.number}.mp3`;

        default:
        return undefined;
    }
};

// --- Juz Selection Modal ---
interface JuzSelectionModalProps {
    onClose: () => void;
    juzStartAyahs: { juz: number, ayahNumber: number }[];
    onJuzSelect: (ayahNumber: number) => void;
    onSelectionConfirm: (selectedJuzs: number[]) => void;
    mode: 'jump' | 'selection';
}

const JuzSelectionModal: React.FC<JuzSelectionModalProps> = ({ onClose, juzStartAyahs, onJuzSelect, onSelectionConfirm, mode }) => {
    const [selectedJuzs, setSelectedJuzs] = useState<number[]>([]);

    const handleJuzClick = (juz: number, ayahNumber: number) => {
        if (mode === 'jump') {
            onJuzSelect(ayahNumber);
            onClose();
        } else { // selection mode
            setSelectedJuzs(prev => 
                prev.includes(juz) ? prev.filter(j => j !== juz) : [...prev, juz]
            );
        }
    };

    const handleConfirm = () => {
        if (selectedJuzs.length > 0) {
            onSelectionConfirm(selectedJuzs.sort((a,b) => a-b));
            onClose();
        }
    };

    const title = mode === 'jump' ? "الانتقال إلى جزء" : "اختر الأجزاء";

    return (
        <div 
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center animate-fade-in p-4"
            onClick={onClose}
        >
            <div 
                className="bg-surface rounded-lg shadow-xl w-full max-w-lg mx-auto flex flex-col"
                onClick={e => e.stopPropagation()}
            >
                <div className="p-4 border-b border-border-default flex justify-between items-center">
                    <h2 className="text-xl font-bold text-text-primary">{title}</h2>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-surface-hover">
                        <ClearIcon className="w-5 h-5" />
                    </button>
                </div>
                <div className="p-4 overflow-y-auto max-h-[60vh]">
                    <div className="grid grid-cols-5 sm:grid-cols-6 gap-2">
                        {juzStartAyahs.map(({ juz, ayahNumber }) => {
                            const isSelected = mode === 'selection' && selectedJuzs.includes(juz);
                            return (
                                <button
                                    key={juz}
                                    onClick={() => handleJuzClick(juz, ayahNumber)}
                                    className={`p-3 rounded-lg text-center font-mono font-bold text-lg text-text-secondary transition-colors focus:outline-none focus:ring-2 focus:ring-primary
                                        bg-surface-subtle hover:bg-surface-hover
                                        ${isSelected ? 'ring-2 ring-primary bg-surface-active' : ''}
                                    `}
                                >
                                    {juz}
                                </button>
                            );
                        })}
                    </div>
                </div>
                {mode === 'selection' && (
                    <div className="p-4 border-t border-border-default">
                        <button 
                            onClick={handleConfirm}
                            disabled={selectedJuzs.length === 0}
                            className="w-full px-4 py-3 bg-primary text-white font-semibold rounded-md hover:bg-primary-hover disabled:bg-primary/50 transition-colors"
                        >
                            بدء القراءة ({selectedJuzs.length})
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

// --- Playback Mode Modal ---
interface PlaybackModeModalProps {
    onClose: () => void;
    onModeSelect: (mode: PlaybackMode) => void;
    onCustomSelectionStart: () => void;
}

const PlaybackModeModal: React.FC<PlaybackModeModalProps> = ({ onClose, onModeSelect, onCustomSelectionStart }) => {
    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center animate-fade-in p-4" onClick={onClose}>
            <div className="bg-surface rounded-lg shadow-xl w-full max-w-md mx-auto" onClick={e => e.stopPropagation()}>
                <div className="p-4 border-b border-border-default flex justify-between items-center">
                    <h2 className="text-xl font-bold text-text-primary">تحديد نطاق القراءة</h2>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-surface-hover"><ClearIcon className="w-5 h-5" /></button>
                </div>
                <div className="p-4 space-y-3">
                    <button onClick={() => { onModeSelect('continuous'); onClose(); }} className="w-full text-right p-4 flex items-center gap-4 bg-surface-subtle rounded-lg hover:bg-surface-hover transition-colors">
                        <BookOpenIcon className="w-8 h-8 text-primary flex-shrink-0"/>
                        <div>
                            <h3 className="font-bold text-lg text-primary-text">ختمة كاملة</h3>
                            <p className="text-sm text-text-muted">الاستمرار في القراءة من مكان وقوفك في المصحف كاملاً.</p>
                        </div>
                    </button>
                    <button onClick={() => { onModeSelect('single'); onClose(); }} className="w-full text-right p-4 flex items-center gap-4 bg-surface-subtle rounded-lg hover:bg-surface-hover transition-colors">
                        <JuzOneIcon className="w-8 h-8 text-primary flex-shrink-0"/>
                        <div>
                            <h3 className="font-bold text-lg text-primary-text">جزء واحد فقط</h3>
                            <p className="text-sm text-text-muted">قراءة الجزء الحالي فقط ثم التوقف تلقائياً.</p>
                        </div>
                    </button>
                    <button onClick={onCustomSelectionStart} className="w-full text-right p-4 flex items-center gap-4 bg-surface-subtle rounded-lg hover:bg-surface-hover transition-colors">
                        <QueueListIcon className="w-8 h-8 text-primary flex-shrink-0"/>
                        <div>
                            <h3 className="font-bold text-lg text-primary-text">تحديد أجزاء</h3>
                            <p className="text-sm text-text-muted">اختر أجزاء متتالية أو متفرقة للقراءة.</p>
                        </div>
                    </button>
                </div>
            </div>
        </div>
    );
};


// --- Main Component ---
const AudioKhatmiyahView: React.FC<AudioKhatmiyahViewProps> = ({
    allAyahs, allAudioEditions, initialAyahNumber, onSaveProgress,
    selectedAudioEdition, onAudioEditionChange, allQuranData, fetchCustomEditionData,
    fontSize,
    activeEditions, selectedEdition, onOpenSidePanel
}) => {
    const [currentAyahNumber, setCurrentAyahNumber] = useState(initialAyahNumber);
    const [currentAyah, setCurrentAyah] = useState<Ayah | null>(null);
    const [uthmaniText, setUthmaniText] = useState<string>('');
    const [displayedText, setDisplayedText] = useState<string>('');

    const [isPlaying, setIsPlaying] = useState(false);
    const [audioDuration, setAudioDuration] = useState(0);
    const [audioProgress, setAudioProgress] = useState(0);

    const [isLoading, setIsLoading] = useState(true);

    const [controlsVisible, setControlsVisible] = useState(true);
    const [isJuzSelectorOpen, setIsJuzSelectorOpen] = useState(false);
    const [isModeSelectorOpen, setIsModeSelectorOpen] = useState(false);

    // --- New State for Playback Modes ---
    const [playbackMode, setPlaybackMode] = useState<PlaybackMode>('continuous');
    const [playbackSelection, setPlaybackSelection] = useState<number[] | null>(null);
    const [juzModalMode, setJuzModalMode] = useState<'jump' | 'selection'>('jump');

    const audioRef = useRef<HTMLAudioElement>(null);

    const audioEditionDetails = useMemo(() => allAudioEditions.find(e => e.identifier === selectedAudioEdition), [selectedAudioEdition, allAudioEditions]);
    const displayEditionDetails = useMemo(() => activeEditions.find(e => e.identifier === selectedEdition), [activeEditions, selectedEdition]);

    const handleScreenTap = () => {
        // Only allow toggling visibility if the audio is playing.
        if (isPlaying) {
            setControlsVisible(prev => !prev);
        }
    };

    useEffect(() => {
        // When playback stops, controls must become visible.
        if (!isPlaying) {
            setControlsVisible(true);
        }
    }, [isPlaying]);

    const juzStartAyahs = useMemo(() => {
        if (!allAyahs || allAyahs.length === 0) return [];
        const juzMap = new Map<number, number>();
        for (const ayah of allAyahs) {
            if (ayah.juz && !juzMap.has(ayah.juz)) {
                juzMap.set(ayah.juz, ayah.number);
            }
        }
        return Array.from(juzMap.entries())
            .sort((a, b) => a[0] - b[0])
            .map(([juz, ayahNumber]) => ({ juz, ayahNumber }));
    }, [allAyahs]);

    const handleJuzSelect = (ayahNumber: number) => {
        setCurrentAyahNumber(ayahNumber);
        setIsJuzSelectorOpen(false);
        if (!isPlaying) setIsPlaying(true);
    };

    const handleSelectionConfirm = (selectedJuzs: number[]) => {
        if (selectedJuzs.length === 0) return;
        setPlaybackMode('selection');
        setPlaybackSelection(selectedJuzs);
        const startAyahNumber = juzStartAyahs.find(j => j.juz === selectedJuzs[0])?.ayahNumber;
        if (startAyahNumber) {
            setCurrentAyahNumber(startAyahNumber);
        }
        setIsJuzSelectorOpen(false);
        if (!isPlaying) setIsPlaying(true);
    };

    useEffect(() => {
        if (!allQuranData?.[selectedEdition]) {
            fetchCustomEditionData(selectedEdition);
        }
    }, [selectedEdition, allQuranData, fetchCustomEditionData]);

    useEffect(() => {
        const foundAyah = allAyahs.find(a => a.number === currentAyahNumber);
        if (foundAyah) {
            setCurrentAyah(foundAyah);
            const uthmaniData = allQuranData?.['quran-uthmani-quran-academy'];
            const uthmaniSurah = uthmaniData?.find(s => s.number === foundAyah.surah?.number);
            const uthmaniAyah = uthmaniSurah?.ayahs.find(a => a.numberInSurah === foundAyah.numberInSurah);
            setUthmaniText(uthmaniAyah?.text || foundAyah.text || '');

            const displayData = allQuranData?.[selectedEdition];
            const displaySurah = displayData?.find(s => s.number === foundAyah.surah?.number);
            const displayAyah = displaySurah?.ayahs.find(a => a.numberInSurah === foundAyah.numberInSurah);
            setDisplayedText(displayAyah?.text || foundAyah.text || '');
        }
    }, [currentAyahNumber, allAyahs, allQuranData, selectedEdition]);

    useEffect(() => {
        if (currentAyah && audioEditionDetails) {
            const url = getAudioUrl(currentAyah, audioEditionDetails);
            if (url && audioRef.current) {
                // If url is different or audio is ended/paused
                if (audioRef.current.src !== url) {
                    setIsLoading(true);
                    audioRef.current.src = url;
                    audioRef.current.load();
                    if (isPlaying) {
                        audioRef.current.play().catch(e => {
                            console.error("Play error", e);
                            setIsPlaying(false);
                        });
                    }
                }
            } else {
                setIsLoading(false);
            }
        }
    }, [currentAyah, audioEditionDetails, isPlaying]);

    const handleAudioEnded = () => {
        if (playbackMode === 'single') {
            setIsPlaying(false);
            return;
        }

        const nextNum = currentAyahNumber + 1;

        if (playbackMode === 'selection' && playbackSelection) {
             const nextAyah = allAyahs.find(a => a.number === nextNum);
             if (nextAyah && nextAyah.juz && playbackSelection.includes(nextAyah.juz)) {
                 setCurrentAyahNumber(nextNum);
                 onSaveProgress(nextNum);
             } else {
                 setIsPlaying(false);
             }
        } else {
             // Continuous
             if (nextNum <= 6236) {
                 setCurrentAyahNumber(nextNum);
                 onSaveProgress(nextNum);
             } else {
                 setIsPlaying(false);
             }
        }
    };

    const handleNext = () => {
        const nextNum = currentAyahNumber + 1;
        if (allAyahs.some(a => a.number === nextNum)) {
            setCurrentAyahNumber(nextNum);
            onSaveProgress(nextNum);
        }
    };

    const handlePrev = () => {
        const prevNum = currentAyahNumber - 1;
        if (prevNum > 0) {
            setCurrentAyahNumber(prevNum);
            onSaveProgress(prevNum);
        }
    };

    const handlePlayPause = () => {
        const audio = audioRef.current;
        if (!audio) return;

        if (isPlaying) {
            audio.pause();
            setIsPlaying(false);
        } else {
            audio.play().catch(console.error);
            setIsPlaying(true);
        }
    };

    return (
        <div className={`fixed inset-0 z-50 flex flex-col bg-background text-text-primary ${!controlsVisible ? 'cursor-none' : ''}`} onClick={handleScreenTap}>
            {/* Audio Element */}
            <audio
                ref={audioRef}
                onEnded={handleAudioEnded}
                onTimeUpdate={(e) => setAudioProgress(e.currentTarget.currentTime)}
                onDurationChange={(e) => setAudioDuration(e.currentTarget.duration)}
                onWaiting={() => isPlaying && setIsLoading(true)}
                onCanPlay={() => setIsLoading(false)}
                onPlay={() => setIsPlaying(true)}
                onPause={() => setIsPlaying(false)}
            />

            {/* Modals */}
            {isJuzSelectorOpen && (
                <JuzSelectionModal 
                    onClose={() => setIsJuzSelectorOpen(false)}
                    juzStartAyahs={juzStartAyahs}
                    onJuzSelect={handleJuzSelect}
                    onSelectionConfirm={handleSelectionConfirm}
                    mode={juzModalMode}
                />
            )}

            {isModeSelectorOpen && (
                <PlaybackModeModal 
                    onClose={() => setIsModeSelectorOpen(false)}
                    onModeSelect={(mode) => { setPlaybackMode(mode); setIsModeSelectorOpen(false); }}
                    onCustomSelectionStart={() => {
                        setIsModeSelectorOpen(false);
                        setJuzModalMode('selection');
                        setIsJuzSelectorOpen(true);
                    }}
                />
            )}

            {/* Top Bar */}
            <div className={`absolute top-0 left-0 right-0 p-4 flex justify-between items-start transition-transform duration-300 z-20 ${controlsVisible ? 'translate-y-0' : '-translate-y-full'}`} onClick={(e) => e.stopPropagation()}>
                <button onClick={onOpenSidePanel} className="p-2 bg-surface/80 backdrop-blur rounded-full shadow-sm hover:bg-surface-hover transition-colors">
                    <MenuIcon className="w-6 h-6" />
                </button>

                <div className="flex gap-2">
                     <button onClick={() => { setJuzModalMode('jump'); setIsJuzSelectorOpen(true); }} className="p-2 bg-surface/80 backdrop-blur rounded-full shadow-sm hover:bg-surface-hover transition-colors">
                        <QueueListIcon className="w-6 h-6" />
                    </button>
                    <button onClick={() => setIsModeSelectorOpen(true)} className="p-2 bg-surface/80 backdrop-blur rounded-full shadow-sm hover:bg-surface-hover transition-colors">
                        <CogIcon className="w-6 h-6" />
                    </button>
                </div>
            </div>

            {/* Main Content (Ayah Display) */}
            <div className="flex-grow flex flex-col justify-center items-center p-6 text-center space-y-8 animate-fade-in relative">
                {isLoading && (
                    <div className="absolute inset-0 flex items-center justify-center bg-background/50 z-10">
                        <SpinnerIcon className="w-12 h-12 text-primary" />
                    </div>
                )}

                <div className="max-w-3xl w-full space-y-6">
                    {/* Surah Info */}
                    {currentAyah && (
                        <div className={`text-sm text-text-muted transition-opacity duration-500 ${controlsVisible ? 'opacity-100' : 'opacity-50'}`}>
                            سورة {currentAyah.surah?.name} - الآية {currentAyah.numberInSurah} - الجزء {currentAyah.juz}
                        </div>
                    )}

                    {/* Uthmani Text */}
                    <p className={`font-quran leading-loose text-primary-text-strong transition-all duration-500 quran-text-${fontSize}`} dir="rtl">
                        {uthmaniText}
                    </p>

                    {/* Translation/Tafsir Text (if different and selected) */}
                    {displayedText && displayedText !== uthmaniText && (
                        <p className={`text-text-secondary text-lg leading-relaxed transition-all duration-500 ${controlsVisible ? 'opacity-100' : 'opacity-0'}`} dir={displayEditionDetails?.direction || 'rtl'}>
                            {displayedText}
                        </p>
                    )}
                </div>
            </div>

            {/* Bottom Controls */}
            <div className={`absolute bottom-0 left-0 right-0 p-6 bg-surface/90 backdrop-blur-md shadow-lg rounded-t-2xl transition-transform duration-300 z-20 ${controlsVisible ? 'translate-y-0' : 'translate-y-full'}`} onClick={(e) => e.stopPropagation()}>
                {/* Progress Bar */}
                <div className="w-full bg-surface-subtle h-1.5 rounded-full mb-6 overflow-hidden">
                    <div className="h-full bg-primary transition-all duration-100" style={{ width: `${(audioProgress / (audioDuration || 1)) * 100}%` }}></div>
                </div>

                <div className="flex flex-col gap-4">
                    {/* Player Controls */}
                    <div className="flex items-center justify-center gap-8">
                        <button onClick={handleNext} className="p-3 text-text-secondary hover:text-primary transition-colors">
                            <ForwardIcon className="w-8 h-8" />
                        </button>

                        <button 
                            onClick={handlePlayPause}
                            className="w-16 h-16 bg-primary text-white rounded-full flex items-center justify-center shadow-xl hover:scale-105 transition-transform"
                        >
                            {isLoading ? <SpinnerIcon className="w-8 h-8" /> : (isPlaying ? <PauseIcon className="w-8 h-8" /> : <PlayIcon className="w-8 h-8 ml-1" />)}
                        </button>

                        <button onClick={handlePrev} className="p-3 text-text-secondary hover:text-primary transition-colors">
                            <BackwardIcon className="w-8 h-8" />
                        </button>
                    </div>

                    {/* Audio Edition Selector */}
                    <div className="max-w-md mx-auto w-full">
                        <AudioEditionSelector 
                            audioEditions={allAudioEditions}
                            selectedAudioEdition={selectedAudioEdition}
                            onSelect={onAudioEditionChange}
                            size="sm"
                        />
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AudioKhatmiyahView;

