import React, { useState, useEffect, useMemo } from 'react';
import { AuthProvider } from './hooks/useAuth';
import { useTheme } from './hooks/useTheme';
import { useRouting } from './hooks/useRouting';
import { useQuranData } from './hooks/useQuranData';
import { useSettings } from './hooks/useSettings';
import { useAudioPlayer } from './hooks/useAudioPlayer';
import { useNotebook } from './hooks/useNotebook';
import { useRandomPattern } from './hooks/useRandomPattern';

import LoadingScreen from './components/LoadingScreen';
import SidePanel from './components/SidePanel';
import Toolbox from './components/Toolbox';
import AudioPlayerBar from './components/AudioPlayerBar';
import TopProgressBar from './components/TopProgressBar';
import ThemeToggleButton from './components/ThemeToggleButton';
import UpdateNotification from './components/UpdateNotification';
import SaveItemModal from './components/SaveItemModal';

// Views
import HomeView from './components/HomeView';
import SurahDetailView from './components/SurahDetailView';
import SearchView from './components/SearchView';
import SavedView from './components/SavedView';
import AudioKhatmiyahView from './components/AudioKhatmiyahView';
import KhatmiyahView from './components/KhatmiyahView';
import WordAnalysisView from './components/WordAnalysisView';
import CommentsCloudView from './components/CommentsCloudView';
import ManualView from './components/ManualView';
import PrivacyPolicyView from './components/PrivacyPolicyView';
import SettingsView from './components/SettingsView';
import AdminView from './components/AdminView';

// Types & Utils
import { normalizeArabicText } from './utils/text';

const AUDIO_KHATMIYAH_PROGRESS_KEY = 'qran_audio_khatmiyah_progress';

const AppContent: React.FC = () => {
    // Hooks
    const { theme } = useTheme();
    const patternStyle = useRandomPattern();
    const { currentPath, pathParts, queryParams } = useRouting();
    const { 
        allQuranData, isInitialLoading, isBackgroundLoading, loadingEditions, availableEditions,
        fetchCustomEditionData, getEditionUrl 
    } = useQuranData();
    const {
        fontSize, setFontSize,
        browsingMode, setBrowsingMode,
        activeEditions, selectedEdition, setSelectedEdition,
        selectedAudioEdition, setSelectedAudioEdition,
        handleAddEdition, handleDeleteEdition, displayEdition
    } = useSettings(availableEditions, fetchCustomEditionData);

    const {
        playbackInfo, currentlyPlayingAyahGlobalNumber, selectedAudioEditionDetails,
        handleStartPlayback, handlePlayPause, handleNext, handlePrev, handleClosePlayback,
        ALL_AUDIO_EDITIONS
    } = useAudioPlayer(currentPath, allQuranData, selectedAudioEdition, setSelectedAudioEdition, fetchCustomEditionData);

    const {
        collections, itemToSave, setItemToSave, handleSaveItem, handleConfirmSave,
        handleDeleteCollection, handleDeleteSavedItem, updateItemNotes,
        handleExportNotebook, handleImportNotebook
    } = useNotebook();

    // Local State
    const [isSidePanelOpen, setIsSidePanelOpen] = useState(false);
    const [updateAvailable, setUpdateAvailable] = useState(false);
    const [audioKhatmiyahProgress, setAudioKhatmiyahProgress] = useState<{ ayahNumber: number } | null>(() => {
        try {
            const stored = localStorage.getItem(AUDIO_KHATMIYAH_PROGRESS_KEY);
            return stored ? JSON.parse(stored) : null;
        } catch {
            return null;
        }
    });

    // Service Worker Update
    useEffect(() => {
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.addEventListener('controllerchange', () => {
                window.location.reload();
            });

            // Check for waiting worker
             navigator.serviceWorker.ready.then(registration => {
                 if (registration.waiting) setUpdateAvailable(true);
             });
        }
    }, []);

    const handleUpdate = () => {
        if ('serviceWorker' in navigator) {
            navigator.serviceWorker.ready.then(registration => {
                if (registration.waiting) {
                    registration.waiting.postMessage({ type: 'SKIP_WAITING' });
                }
            });
        }
    };

    const handleSaveAudioKhatmiyahProgress = (ayahNumber: number) => {
        const progress = { ayahNumber };
        setAudioKhatmiyahProgress(progress);
        localStorage.setItem(AUDIO_KHATMIYAH_PROGRESS_KEY, JSON.stringify(progress));
    };

    // Derived Data
    const simpleCleanData = allQuranData?.['quran-simple-clean'] || [];
    const displayEditionData = allQuranData?.[selectedEdition] || [];

    // Flattened ayahs for search/khatmiyah
    const simpleSearchableAyahs = useMemo(() => {
        if (simpleCleanData.length === 0) return [];
        return simpleCleanData.flatMap(s => s.ayahs.map(a => ({...a, surah: { number: s.number, name: s.name, englishName: s.englishName, englishNameTranslation: s.englishNameTranslation, revelationType: s.revelationType, numberOfAyahs: s.numberOfAyahs }})));
    }, [simpleCleanData]);

    // Data for Index
    const { surahList, juzList, hizbList } = useMemo(() => {
        if (simpleCleanData.length === 0) return { surahList: [], juzList: [], hizbList: [] };

        const surahs = simpleCleanData.map(({ ayahs, ...rest }) => ({...rest}));

        const juzMap = new Map();
        const hizbMap = new Map();

        simpleCleanData.forEach(surah => {
            surah.ayahs.forEach(ayah => {
                if (ayah.juz && !juzMap.has(ayah.juz)) {
                    juzMap.set(ayah.juz, { number: ayah.juz, startSurah: surah.number, startAyah: ayah.numberInSurah, startSurahName: surah.name });
                }
                if (ayah.hizbQuarter) {
                    const hizbNum = Math.floor((ayah.hizbQuarter - 1) / 4) + 1;
                    if (!hizbMap.has(hizbNum)) {
                        hizbMap.set(hizbNum, { number: hizbNum, startSurah: surah.number, startAyah: ayah.numberInSurah, startSurahName: surah.name });
                    }
                }
            });
        });

        return {
            surahList: surahs,
            juzList: Array.from(juzMap.values()),
            hizbList: Array.from(hizbMap.values())
        };
    }, [simpleCleanData]);

    const hizbQuarterStartMap = useMemo(() => {
        const map = new Map<number, number>();
        simpleCleanData.forEach(surah => {
            surah.ayahs.forEach(ayah => {
                if(ayah.hizbQuarter && !map.has(ayah.hizbQuarter)) {
                    map.set(ayah.hizbQuarter, ayah.number);
                }
            });
        });
        return map;
    }, [simpleCleanData]);


    if (isInitialLoading) {
        return <LoadingScreen />;
    }

    const renderContent = () => {
        const route = pathParts[0] || '';

        if (route === 'audio-khatmiyah') {
            return <AudioKhatmiyahView
                allAyahs={simpleSearchableAyahs}
                allAudioEditions={ALL_AUDIO_EDITIONS}
                initialAyahNumber={audioKhatmiyahProgress?.ayahNumber || 1}
                onSaveProgress={handleSaveAudioKhatmiyahProgress}
                selectedAudioEdition={selectedAudioEdition}
                onAudioEditionChange={setSelectedAudioEdition}
                allQuranData={allQuranData}
                fetchCustomEditionData={fetchCustomEditionData}
                fontSize={fontSize} onFontSizeChange={setFontSize}
                activeEditions={activeEditions} selectedEdition={selectedEdition} onEditionChange={setSelectedEdition}
                onOpenSidePanel={() => setIsSidePanelOpen(true)}
            />;
        }

        if (route === 'surah') {
            const surahId = parseInt(pathParts[1]);
            const surah = displayEditionData.find(s => s.number === surahId);
            const ayahParam = queryParams.get('ayah');
            const highlightAyah = ayahParam ? parseInt(ayahParam) : null;

            if (!surah) return <LoadingScreen />;

            return <SurahDetailView 
                surah={surah}
                highlightAyahNumber={highlightAyah}
                onWordClick={(word) => {
                    window.location.hash = `#/search/${encodeURIComponent(word)}`;
                }}
                displayEdition={displayEdition}
                fontSize={fontSize}
                browsingMode={browsingMode}
                onSaveAyah={handleSaveItem}
                onSearchByAyahNumber={(num) => window.location.hash = `#/search/${num}?type=number`}
                currentlyPlayingAyahGlobalNumber={currentlyPlayingAyahGlobalNumber}
                isPlaybackLoading={playbackInfo ? !playbackInfo.isPlaying && playbackInfo.playlist.length === 0 : false} 
                onStartPlayback={(ayahs, editionId, startIdx) => handleStartPlayback(ayahs.length ? ayahs : surah.ayahs, editionId, startIdx)}
                allAudioEditions={ALL_AUDIO_EDITIONS}
                selectedAudioEdition={selectedAudioEdition}
                onAudioEditionChange={setSelectedAudioEdition}
                simpleCleanData={simpleCleanData}
                hizbQuarterStartMap={hizbQuarterStartMap}
            />;
        }

        if (route === 'search') {
            const query = decodeURIComponent(pathParts[1] || '');
            const searchType = queryParams.get('type') === 'number' ? 'number' : 'text';

            let results: any[] = [];

            if (searchType === 'number') {
                const ayahNum = parseInt(query);
                if (!isNaN(ayahNum)) {
                    // Search in simpleCleanData to get global ayah results
                    simpleCleanData.forEach(surah => {
                        const ayah = surah.ayahs.find(a => a.numberInSurah === ayahNum);
                        if (ayah) {
                            results.push({
                                ...ayah,
                                surah: { number: surah.number, name: surah.name, englishName: surah.englishName, englishNameTranslation: surah.englishNameTranslation, revelationType: surah.revelationType }
                            });
                        }
                    });
                }
            } else {
                const normalizedQuery = normalizeArabicText(query);
                if (normalizedQuery) {
                    simpleCleanData.forEach(surah => {
                        surah.ayahs.forEach(ayah => {
                            if (normalizeArabicText(ayah.text).includes(normalizedQuery)) {
                                results.push({
                                    ...ayah,
                                    surah: { number: surah.number, name: surah.name, englishName: surah.englishName, englishNameTranslation: surah.englishNameTranslation, revelationType: surah.revelationType }
                                });
                            }
                        });
                    });
                }
            }

            return <SearchView 
                query={query}
                results={results}
                onNewSearch={(w) => window.location.hash = `#/search/${encodeURIComponent(w)}`}
                onSearchByAyahNumber={(n) => window.location.hash = `#/search/${n}?type=number`}
                onSearchComplete={() => {}}
                displayEdition={displayEdition}
                displayEditionData={displayEditionData}
                searchEdition={selectedEdition}
                fontSize={fontSize}
                simpleCleanData={simpleCleanData}
                onSaveAyah={handleSaveItem}
                onSaveSearch={handleSaveItem}
                searchType={searchType}
                currentlyPlayingAyahGlobalNumber={currentlyPlayingAyahGlobalNumber}
                isPlaybackLoading={false}
                onStartPlayback={handleStartPlayback}
                allAudioEditions={ALL_AUDIO_EDITIONS}
                selectedAudioEdition={selectedAudioEdition}
                onAudioEditionChange={setSelectedAudioEdition}
                autoOpenDiscussion={queryParams.get('from') === 'comments'}
            />;
        }

        if (route === 'saved') {
            const collectionId = pathParts[1] || null;
            return <SavedView 
                collections={collections}
                collectionId={collectionId}
                onDeleteCollection={handleDeleteCollection}
                onDeleteSavedItem={handleDeleteSavedItem}
                onUpdateNotes={updateItemNotes}
            />;
        }

        if (route === 'khatmiyah') {
            const khatmahId = pathParts[1] || null;
            return <KhatmiyahView khatmiyahId={khatmahId} />;
        }

        if (route === 'analysis') {
            const word = decodeURIComponent(pathParts[1] || '');
            return <WordAnalysisView simpleCleanData={simpleCleanData} initialWord={word} />;
        }

        if (route === 'comments') {
            return <CommentsCloudView />;
        }

        if (route === 'settings') {
            return <SettingsView 
                activeEditions={activeEditions}
                availableEditions={availableEditions}
                onAddEdition={handleAddEdition}
                onDeleteEdition={handleDeleteEdition}
                allQuranData={allQuranData}
                loadingEditions={loadingEditions}
                onExportNotebook={handleExportNotebook}
                onImportNotebook={handleImportNotebook}
                getEditionUrl={getEditionUrl}
            />;
        }

        if (route === 'manual') {
            return <ManualView />;
        }

        if (route === 'privacy-policy') {
            return <PrivacyPolicyView />;
        }

        if (route === 'admin') {
            return <AdminView />;
        }

        // Default: Home
        return <HomeView surahList={surahList} juzList={juzList} hizbList={hizbList} />;
    };

    return (
        <div className={`app-container ${theme} min-h-screen transition-colors duration-300 bg-background text-text-primary font-sans`} style={patternStyle}>
            <TopProgressBar isSearching={isBackgroundLoading || loadingEditions.length > 0} />

            {!currentPath.startsWith('#/audio-khatmiyah') && (
                <div className="fixed top-4 left-4 z-30 flex flex-col gap-2">
                    <button onClick={() => setIsSidePanelOpen(true)} className="p-3 bg-surface rounded-full shadow-md text-text-secondary hover:text-primary transition-colors">
                        <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-6 h-6">
                            <path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" />
                        </svg>
                    </button>
                    <ThemeToggleButton />
                </div>
            )}

            <SidePanel 
                isOpen={isSidePanelOpen} 
                onClose={() => setIsSidePanelOpen(false)}
                currentPath={currentPath}
                onNavigate={(path) => { window.location.hash = path; setIsSidePanelOpen(false); }}
            />

            <div className={`pt-20 pb-32 ${currentPath.startsWith('#/audio-khatmiyah') ? 'pt-0 pb-0' : ''}`}>
                {renderContent()}
            </div>

            {!currentPath.startsWith('#/audio-khatmiyah') && (
                <Toolbox 
                    fontSize={fontSize}
                    onFontSizeChange={setFontSize}
                    activeEditions={activeEditions}
                    selectedEdition={selectedEdition}
                    onEditionChange={setSelectedEdition}
                    isAudioPlayerVisible={!!playbackInfo}
                    browsingMode={browsingMode}
                    onBrowsingModeChange={setBrowsingMode}
                />
            )}

            {playbackInfo && (
                <AudioPlayerBar 
                    playlist={playbackInfo.playlist}
                    currentIndex={playbackInfo.currentIndex}
                    isPlaying={playbackInfo.isPlaying}
                    isLoading={!playbackInfo.playlist[playbackInfo.currentIndex]?.audio}
                    onPlayPause={handlePlayPause}
                    onNext={handleNext}
                    onPrev={handlePrev}
                    onEnded={handleNext}
                    onClose={handleClosePlayback}
                    audioEdition={selectedAudioEditionDetails}
                />
            )}

            {updateAvailable && <UpdateNotification onUpdate={handleUpdate} />}

            {itemToSave && (
                <SaveItemModal 
                    item={itemToSave}
                    collections={collections}
                    onClose={() => setItemToSave(null)}
                    onSave={handleConfirmSave}
                />
            )}
        </div>
    );
};

const App: React.FC = () => {
    return (
        <AuthProvider>
            <AppContent />
        </AuthProvider>
    );
};

