interface SettingsViewProps {
    allAvailableFonts: QuranFont[];
    selectedFont: string;
    onFontChange: (fontFamily: string) => void;
    onExportNotebook: () => Promise<string>;
    onImportNotebook: (code: string) => Promise<void>;
}

const SettingsView: React.FC<SettingsViewProps> = ({ 
    allAvailableFonts, selectedFont, onFontChange,
    onExportNotebook, onImportNotebook
}) => {
    type Tab = 'fonts' | 'tadabbur' | 'export_format' | 'api_key';
    const [activeTab, setActiveTab] = useState<Tab>('fonts');
    const [showSuccessToast, setShowSuccessToast] = useState(false);

    useEffect(() => {
        const params = new URLSearchParams(window.location.hash.split('?')[1]);
        const tabParam = params.get('tab');
        if (tabParam === 'tadabbur' || tabParam === 'fonts' || tabParam === 'export_format' || tabParam === 'api_key') {
            setActiveTab(tabParam as Tab);
        }
    }, [window.location.hash]);


    const handleFontSelect = (fontFamily: string) => {
        onFontChange(fontFamily);
        setShowSuccessToast(true);
        setTimeout(() => {
            setShowSuccessToast(false);
