import React, { useState, useEffect, useRef } from 'react';
import type { QuranFont, QuranEdition, FontSize, BrowsingMode } from '../types';
import { ArrowLeftIcon, ArrowRightIcon, HomeIcon, TextSizeIcon, PlusIcon, MinusIcon, SparklesIcon, BookOpenIcon, CheckIcon, DocumentDuplicateIcon, QueueListIcon } from './icons';

interface ToolboxProps {
    // Font Size
    fontSize: FontSize;
    onFontSizeChange: (size: FontSize) => void;
    // Editions
    activeEditions: QuranEdition[];
    selectedEdition: string;
    onEditionChange: (id: string) => void;
    isAudioPlayerVisible: boolean;
    // Browsing Mode
    browsingMode: BrowsingMode;
    onBrowsingModeChange: (mode: BrowsingMode) => void;
}

const Toolbox: React.FC<ToolboxProps> = ({
    fontSize, onFontSizeChange,
    activeEditions, selectedEdition, onEditionChange,
    isAudioPlayerVisible,
    browsingMode, onBrowsingModeChange
}) => {
    type Popover = 'size' | 'edition';
    const [openPopover, setOpenPopover] = useState<Popover | null>(null);
    const [isShown, setIsShown] = useState(true);
    const popoverRef = useRef<HTMLDivElement>(null);
    const lastScrollY = useRef(0);

    // Effect to handle toolbox visibility on scroll
    useEffect(() => {
        const handleScroll = () => {
            const currentScrollY = window.scrollY;
            const scrollThreshold = 20;

            // Do nothing if scroll change is insignificant
            if (Math.abs(currentScrollY - lastScrollY.current) < scrollThreshold) {
                return;
            }

            if (currentScrollY < 100) { // Always show near the top
                setIsShown(true);
            } else if (currentScrollY > lastScrollY.current) { // Scrolling down
                setIsShown(false);
                setOpenPopover(null); // Hide popovers when toolbar hides
            } else { // Scrolling up
                setIsShown(true);
            }
            lastScrollY.current = currentScrollY;
        };

        window.addEventListener('scroll', handleScroll, { passive: true });
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    // Close popover on outside click
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (popoverRef.current && !popoverRef.current.contains(event.target as Node)) {
                setOpenPopover(null);
            }
        };
        if (openPopover) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [openPopover]);

    const handleTogglePopover = (popover: Popover) => {
        setOpenPopover(prev => (prev === popover ? null : popover));
    };

    const handleSelectAndClose = (setter: (value: string) => void) => (event: React.MouseEvent<HTMLButtonElement>) => {
        setter(event.currentTarget.value);
        setOpenPopover(null);
    };

    const ToolButton: React.FC<{ onClick: () => void; label: string; children: React.ReactNode; isActive?: boolean }> = ({ onClick, label, children, isActive }) => (
        <button
            onClick={onClick}
            aria-label={label}
            title={label}
            className={`p-3 rounded-full transition-colors ${isActive ? 'bg-surface-active text-primary-text-strong' : 'text-text-muted hover:bg-surface-hover'}`}
        >
            {children}
        </button>
    );

    const PopoverContainer: React.FC<{ children: React.ReactNode; popoverId: Popover, title: string, widthClass?: string }> = ({ children, popoverId, title, widthClass = 'w-72' }) => (
        openPopover === popoverId ? (
            <div ref={popoverRef} className={`absolute bottom-full left-1/2 -translate-x-1/2 mb-3 ${widthClass} bg-surface rounded-lg shadow-2xl ring-1 ring-black/5 animate-fade-in`}
                role="dialog" aria-labelledby={`${popoverId}-title`}>
                <div className="p-3 border-b border-border-default">
                    <h3 id={`${popoverId}-title`} className="font-semibold text-text-primary">{title}</h3>
                </div>
                <div className="p-3 max-h-64 overflow-y-auto">
                    {children}
                </div>
                <div className={`absolute left-1/2 -translate-x-1/2 bottom-[-8px] w-4 h-4 bg-surface rotate-45 -z-10`}></div>
            </div>
        ) : null
    );

    return (
        <div className={`fixed left-1/2 -translate-x-1/2 z-20 transition-all duration-300 ${isAudioPlayerVisible ? 'bottom-28' : 'bottom-8'}`}>
            <div className={`relative flex items-center gap-1 bg-surface/80 backdrop-blur-md p-2 rounded-full shadow-lg border border-border-default transition-all duration-300 ${
                isShown ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-16 pointer-events-none'
            }`}>

                {/* Navigation Group */}
                <ToolButton onClick={() => window.history.back()} label="الخلف"><ArrowRightIcon className="w-5 h-5" /></ToolButton>
                <ToolButton onClick={() => window.location.hash = '#/'} label="الرئيسية"><HomeIcon className="w-5 h-5" /></ToolButton>
                <ToolButton onClick={() => window.history.forward()} label="الأمام"><ArrowLeftIcon className="w-5 h-5" /></ToolButton>

                <div className="h-6 w-px bg-border-default mx-2"></div>

                {/* Settings Group */}
                <div className="relative">
                    <ToolButton onClick={() => handleTogglePopover('size')} label="حجم الخط" isActive={openPopover === 'size'}>
                        <TextSizeIcon className="w-5 h-5" />
                    </ToolButton>
                    <PopoverContainer popoverId="size" title="تغيير حجم الخط" widthClass="w-auto">
                        <div className="flex items-center justify-center gap-2">
                            <button
                                onClick={() => onFontSizeChange('sm')}
                                className={`p-3 w-16 h-12 flex items-center justify-center rounded-lg transition-colors ${fontSize === 'sm' ? 'bg-surface-active text-primary-text-strong' : 'bg-surface-subtle hover:bg-surface-hover'}`}
                                aria-pressed={fontSize === 'sm'}
                                title="صغير"
                            >
                                <span className="text-sm font-bold">A</span>
                            </button>
                            <button
                                onClick={() => onFontSizeChange('md')}
                                className={`p-3 w-16 h-12 flex items-center justify-center rounded-lg transition-colors ${fontSize === 'md' ? 'bg-surface-active text-primary-text-strong' : 'bg-surface-subtle hover:bg-surface-hover'}`}
                                aria-pressed={fontSize === 'md'}
                                title="متوسط"
                            >
                                <span className="text-lg font-bold">A</span>
                            </button>
                            <button
                                onClick={() => onFontSizeChange('lg')}
                                className={`p-3 w-16 h-12 flex items-center justify-center rounded-lg transition-colors ${fontSize === 'lg' ? 'bg-surface-active text-primary-text-strong' : 'bg-surface-subtle hover:bg-surface-hover'}`}
                                aria-pressed={fontSize === 'lg'}
                                title="كبير"
                            >
                                <span className="text-xl font-bold">A</span>
                            </button>
                        </div>
                    </PopoverContainer>
                </div>

                 <div className="relative">
                    <ToolButton onClick={() => handleTogglePopover('edition')} label="تغيير المصحف" isActive={openPopover === 'edition'}>
                        <BookOpenIcon className="w-5 h-5" />
                    </ToolButton>
                     <PopoverContainer popoverId="edition" title="اختر نسخة العرض">
                        <div className="space-y-1">
                            {activeEditions.map(edition => (
                                <button key={edition.identifier} onClick={handleSelectAndClose(onEditionChange)} value={edition.identifier}
                                    className="w-full text-right p-2 rounded-md flex justify-between items-center text-text-primary hover:bg-surface-hover transition-colors">
                                    <span>{edition.name}</span>
                                    {selectedEdition === edition.identifier && <CheckIcon className="w-5 h-5 text-primary" />}
                                </button>
                            ))}
                        </div>
                    </PopoverContainer>
                </div>

                <div className="h-6 w-px bg-border-default mx-2"></div>

                {/* Browsing Mode Group */}
                <ToolButton
                    onClick={() => onBrowsingModeChange(browsingMode === 'full' ? 'page' : 'full')}
                    label={browsingMode === 'full' ? 'التحويل إلى عرض الصفحات' : 'التحويل إلى العرض الكامل'}
                >
                    {browsingMode === 'full' ? <DocumentDuplicateIcon className="w-5 h-5" /> : <QueueListIcon className="w-5 h-5" />}
                </ToolButton>

            </div>
        </div>
    );
};

export default Toolbox;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import type { SurahData, QuranEdition, QuranFont, SavedAyahItem, Ayah, FontSize, BrowsingMode } from '../types';
import { PlayIcon, SpinnerIcon, ArrowLeftIcon, ArrowRightIcon } from './icons';
import AudioEditionSelector from './AudioEditionSelector';
import AyahActionPopover from './AyahActionPopover';
import AyahRenderer from './AyahRenderer';
import { formatSurahNameForDisplay, normalizeArabicText } from '../utils/text';

interface SurahDetailViewProps {
  surah: SurahData;
  highlightAyahNumber: number | null;
  onWordClick: (query: string, editionIdentifier: string, position: { surah: number; ayah: number; wordIndex: number; }) => void;
  displayEdition: QuranEdition;
  fontSize: FontSize;
  browsingMode: BrowsingMode;
  onSaveAyah: (item: SavedAyahItem) => void;
  onSearchByAyahNumber: (ayahNumber: number) => void;
  // --- Props for audio playback ---
  currentlyPlayingAyahGlobalNumber: number | null;
  isPlaybackLoading: boolean;
  onStartPlayback: (ayahs: Ayah[], audioEditionIdentifier: string, startIndex?: number) => void;
  allAudioEditions: QuranEdition[];
  selectedAudioEdition: string;
  onAudioEditionChange: (identifier: string) => void;
  // --- Prop for word popover ---
  simpleCleanData: SurahData[];
  hizbQuarterStartMap: Map<number, number>;
}

const SurahDetailView: React.FC<SurahDetailViewProps> = ({ 
  surah, highlightAyahNumber, onWordClick, displayEdition, fontSize, browsingMode,
  onSaveAyah, onSearchByAyahNumber,
  currentlyPlayingAyahGlobalNumber, isPlaybackLoading, onStartPlayback,
  allAudioEditions, selectedAudioEdition, onAudioEditionChange,
  simpleCleanData, hizbQuarterStartMap
}) => {
  const highlightRef = useRef<HTMLSpanElement>(null);
  const playingAyahRef = useRef<HTMLSpanElement>(null);
  const wordPopoverRef = useRef<HTMLDivElement>(null);

  const [activePopover, setActivePopover] = useState<{ ayah: Ayah; triggerElement: HTMLElement } | null>(null);
  const [copiedAyah, setCopiedAyah] = useState<number | null>(null);
  const [currentPage, setCurrentPage] = useState<number>(1);

  const [wordPopoverState, setWordPopoverState] = useState<{
    ayahNumberInSurah: number;
    simpleText: string;
    triggerElement: HTMLElement;
  } | null>(null);

  const [touchStartX, setTouchStartX] = useState<number | null>(null);
  const [touchCurrentX, setTouchCurrentX] = useState<number | null>(null);

  const prevSurahNumber = useRef<number | null>(null);

  const { ayahsByPage, firstPage, lastPage, getPageForAyahNumber } = useMemo(() => {
    const map = new Map<number, Ayah[]>();
    const ayahNumToPageMap = new Map<number, number>();
    if (!surah || !surah.ayahs || surah.ayahs.length === 0) {
        return { ayahsByPage: map, firstPage: 1, lastPage: 1, getPageForAyahNumber: (n: number) => undefined };
    }
    let minPage = Infinity;
    let maxPage = -Infinity;
    for (const ayah of surah.ayahs) {
        if (ayah.page) {
            if (!map.has(ayah.page)) {
                map.set(ayah.page, []);
            }
            map.get(ayah.page)!.push(ayah);
            minPage = Math.min(minPage, ayah.page);
            maxPage = Math.max(maxPage, ayah.page);
            ayahNumToPageMap.set(ayah.numberInSurah, ayah.page);
        }
    }
    const getPageForAyahNumber = (num: number) => ayahNumToPageMap.get(num);
    return { ayahsByPage: map, firstPage: minPage === Infinity ? 1 : minPage, lastPage: maxPage === -Infinity ? 1 : maxPage, getPageForAyahNumber };
  }, [surah]);

  useEffect(() => {
    let targetPage: number | undefined;

    if (highlightAyahNumber) {
        targetPage = getPageForAyahNumber(highlightAyahNumber);
    } else if (currentlyPlayingAyahGlobalNumber) {
        const playingAyah = surah.ayahs.find(a => a.number === currentlyPlayingAyahGlobalNumber);
        if (playingAyah) {
            targetPage = getPageForAyahNumber(playingAyah.numberInSurah);
        }
    }

    setCurrentPage(targetPage || firstPage);
  }, [surah.number, highlightAyahNumber, currentlyPlayingAyahGlobalNumber, getPageForAyahNumber, firstPage]);


  useEffect(() => {
    const currentSurahNumber = surah.number;
    const isNewSurahView = prevSurahNumber.current !== currentSurahNumber;

    if (isNewSurahView) {
        prevSurahNumber.current = currentSurahNumber;
    }

    let elementToScroll: HTMLElement | null = null;
    let shouldPulse = false;

    if (currentlyPlayingAyahGlobalNumber !== null && surah.ayahs.some(a => a.number === currentlyPlayingAyahGlobalNumber)) {
        elementToScroll = playingAyahRef.current;
        shouldPulse = false;
    }
    else if (isNewSurahView && highlightAyahNumber) {
        elementToScroll = highlightRef.current;
        shouldPulse = true;
    }

    if (elementToScroll) {
        const scrollTimer = setTimeout(() => {
            elementToScroll?.scrollIntoView({
                behavior: 'smooth',
                block: 'center',
            });

            if (shouldPulse) {
                elementToScroll?.classList.add('animate-highlight-pulse');
                setTimeout(() => {
                    elementToScroll?.classList.remove('animate-highlight-pulse');
                }, 3000);
            }
        }, 150); // Delay to allow page transition to finish

        return () => clearTimeout(scrollTimer);
    } else if (isNewSurahView && browsingMode === 'full') {
        window.scrollTo(0, 0);
    }
  }, [highlightAyahNumber, currentlyPlayingAyahGlobalNumber, surah.number, browsingMode, currentPage]);


  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        const target = event.target as Node;
        if (!(target as HTMLElement).closest('.popover-trigger, .popover-content')) {
            setActivePopover(null);
        }
        if (wordPopoverRef.current && !wordPopoverRef.current.contains(target)) {
            if (!(event.target as HTMLElement).closest('.word-trigger')) {
                setWordPopoverState(null);
            }
        }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
        document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handlePlaySurah = () => {
    onStartPlayback([], selectedAudioEdition);
  };

  if (displayEdition.format === 'audio') {
    return (
      <div className="animate-fade-in w-full max-w-4xl mx-auto px-4">
        <main className="bg-surface p-6 sm:p-8 rounded-lg shadow-md transition-colors duration-300">
          <h3 className="text-xl font-bold mb-4 text-center text-primary-text">{displayEdition.name}</h3>
          <div className="flex flex-col gap-2">
            {surah.ayahs.map(ayah => (
              ayah.audio ? (
                <div key={ayah.number} className="flex items-center gap-4 py-2 px-3 my-1 bg-surface-subtle rounded-lg">
                  <span className="font-bold text-primary-text">الآية {ayah.numberInSurah}</span>
                  <audio
                    controls
                    src={ayah.audio}
                    className="w-full h-10"
                    preload="metadata"
                    title={`الاستماع للآية ${ayah.numberInSurah}`}
                  >
                    متصفحك لا يدعم عنصر الصوت.
                  </audio>
                </div>
              ) : null
            ))}
          </div>
        </main>
      </div>
    );
  }

  const getQuranTextStyle = () => {
    const isImlaei = displayEdition.identifier.includes('simple-clean');

    if (displayEdition.type === 'quran' && displayEdition.direction === 'rtl') {
      return {
        className: `${isImlaei ? 'imlai-font' : 'uthmani-font'} quran-text-${fontSize}`,
      };
    }

    return { className: 'font-quran text-2xl' };
  }

  const { className: quranTextClass } = getQuranTextStyle();

  const handleSaveClick = (ayah: Ayah) => {
    onSaveAyah({
      type: 'ayah',
      id: `${ayah.surah?.number || surah.number}:${ayah.numberInSurah}`,
      surah: ayah.surah?.number || surah.number,
      ayah: ayah.numberInSurah,
      text: ayah.text || '',
      createdAt: Date.now(),
    });
    setActivePopover(null);
  };

  const handleCopyAyah = (ayah: Ayah) => {
    const surahName = ayah.surah?.name || surah.name;
    const cleanSurahName = formatSurahNameForDisplay(surahName);
    const textToCopy = `"${ayah.text || ''}" (سورة ${cleanSurahName} - الآية ${ayah.numberInSurah})`;
    navigator.clipboard.writeText(textToCopy).then(() => {
        setCopiedAyah(ayah.number);
        setTimeout(() => setCopiedAyah(null), 2000);
        setActivePopover(null);
    });
  };

  const handleSearchByAyahText = (ayah: Ayah) => {
    const simpleSurah = simpleCleanData.find(s => s.number === (ayah.surah?.number || surah.number));
    const simpleAyah = simpleSurah?.ayahs.find(a => a.numberInSurah === ayah.numberInSurah);
    const simpleTextToSearch = simpleAyah?.text;

    if (simpleTextToSearch) {
        onWordClick(simpleTextToSearch, 'quran-simple-clean', { surah: surah.number, ayah: ayah.numberInSurah, wordIndex: 0 });
    } else if (ayah.text) {
        onWordClick(ayah.text, displayEdition.identifier, { surah: surah.number, ayah: ayah.numberInSurah, wordIndex: 0 });
    }
    setActivePopover(null);
  };

  const handlePlayFromAyah = (ayah: Ayah) => {
    const startIndex = surah.ayahs.findIndex(a => a.numberInSurah === ayah.numberInSurah);
    if (startIndex !== -1) {
        onStartPlayback([], selectedAudioEdition, startIndex);
    }
    setActivePopover(null);
  };

  const handleNextPage = () => {
    setCurrentPage(p => {
        const nextPage = p < lastPage ? p + 1 : p;
        if (nextPage !== p) window.scrollTo({ top: 0, behavior: 'smooth' });
        return nextPage;
    });
  };

  const handlePrevPage = () => {
      setCurrentPage(p => {
          const prevPage = p > firstPage ? p - 1 : p;
          if (prevPage !== p) window.scrollTo({ top: 0, behavior: 'smooth' });
          return prevPage;
      });
  };

  const SWIPE_THRESHOLD = 50;

  const handleTouchStart = (e: React.TouchEvent) => {
      if (browsingMode !== 'page') return;
      setTouchStartX(e.targetTouches[0].clientX);
      setTouchCurrentX(e.targetTouches[0].clientX);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      if (touchStartX === null || browsingMode !== 'page') return;
      setTouchCurrentX(e.targetTouches[0].clientX);
  };

  const handleTouchEnd = () => {
      if (touchStartX === null || touchCurrentX === null || browsingMode !== 'page') return;

      const deltaX = touchStartX - touchCurrentX;

      if (Math.abs(deltaX) > SWIPE_THRESHOLD) {
          if (deltaX > 0) { 
              if (currentPage < lastPage) {
                  handleNextPage();
              }
          } else { 
              if (currentPage > firstPage) {
                  handlePrevPage();
              }
          }
      }

      setTouchStartX(null);
      setTouchCurrentX(null);
  };

  const swipeTranslateX = useMemo(() => {
      if (touchStartX === null || touchCurrentX === null || browsingMode !== 'page') {
          return 0;
      }
      const deltaX = touchCurrentX - touchStartX;

      if ((deltaX < 0 && currentPage >= lastPage) || (deltaX > 0 && currentPage <= firstPage)) {
          return deltaX / 3;
      }
      return deltaX;
  }, [touchStartX, touchCurrentX, browsingMode, currentPage, firstPage, lastPage]);

  const ayahsToRender = useMemo(() => browsingMode === 'page'
      ? (ayahsByPage.get(currentPage) || [])
      : surah.ayahs, [browsingMode, ayahsByPage, currentPage, surah.ayahs]);

  const pageInfo = useMemo(() => {
    if (browsingMode !== 'page' || !hizbQuarterStartMap || ayahsToRender.length === 0) return null;

    const firstAyah = ayahsToRender[0];
    let surahName = firstAyah.surah?.name || surah.name;
    surahName = surahName.replace(/^سُورَةُ\s*/, '').trim();

    const juzNumber = firstAyah.juz;
    const hizbNumber = firstAyah.hizbQuarter ? Math.floor((firstAyah.hizbQuarter - 1) / 4) + 1 : null;

    const markers: {label: string}[] = [];
    const processedQuarters = new Set<number>();

    if (hizbNumber) {
        const startOfHizbQuarter = (hizbNumber - 1) * 4 + 1;
        if(hizbQuarterStartMap.get(startOfHizbQuarter) === firstAyah.number) {
            markers.push({ label: `الحزب ${hizbNumber}`});
        }
    }

    for(const ayah of ayahsToRender) {
        if(ayah.hizbQuarter && hizbQuarterStartMap.get(ayah.hizbQuarter) === ayah.number) {
            if (processedQuarters.has(ayah.hizbQuarter)) continue;

            const quarterType = (ayah.hizbQuarter - 1) % 4;
            if (quarterType === 1) markers.push({ label: 'ربع الحزب'});
            else if (quarterType === 2) markers.push({ label: 'نصف الحزب'});
            else if (quarterType === 3) markers.push({ label: 'ثلاثة أرباع الحزب'});

            processedQuarters.add(ayah.hizbQuarter);
        }
    }

    return {
        surahName,
        juzNumber,
        markers,
        side: currentPage % 2 === 0 ? 'left' : 'right'
    };
  }, [currentPage, browsingMode, ayahsToRender, hizbQuarterStartMap, surah.name]);

  const bismillahInfo = useMemo(() => {
    const isApplicable = surah.number !== 1 && surah.number !== 9 && 
                         displayEdition.type === 'quran' && displayEdition.direction === 'rtl' &&
                         (browsingMode === 'full' || currentPage === firstPage);

    if (!isApplicable || ayahsToRender.length === 0) return null;

    const firstAyah = ayahsToRender[0];
    if (!firstAyah.text) return null;

    const normalizedText = normalizeArabicText(firstAyah.text);
    const NORMALIZED_BISMILLAH = 'بسم الله الرحمن الرحيم';

    if (normalizedText.startsWith(NORMALIZED_BISMILLAH)) {
        const uthmaniTerminator = 'ٱلرَّحِيمِ';
        const simpleTerminator = 'الرحيم';
        let bismillahPart = '';
        let restOfAyahPart = '';

        const uthmaniIndex = firstAyah.text.indexOf(uthmaniTerminator);
        if (uthmaniIndex > -1 && uthmaniIndex < 35) {
            const splitPoint = uthmaniIndex + uthmaniTerminator.length;
            bismillahPart = firstAyah.text.substring(0, splitPoint);
            restOfAyahPart = firstAyah.text.substring(splitPoint);
        } else {
            const simpleIndex = firstAyah.text.indexOf(simpleTerminator);
            if (simpleIndex > -1 && simpleIndex < 35) {
                const splitPoint = simpleIndex + simpleTerminator.length;
                bismillahPart = firstAyah.text.substring(0, splitPoint);
                restOfAyahPart = firstAyah.text.substring(splitPoint);
            }
        }

        if (bismillahPart && restOfAyahPart.trim()) {
            return {
                bismillah: bismillahPart.trim(),
                restOfAyah: restOfAyahPart.trim()
            };
        } else if (bismillahPart && !restOfAyahPart.trim()) {
            return null;
        }
    }

    return null;
  }, [surah.number, displayEdition, browsingMode, currentPage, firstPage, ayahsToRender]);

  return (
    <div className="animate-fade-in w-full max-w-4xl mx-auto px-4">
      {displayEdition.type === 'quran' && displayEdition.direction === 'rtl' && (
        <div className="w-full max-w-4xl mx-auto mb-4 flex items-stretch justify-center gap-3">
            <div className="flex-grow">
                <AudioEditionSelector
                    audioEditions={allAudioEditions}
                    selectedAudioEdition={selectedAudioEdition}
                    onSelect={onAudioEditionChange}
                />
            </div>
            <button
                onClick={handlePlaySurah}
                disabled={isPlaybackLoading || allAudioEditions.length === 0}
                className="flex items-center gap-3 px-6 py-3 bg-surface border-2 border-primary text-primary-text rounded-lg shadow-sm hover:shadow-md hover:bg-surface-hover transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary disabled:opacity-60 disabled:cursor-not-allowed flex-shrink-0"
                aria-label="استماع للسورة"
            >
                {isPlaybackLoading ? <SpinnerIcon className="w-6 h-6"/> : <PlayIcon className="w-6 h-6"/>}
                <span className="text-lg font-semibold hidden sm:inline">{isPlaybackLoading ? 'جاري التحضير...' : 'استماع'}</span>
            </button>
        </div>
      )}
      <div className="overflow-hidden rounded-lg">
        {browsingMode === 'page' && !displayEdition.identifier.includes('simple-clean') ? (
             <div
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                onTouchEnd={handleTouchEnd}
                style={{
                    transform: `translateX(${swipeTranslateX}px)`,
                    transition: touchStartX === null ? 'transform 0.3s ease-out' : 'none',
                }}
             >
                <div className="mushaf-page" style={{ touchAction: 'pan-y' }}>
                    {pageInfo?.markers.map((marker, index) => (
                         <div key={index} className={`hizb-marker ${pageInfo.side}`}>{marker.label}</div>
                    ))}
                    <header className="mushaf-header">
                        <span>{pageInfo?.juzNumber && `الجزء ${pageInfo.juzNumber}`}</span>
                        <span>{pageInfo?.surahName && `سورة ${pageInfo.surahName}`}</span>
                    </header>

                    {bismillahInfo && (
                        <div className="text-center mb-8 font-bismillah text-2xl text-primary-text-strong">
                            {bismillahInfo.bismillah}
                        </div>
                    )}
                    <main dir={displayEdition.direction} className={`text-text-primary ${quranTextClass} text-justify`}>
                        <AyahRenderer {...{ ayahsToRender, surah, highlightAyahNumber, onWordClick, displayEdition, fontSize, browsingMode, currentlyPlayingAyahGlobalNumber, simpleCleanData, wordPopoverState, setWordPopoverState, setActivePopover, playingAyahRef, highlightRef }} firstAyahInfo={bismillahInfo} />
                    </main>

                    <footer className="mushaf-footer">
                        <span>{currentPage}</span>
                    </footer>
                </div>
            </div>
        ) : (
            <main
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                onTouchEnd={handleTouchEnd}
                style={{
                    transform: `translateX(${swipeTranslateX}px)`,
                    transition: touchStartX === null ? 'transform 0.3s ease-out' : 'none',
                    touchAction: browsingMode === 'page' ? 'pan-y' : 'auto',
                }}
                className={`bg-surface p-6 sm:p-8 rounded-lg shadow-md transition-colors duration-300 ${browsingMode === 'page' ? 'cursor-grab active:cursor-grabbing' : ''}`}
            >
                {browsingMode === 'page' && lastPage > firstPage && (
                    <div className="text-center mb-6 -mt-2">
                        <span className="font-mono text-sm font-semibold text-text-muted select-none">
                            {currentPage}
                        </span>
                    </div>
                )}
                {bismillahInfo && (
                    <div className="text-center mb-8 font-bismillah text-2xl text-primary-text-strong">
                        {bismillahInfo.bismillah}
                    </div>
                )}
                <div dir={displayEdition.direction} className={`text-text-primary ${quranTextClass} ${displayEdition.direction === 'ltr' ? 'text-left' : 'text-right'}`}>
                     <AyahRenderer {...{ ayahsToRender, surah, highlightAyahNumber, onWordClick, displayEdition, fontSize, browsingMode, currentlyPlayingAyahGlobalNumber, simpleCleanData, wordPopoverState, setWordPopoverState, setActivePopover, playingAyahRef, highlightRef }} firstAyahInfo={bismillahInfo} />
                </div>
            </main>
        )}
      </div>

      {browsingMode === 'page' && lastPage > firstPage && (
          <div className="mt-6 flex items-center justify-between p-2 bg-surface rounded-full shadow-md border border-border-default">
              <button 
                  onClick={handlePrevPage} 
                  disabled={currentPage <= firstPage}
                  className="flex items-center gap-2 px-4 py-2 rounded-full text-text-secondary hover:bg-surface-hover disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                  <ArrowRightIcon className="w-5 h-5" />
                  <span className="font-semibold hidden sm:inline">الصفحة السابقة</span>
              </button>
              <div className="font-bold text-lg text-text-primary font-mono select-none">
                  {currentPage}
              </div>
              <button 
                  onClick={handleNextPage} 
                  disabled={currentPage >= lastPage}
                  className="flex items-center gap-2 px-4 py-2 rounded-full text-text-secondary hover:bg-surface-hover disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                  <span className="font-semibold hidden sm:inline">الصفحة التالية</span>
                  <ArrowLeftIcon className="w-5 h-5" />
              </button>
          </div>
      )}

      {wordPopoverState && (
         <div 
            ref={wordPopoverRef}
            className="absolute p-3 bg-surface rounded-lg shadow-lg border border-border-default flex items-center gap-2 z-20 animate-fade-in flex-wrap leading-loose"
            style={(() => {
                if (!wordPopoverState.triggerElement) return { opacity: 0, top: 0, left: 0 };
                const rect = wordPopoverState.triggerElement.getBoundingClientRect();
                return {
                    top: `${rect.bottom + window.scrollY + 5}px`,
                    left: `${rect.left + window.scrollX + rect.width / 2}px`,
                    transform: 'translateX(-50%)',
                };
            })()}
        >
            {wordPopoverState.simpleText.split(' ').map((word, index) => (
                <button
                    key={index}
                    onClick={() => {
                        onWordClick(word, 'quran-simple-clean', { surah: surah.number, ayah: wordPopoverState.ayahNumberInSurah, wordIndex: index });
                        setWordPopoverState(null);
                    }}
                    className="px-2 py-1 bg-surface-subtle rounded-md hover:bg-primary/20 transition-colors"
                >
                    {word}
                </button>
            ))}
        </div>
      )}

      {activePopover && (
        <AyahActionPopover 
            activePopover={activePopover}
            onClose={() => setActivePopover(null)}
            onSave={handleSaveClick}
            onCopy={handleCopyAyah}
            onSearchText={handleSearchByAyahText}
            onSearchNumber={onSearchByAyahNumber}
            onPlayFrom={handlePlayFromAyah}
            copiedAyah={copiedAyah}
        />
      )}

    </div>
  );
};

export default SurahDetailView;

import React, { useMemo } from 'react';
import type { Ayah, SurahData, QuranEdition, FontSize } from '../types';
import { SparklesIcon } from './icons';
import { normalizeArabicText } from '../utils/text';

interface SearchResultItemProps {
  ayah: Ayah;
  queryWords: string[];
  onNewSearch: (word: string, sourceEdition?: string, position?: { surah: number, ayah: number, wordIndex: number }) => void;
  displayEdition: QuranEdition;
  displayEditionData: SurahData[];
  searchEdition: string;
  fontSize: FontSize;
  searchType: 'text' | 'number';
  isCurrentlyPlaying: boolean;
  itemRef: React.RefObject<HTMLLIElement>;
  pulsingWordIndex: number;
  resultIndex: number;
  simpleAyahText: string;
  onUthmaniWordClick: (event: React.MouseEvent<HTMLButtonElement>, resultIndex: number, simpleAyahText: string) => void;
  onOpenPopover: (ayah: Ayah, triggerElement: HTMLElement) => void;
}

const SearchResultItem: React.FC<SearchResultItemProps> = ({ 
    ayah, queryWords, onNewSearch, displayEdition, displayEditionData, 
    fontSize, searchType, isCurrentlyPlaying, itemRef, pulsingWordIndex,
    resultIndex, simpleAyahText, onUthmaniWordClick, onOpenPopover
}) => {

    const displayAyah = useMemo(() => {
        if (displayEditionData?.length > 0 && ayah.surah) {
            const displaySurah = displayEditionData.find(s => s.number === ayah.surah!.number);
            const displayAyahData = displaySurah?.ayahs.find(a => a.numberInSurah === ayah.numberInSurah);
            if (displayAyahData && displaySurah) {
                return { 
                    ...displayAyahData,
                    surah: {
                        number: displaySurah.number,
                        name: displaySurah.name,
                        englishName: displaySurah.englishName,
                        englishNameTranslation: displaySurah.englishNameTranslation,
                        revelationType: displaySurah.revelationType,
                    }
                };
            }
        }
        return ayah;
    }, [ayah, displayEditionData]);

    const handleSelectResult = (e: React.MouseEvent<HTMLAnchorElement>) => {
        e.preventDefault();
        if(ayah.surah) {
            window.location.hash = e.currentTarget.getAttribute('href')!;
        }
    };

    const getQuranTextStyle = () => {
        const isImlaei = displayEdition.identifier.includes('simple-clean');

        if (displayEdition.type === 'quran' && displayEdition.direction === 'rtl') {
            return {
                className: `${isImlaei ? 'imlai-font' : 'uthmani-font'} quran-text-${fontSize}`,
            };
        }

        return { className: 'font-quran text-2xl' };
    };

    const { className: quranTextClass } = getQuranTextStyle();

    const renderAyahWithHighlight = () => {
        if (displayEdition.format === 'audio') {
            return <span className="text-sm text-text-muted">[مصدر صوتي، لا يتوفر عرض نصي هنا]</span>
        }

        if (!displayAyah.text) {
            return '';
        }
        const textToRender = displayAyah.text;
        const isImlaei = displayEdition.identifier.includes('simple-clean');

        const wordElements = textToRender.split(' ').map((word, index) => {
            const isPulsing = index === pulsingWordIndex;

            if (searchType === 'number') { // No highlighting for number search
                 return (
                    <button 
                        type="button" 
                        key={index} 
                        onClick={(e) => {
                            e.stopPropagation();
                            if (isImlaei) {
                                if (word && ayah.surah) {
                                    onNewSearch(word, displayEdition.identifier, { surah: ayah.surah.number, ayah: ayah.numberInSurah, wordIndex: index });
                                }
                            } else {
                                if (simpleAyahText) {
                                    onUthmaniWordClick(e, resultIndex, simpleAyahText);
                                }
                            }
                        }} 
                        className="word-trigger bg-transparent border-none p-0 font-inherit cursor-pointer hover:bg-primary/10 rounded-md px-1 transition-colors"
                        aria-label={`إظهار خيارات البحث لكلمة: ${word}`}
                    >
                        <span className={isPulsing ? 'animate-highlight-pulse rounded-sm' : ''}>{word}</span>
                    </button>
                 );
            }

            const normalizedWord = normalizeArabicText(word);
            const isMatch = queryWords.some(queryWord => normalizedWord.includes(queryWord));

            return (
                <button
                    type="button"
                    key={index}
                    onClick={(e) => {
                        e.stopPropagation();
                        if (isImlaei) {
                            if (word && ayah.surah) {
                                onNewSearch(word, displayEdition.identifier, { surah: ayah.surah.number, ayah: ayah.numberInSurah, wordIndex: index });
                            }
                        } else {
                            if (simpleAyahText) {
                                onUthmaniWordClick(e, resultIndex, simpleAyahText);
                            }
                        }
                    }}
                    className="word-trigger bg-transparent border-none p-0 font-inherit cursor-pointer hover:bg-primary/10 rounded-md px-1 transition-colors"
                    aria-label={`إظهار خيارات البحث لكلمة: ${word}`}
                >
                    {isMatch ? (
                        <mark className={`bg-yellow-400/40 text-text-primary rounded-sm ${isPulsing ? 'animate-highlight-pulse' : ''}`}>{word}</mark>
                    ) : (
                        <span className={isPulsing ? 'animate-highlight-pulse rounded-sm' : ''}>{word}</span>
                    )}
                </button>
            );
        });

        return wordElements.reduce((prev, curr, index) => <>{prev}{index > 0 ? ' ' : ''}{curr}</>, <></>);
    };

    return (
        <li
            ref={itemRef}
            className={`p-4 rounded-xl shadow-sm transition-all duration-300 hover:shadow-lg ${isCurrentlyPlaying ? 'bg-primary/20 ring-2 ring-primary' : 'bg-surface-subtle'}`}
        >
            <div className="flex justify-between items-center mb-2 gap-4">
                 <a
                    href={`#/surah/${displayAyah.surah?.number}?ayah=${displayAyah.numberInSurah}`}
                    onClick={handleSelectResult}
                    className="text-primary-text font-bold cursor-pointer rounded-md p-1 -m-1 hover:bg-surface-hover transition-colors"
                    aria-label={`الانتقال إلى ${displayAyah.surah?.name} الآية ${displayAyah.numberInSurah}`}
                >
                    <span className="font-quran-title">{displayAyah.surah?.name} - الآية {displayAyah.numberInSurah}</span>
                </a>

                <div className="flex items-center gap-2 flex-shrink-0">
                    <button
                        onClick={(e) => onOpenPopover(displayAyah, e.currentTarget)}
                        className="p-2 -m-2 rounded-full text-text-subtle hover:text-primary hover:bg-surface-hover transition-colors focus:outline-none focus:ring-2 focus:ring-primary/50"
                        aria-label="إجراءات الآية"
                        title="إجراءات الآية"
                    >
                        <SparklesIcon className="w-5 h-5" />
                    </button>
                </div>
            </div>
            <p
                dir={displayEdition.direction}
                aria-label={`نص الآية ${displayAyah.numberInSurah} من سورة ${displayAyah.surah?.name}`}
                className={`${quranTextClass} text-text-primary ${displayEdition.direction === 'ltr' ? 'text-left' : 'text-right'}`}
            >
               {renderAyahWithHighlight()}
            </p>
        </li>
    );
};

export default SearchResultItem;

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import type { Ayah, QuranEdition, SurahData, FontSize, QuranFont } from '../types';
import { useTheme } from '../hooks/useTheme';
import { 
    SpinnerIcon, PlayIcon, PauseIcon, ForwardIcon, BackwardIcon, 
    HomeIcon,
    CogIcon, ClearIcon, CheckIcon, BookOpenIcon, TextSizeIcon, QueueListIcon,
    ComputerDesktopIcon, JuzOneIcon
} from './icons';
import AudioEditionSelector from './AudioEditionSelector';

// --- Types ---
type PlaybackMode = 'continuous' | 'single' | 'selection';

interface AudioKhatmiyahViewProps {
    allAyahs: Ayah[];
    allAudioEditions: QuranEdition[];
    initialAyahNumber: number;
    onSaveProgress: (ayahNumber: number) => void;
    selectedAudioEdition: string;
    onAudioEditionChange: (id: string) => void;
    allQuranData: { [key: string]: SurahData[] } | null;
    fetchCustomEditionData: (id: string) => void;
    fontSize: FontSize;
    onFontSizeChange: (size: FontSize) => void;
    activeEditions: QuranEdition[];
    selectedEdition: string;
    onEditionChange: (id: string) => void;
}

// --- Helper: Get Audio URL ---
const getAudioUrl = (ayah: Ayah, audioEditionDetails: QuranEdition): string | undefined => {
    const { sourceApi, reciterIdentifier, identifier } = audioEditionDetails;
    if (!ayah.surah?.number) return undefined;

    switch (sourceApi) {
        case 'versebyversequran.com':
        if (!reciterIdentifier) return undefined;
        const surahNumPad = ayah.surah.number.toString().padStart(3, '0');
        const ayahNumPad = ayah.numberInSurah.toString().padStart(3, '0');
        return `https://everyayah.com/data/${reciterIdentifier}/${surahNumPad}${ayahNumPad}.mp3`;

        case 'islamic-network':
        if (!ayah.number) return undefined;
        return `https://cdn.islamic.network/quran/audio/128/${identifier}/${ayah.number}.mp3`;

        default:
        return undefined;
    }
};

// --- Juz Selection Modal ---
interface JuzSelectionModalProps {
    onClose: () => void;
    juzStartAyahs: { juz: number, ayahNumber: number }[];
    onJuzSelect: (ayahNumber: number) => void;
    onSelectionConfirm: (selectedJuzs: number[]) => void;
    mode: 'jump' | 'selection';
}

const JuzSelectionModal: React.FC<JuzSelectionModalProps> = ({ onClose, juzStartAyahs, onJuzSelect, onSelectionConfirm, mode }) => {
    const [selectedJuzs, setSelectedJuzs] = useState<number[]>([]);

    const handleJuzClick = (juz: number, ayahNumber: number) => {
        if (mode === 'jump') {
            onJuzSelect(ayahNumber);
            onClose();
        } else { // selection mode
            setSelectedJuzs(prev => 
                prev.includes(juz) ? prev.filter(j => j !== juz) : [...prev, juz]
            );
        }
    };

    const handleConfirm = () => {
        if (selectedJuzs.length > 0) {
            onSelectionConfirm(selectedJuzs.sort((a,b) => a-b));
            onClose();
        }
    };

    const title = mode === 'jump' ? "الانتقال إلى جزء" : "اختر الأجزاء";

    return (
        <div 
            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center animate-fade-in p-4"
            onClick={onClose}
        >
            <div 
                className="bg-surface rounded-lg shadow-xl w-full max-w-lg mx-auto flex flex-col"
                onClick={e => e.stopPropagation()}
            >
                <div className="p-4 border-b border-border-default flex justify-between items-center">
                    <h2 className="text-xl font-bold text-text-primary">{title}</h2>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-surface-hover">
                        <ClearIcon className="w-5 h-5" />
                    </button>
                </div>
                <div className="p-4 overflow-y-auto">
                    <div className="grid grid-cols-6 gap-2">
                        {juzStartAyahs.map(({ juz, ayahNumber }) => {
                            const isSelected = mode === 'selection' && selectedJuzs.includes(juz);
                            return (
                                <button
                                    key={juz}
                                    onClick={() => handleJuzClick(juz, ayahNumber)}
                                    className={`p-3 rounded-lg text-center font-mono font-bold text-lg text-text-secondary transition-colors focus:outline-none focus:ring-2 focus:ring-primary
                                        bg-surface-subtle hover:bg-surface-hover
                                        ${isSelected ? 'ring-2 ring-primary bg-surface-active' : ''}
                                    `}
                                >
                                    {juz}
                                </button>
                            );
                        })}
                    </div>
                </div>
                {mode === 'selection' && (
                    <div className="p-4 border-t border-border-default">
                        <button 
                            onClick={handleConfirm}
                            disabled={selectedJuzs.length === 0}
                            className="w-full px-4 py-3 bg-primary text-white font-semibold rounded-md hover:bg-primary-hover disabled:bg-primary/50 transition-colors"
                        >
                            بدء القراءة ({selectedJuzs.length})
                        </button>
                    </div>
                )}
            </div>
        </div>
    );
};

// --- Playback Mode Modal ---
interface PlaybackModeModalProps {
    onClose: () => void;
    onModeSelect: (mode: PlaybackMode) => void;
    onCustomSelectionStart: () => void;
}

const PlaybackModeModal: React.FC<PlaybackModeModalProps> = ({ onClose, onModeSelect, onCustomSelectionStart }) => {
    return (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center animate-fade-in p-4" onClick={onClose}>
            <div className="bg-surface rounded-lg shadow-xl w-full max-w-md mx-auto" onClick={e => e.stopPropagation()}>
                <div className="p-4 border-b border-border-default flex justify-between items-center">
                    <h2 className="text-xl font-bold text-text-primary">تحديد نطاق القراءة</h2>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-surface-hover"><ClearIcon className="w-5 h-5" /></button>
                </div>
                <div className="p-4 space-y-3">
                    <button onClick={() => { onModeSelect('continuous'); onClose(); }} className="w-full text-right p-4 flex items-center gap-4 bg-surface-subtle rounded-lg hover:bg-surface-hover transition-colors">
                        <BookOpenIcon className="w-8 h-8 text-primary flex-shrink-0"/>
                        <div>
                            <h3 className="font-bold text-lg">ختمة كاملة</h3>
                            <p className="text-sm text-text-muted">الاستمرار في القراءة من مكان وقوفك في المصحف كاملاً.</p>
                        </div>
                    </button>
                    <button onClick={() => { onModeSelect('single'); onClose(); }} className="w-full text-right p-4 flex items-center gap-4 bg-surface-subtle rounded-lg hover:bg-surface-hover transition-colors">
                        <JuzOneIcon className="w-8 h-8 text-primary flex-shrink-0"/>
                        <div>
                            <h3 className="font-bold text-lg">جزء واحد فقط</h3>
                            <p className="text-sm text-text-muted">قراءة الجزء الحالي فقط ثم التوقف تلقائياً.</p>
                        </div>
                    </button>
                    <button onClick={onCustomSelectionStart} className="w-full text-right p-4 flex items-center gap-4 bg-surface-subtle rounded-lg hover:bg-surface-hover transition-colors">
                        <QueueListIcon className="w-8 h-8 text-primary flex-shrink-0"/>
                        <div>
                            <h3 className="font-bold text-lg">تحديد أجزاء</h3>
                            <p className="text-sm text-text-muted">اختر أجزاء متتالية أو متفرقة للقراءة.</p>
                        </div>
                    </button>
                </div>
            </div>
        </div>
    );
};


// --- Main Component ---
const AudioKhatmiyahView: React.FC<AudioKhatmiyahViewProps> = ({
    allAyahs, allAudioEditions, initialAyahNumber, onSaveProgress,
    selectedAudioEdition, onAudioEditionChange, allQuranData, fetchCustomEditionData,
    fontSize, onFontSizeChange,
    activeEditions, selectedEdition, onEditionChange
}) => {
    const { cycleTheme, emoji, name, nextThemeName } = useTheme();
    const [currentAyahNumber, setCurrentAyahNumber] = useState(initialAyahNumber);
    const [currentAyah, setCurrentAyah] = useState<Ayah | null>(null);
    const [uthmaniText, setUthmaniText] = useState<string>('');
    const [displayedText, setDisplayedText] = useState<string>('');

    const [isPlaying, setIsPlaying] = useState(false);
    const [audioDuration, setAudioDuration] = useState(0);
    const [audioProgress, setAudioProgress] = useState(0);
    const [wordTimings, setWordTimings] = useState<{word: string, start: number, duration: number}[]>([]);
    const [currentWordIndex, setCurrentWordIndex] = useState(-1);

    const [isLoading, setIsLoading] = useState(true);
    const [isBuffering, setIsBuffering] = useState(false);

    const [controlsVisible, setControlsVisible] = useState(true);
    const [isSettingsOpen, setIsSettingsOpen] = useState(false);
    const [isJuzSelectorOpen, setIsJuzSelectorOpen] = useState(false);
    const [isModeSelectorOpen, setIsModeSelectorOpen] = useState(false);

    // --- New State for Playback Modes ---
    const [playbackMode, setPlaybackMode] = useState<PlaybackMode>('continuous');
    const [playbackSelection, setPlaybackSelection] = useState<number[] | null>(null);
    const [juzModalMode, setJuzModalMode] = useState<'jump' | 'selection'>('jump');

    const audioRef = useRef<HTMLAudioElement>(null);

    const audioEditionDetails = useMemo(() => allAudioEditions.find(e => e.identifier === selectedAudioEdition), [selectedAudioEdition, allAudioEditions]);
    const displayEditionDetails = useMemo(() => activeEditions.find(e => e.identifier === selectedEdition), [activeEditions, selectedEdition]);

    const handleScreenTap = () => {
        // Only allow toggling visibility if the audio is playing.
        if (isPlaying) {
            setControlsVisible(prev => !prev);
        }
    };

    useEffect(() => {
        // When playback stops, controls must become visible.
        if (!isPlaying) {
            setControlsVisible(true);
        }
    }, [isPlaying]);

    const juzStartAyahs = useMemo(() => {
        if (!allAyahs || allAyahs.length === 0) return [];
        const juzMap = new Map<number, number>();
        for (const ayah of allAyahs) {
            if (ayah.juz && !juzMap.has(ayah.juz)) {
                juzMap.set(ayah.juz, ayah.number);
            }
        }
        return Array.from(juzMap.entries())
            .sort((a, b) => a[0] - b[0])
            .map(([juz, ayahNumber]) => ({ juz, ayahNumber }));
    }, [allAyahs]);

    const handleJuzSelect = (ayahNumber: number) => {
        setCurrentAyahNumber(ayahNumber);
        setIsJuzSelectorOpen(false);
        if (!isPlaying) setIsPlaying(true);
    };

    const handleSelectionConfirm = (selectedJuzs: number[]) => {
        if (selectedJuzs.length === 0) return;
        setPlaybackMode('selection');
        setPlaybackSelection(selectedJuzs);
        const startAyahNumber = juzStartAyahs.find(j => j.juz === selectedJuzs[0])?.ayahNumber;
        if (startAyahNumber) {
            setCurrentAyahNumber(startAyahNumber);
        }
        setIsJuzSelectorOpen(false);
        if (!isPlaying) setIsPlaying(true);
    };

    useEffect(() => {
        if (!allQuranData?.[selectedEdition]) {
            fetchCustomEditionData(selectedEdition);
        }
    }, [selectedEdition, allQuranData, fetchCustomEditionData]);

    useEffect(() => {
        const foundAyah = allAyahs.find(a => a.number === currentAyahNumber);
        if (foundAyah) {
            setCurrentAyah(foundAyah);
            const uthmaniData = allQuranData?.['quran-uthmani-quran-academy'];
            const uthmaniSurah = uthmaniData?.find(s => s.number === foundAyah.surah?.number);
            const uthmaniAyah = uthmaniSurah?.ayahs.find(a => a.numberInSurah === foundAyah.numberInSurah);
            setUthmaniText(uthmaniAyah?.text || foundAyah.text || '');
            const displayData = allQuranData?.[selectedEdition];
            const displaySurah = displayData?.find(s => s.number === foundAyah.surah?.number);
            const displayAyah = displaySurah?.ayahs.find(a => a.numberInSurah === foundAyah.numberInSurah);
            setDisplayedText(displayAyah?.text || uthmaniAyah?.text || foundAyah.text || '');
            setIsLoading(true);
            setIsBuffering(true);
            setWordTimings([]);
            setCurrentWordIndex(-1);
            onSaveProgress(currentAyahNumber);
        }
    }, [currentAyahNumber, allAyahs, allQuranData, onSaveProgress, selectedEdition]);

    useEffect(() => {
        if (!currentAyah || !audioEditionDetails || !audioRef.current) return;
        const loadAudio = () => {
            let audioUrl: string | undefined;
            if (audioEditionDetails.sourceApi === 'alquran.cloud') {
                const audioData = allQuranData?.[selectedAudioEdition];
                const audioSurah = audioData?.find(s => s.number === currentAyah.surah?.number);
                const audioAyah = audioSurah?.ayahs.find(a => a.numberInSurah === currentAyah.numberInSurah);
                audioUrl = audioAyah?.audio;
            } else {
                audioUrl = getAudioUrl(currentAyah, audioEditionDetails);
            }
            if (audioUrl && audioRef.current) {
                audioRef.current.src = audioUrl;
                audioRef.current.load();
                if(isPlaying) audioRef.current.play().catch(e => console.error("Play failed", e));
            } else {
                setIsLoading(false);
                setIsBuffering(false);
            }
        };
        if(audioEditionDetails.sourceApi === 'alquran.cloud' && !allQuranData?.[selectedAudioEdition]) {
            fetchCustomEditionData(selectedAudioEdition);
        } else {
            loadAudio();
        }
    }, [currentAyah, selectedAudioEdition, audioEditionDetails, allQuranData, fetchCustomEditionData, isPlaying]);

    useEffect(() => {
        if (audioDuration > 0 && uthmaniText) {
            const words = uthmaniText.split(' ');
            const totalLetters = words.reduce((acc, word) => acc + word.length, 0);
            if (totalLetters === 0) return;
            const effectiveDuration = audioDuration * 0.92;
            const timePerLetter = effectiveDuration / totalLetters;
            let cumulativeTime = 0;
            const timings = words.map(word => {
                const duration = word.length * timePerLetter;
                const timing = { word, start: cumulativeTime, duration };
                cumulativeTime += duration;
                return timing;
            });
            setWordTimings(timings);
        }
    }, [audioDuration, uthmaniText]);

    useEffect(() => {
        if (!isPlaying) return;
        const intervalId = setInterval(() => {
            if (audioRef.current && wordTimings.length > 0) {
                 const leadTime = 0.150;
                 const currentTime = audioRef.current.currentTime;
                 const lookupTime = currentTime + leadTime;
                 setAudioProgress(currentTime);
                 let newWordIndex = -1;
                 for (let i = 0; i < wordTimings.length; i++) {
                    if (lookupTime >= wordTimings[i].start) {
                        newWordIndex = i;
                    } else {
                        break;
                    }
                 }
                 setCurrentWordIndex(prevIndex => newWordIndex !== prevIndex ? newWordIndex : prevIndex);
            }
        }, 50);
        return () => clearInterval(intervalId);
    }, [isPlaying, wordTimings]);

    const handlePlayPause = () => {
        if (isLoading || isBuffering) return;
        const newIsPlaying = !isPlaying;
        setIsPlaying(newIsPlaying);
        if (newIsPlaying) {
            audioRef.current?.play().catch(e => console.error(e));
            setCurrentWordIndex(-1);
        } else {
            audioRef.current?.pause();
        }
    };

    const changeAyah = useCallback((direction: 'next' | 'prev') => {
        if (direction === 'prev') {
            const newAyahNumber = currentAyahNumber - 1;
            if (newAyahNumber > 0) setCurrentAyahNumber(newAyahNumber);
            return;
        }

        const nextAyahNumber = currentAyahNumber + 1;
        if (nextAyahNumber > allAyahs.length) {
            setIsPlaying(false);
            return;
        }

        const nextAyah = allAyahs[nextAyahNumber - 1];
        if (!nextAyah || !currentAyah?.juz) {
            setIsPlaying(false);
            return;
        }

        let shouldStop = false;

        if (playbackMode === 'single' && nextAyah.juz !== currentAyah.juz) {
            shouldStop = true;
        } else if (playbackMode === 'selection' && playbackSelection && nextAyah.juz !== currentAyah.juz) {
            const currentJuzIndex = playbackSelection.indexOf(currentAyah.juz);
            if (currentJuzIndex === -1 || currentJuzIndex === playbackSelection.length - 1) {
                shouldStop = true;
            } else {
                const nextSelectedJuz = playbackSelection[currentJuzIndex + 1];
                const startOfNextSelectedJuz = juzStartAyahs.find(j => j.juz === nextSelectedJuz)?.ayahNumber;
                if (startOfNextSelectedJuz) {
                    setCurrentAyahNumber(startOfNextSelectedJuz);
                    return; 
                } else {
                    shouldStop = true;
                }
            }
        }

        if (shouldStop) {
            setIsPlaying(false);
        } else {
            setCurrentAyahNumber(nextAyahNumber);
        }
    }, [currentAyahNumber, allAyahs, currentAyah, playbackMode, playbackSelection, juzStartAyahs]);

    const handleAudioEnded = useCallback(() => {
        changeAyah('next');
    }, [changeAyah]);

    const getQuranTextStyle = useCallback(() => {
        const isImlaei = displayEditionDetails?.identifier.includes('simple-clean');
        if (displayEditionDetails?.type === 'quran' && displayEditionDetails?.direction === 'rtl') {
            return {
                className: `${isImlaei ? 'imlai-font' : 'uthmani-font'} quran-text-${fontSize}`,
            };
        }
        return { 
            className: `font-sans text-2xl md:text-3xl lg:text-4xl`, 
            style: { lineHeight: 1.8 } 
        };
    }, [displayEditionDetails, fontSize]);

    const { className: quranTextClass } = getQuranTextStyle();
    const canHighlight = displayEditionDetails?.type === 'quran' && displayEditionDetails?.direction === 'rtl';

    const formatJuzSelection = (juzs: number[]): string => {
        if (!juzs || juzs.length === 0) return '';
        if (juzs.length === 1) return `${juzs[0]}`;

        const sorted = [...juzs].sort((a,b) => a - b);
        const ranges: string[] = [];
        let start = sorted[0];
        let end = sorted[0];

        for (let i = 1; i < sorted.length; i++) {
            if (sorted[i] === end + 1) {
                end = sorted[i];
            } else {
                ranges.push(start === end ? `${start}` : `${start}-${end}`);
                start = sorted[i];
                end = sorted[i];
            }
        }
        ranges.push(start === end ? `${start}` : `${start}-${end}`);
        return ranges.join(', ');
    };

    const getPlaybackScopeDescription = () => {
        if (playbackMode === 'single' && currentAyah?.juz) return `الجزء ${currentAyah.juz} فقط`;
        if (playbackMode === 'selection' && playbackSelection) {
            const isRange = playbackSelection.every((juz, i) => i === 0 || juz === playbackSelection[i-1] + 1);
            if (isRange && playbackSelection.length > 1) {
                return `من الجزء ${playbackSelection[0]} إلى ${playbackSelection[playbackSelection.length - 1]}`;
            }
            return `أجزاء مختارة: ${formatJuzSelection(playbackSelection)}`;
        }
        return 'ختمة كاملة';
    };


    if (!currentAyah) {
        return <div className="flex flex-col gap-4 justify-center items-center h-screen bg-gray-900 text-white"><SpinnerIcon className="w-10 h-10"/> <p>جاري تحميل بيانات الختمة...</p></div>;
    }

    return (
        <div className="bg-background text-text-primary fixed inset-0 flex flex-col font-sans" onClick={handleScreenTap}>
            {isJuzSelectorOpen && (
                <JuzSelectionModal 
                    onClose={() => setIsJuzSelectorOpen(false)}
                    juzStartAyahs={juzStartAyahs}
                    onJuzSelect={handleJuzSelect}
                    onSelectionConfirm={handleSelectionConfirm}
                    mode={juzModalMode}
                />
            )}
            {isModeSelectorOpen && (
                <PlaybackModeModal
                    onClose={() => setIsModeSelectorOpen(false)}
                    onModeSelect={(mode) => {
                        setPlaybackMode(mode);
                        setPlaybackSelection(null);
                        if (mode === 'single' && !isPlaying) setIsPlaying(true);
                    }}
                    onCustomSelectionStart={() => {
                        setIsModeSelectorOpen(false);
                        setJuzModalMode('selection');
                        setIsJuzSelectorOpen(true);
                    }}
                />
            )}
            {isSettingsOpen && (
                <SettingsModal 
                    onClose={() => setIsSettingsOpen(false)}
                    fontSize={fontSize} onFontSizeChange={onFontSizeChange}
                    activeEditions={activeEditions} selectedEdition={selectedEdition} onEditionChange={onEditionChange}
                />
            )}

            <audio ref={audioRef} onLoadedMetadata={() => setAudioDuration(audioRef.current?.duration || 0)} onCanPlay={() => { setIsLoading(false); setIsBuffering(false); if(isPlaying) audioRef.current?.play(); }} onPlay={() => setIsPlaying(true)} onPause={() => { if (audioRef.current && Math.abs(audioRef.current.currentTime - audioRef.current.duration) > 0.1) setIsPlaying(false); }} onEnded={handleAudioEnded} onWaiting={() => setIsBuffering(true)} className="hidden" />

            <header className={`flex-shrink-0 p-3 text-center bg-surface/80 backdrop-blur-md shadow-md z-10 transition-all duration-300 ${controlsVisible ? 'opacity-100' : 'opacity-0 -translate-y-full'}`}>
                <a href="#/" onClick={(e) => { e.preventDefault(); window.location.hash = '#/'; }} title="العودة للرئيسية" aria-label="العودة للرئيسية" className="absolute top-3 left-3 p-2 rounded-full bg-surface-subtle hover:bg-surface-hover">
                    <HomeIcon className="w-6 h-6"/>
                </a>
                <h1 className="text-xl font-bold text-primary-text-strong">سورة {currentAyah.surah?.name}</h1>
                <div className="text-sm text-text-muted font-semibold flex justify-center gap-4">
                    <span>الآية: {currentAyah.numberInSurah}</span>
                    <span>الجزء: {currentAyah.juz}</span>
                    <span>الصفحة: {currentAyah.page}</span>
                </div>
            </header>

            <main className="flex-grow flex items-center justify-center p-4">
                <div className="text-center w-full">
                    {(isLoading && !displayedText) ? (
                        <div className="flex flex-col gap-4 items-center"><SpinnerIcon className="w-12 h-12 text-primary"/><p className="text-lg">جاري تحميل الآية...</p></div>
                    ) : (
                        <p className={`select-none ${quranTextClass}`} dir={displayEditionDetails?.direction || 'rtl'}>
                           {canHighlight ? displayedText.split(' ').map((word, index) => (
                                <span key={index} className={`transition-colors duration-200 ${index === currentWordIndex ? 'text-primary' : ''}`}>
                                    {word}{' '}
                                </span>
                            )) : displayedText}
                        </p>
                    )}
                </div>
            </main>

            <footer className={`flex-shrink-0 p-4 bg-surface/80 backdrop-blur-md shadow-[0_-4px_30px_rgba(0,0,0,0.1)] z-10 transition-all duration-300 ${controlsVisible ? 'opacity-100' : 'opacity-0 translate-y-full'}`}>
                <div className="w-full h-1.5 bg-surface-subtle rounded-full mb-4">
                    <div className="h-1.5 bg-primary rounded-full transition-all" style={{ width: audioDuration > 0 ? `${(audioProgress / audioDuration) * 100}%` : '0%'}}></div>
                </div>
                <div className="flex items-center justify-between gap-4">
                    <div className="flex-1 min-w-0 flex flex-col gap-1 items-start">
                        <AudioEditionSelector audioEditions={allAudioEditions} selectedAudioEdition={selectedAudioEdition} onSelect={onAudioEditionChange} size="sm" />
                        <span className="text-xs font-semibold text-text-muted px-2">{getPlaybackScopeDescription()}</span>
                    </div>
                    <div className="flex items-center gap-2 sm:gap-4 flex-shrink-0">
                        <button onClick={() => changeAyah('prev')} className="p-2 text-text-secondary hover:text-text-primary transition-colors"><BackwardIcon className="w-7 h-7" /></button>
                        <button onClick={handlePlayPause} className="p-4 bg-primary text-white rounded-full shadow-lg hover:bg-primary-hover transition-transform hover:scale-105">
                             {isBuffering ? <SpinnerIcon className="w-8 h-8"/> : (isPlaying ? <PauseIcon className="w-8 h-8" /> : <PlayIcon className="w-8 h-8" />)}
                        </button>
                        <button onClick={() => changeAyah('next')} className="p-2 text-text-secondary hover:text-text-primary transition-colors"><ForwardIcon className="w-7 h-7" /></button>
                    </div>
                    <div className="flex-1 flex justify-end items-center gap-2">
                        <button onClick={() => setIsModeSelectorOpen(true)} title="تحديد نطاق القراءة" className={`p-2 rounded-full transition-colors text-text-muted hover:bg-surface-hover`}><BookOpenIcon className="w-6 h-6"/></button>
                        <div className="h-6 w-px bg-border-default mx-1"></div>
                        <button onClick={() => setIsSettingsOpen(true)} title="إعدادات العرض" className="p-2 rounded-full text-text-muted hover:bg-surface-hover transition-colors"><ComputerDesktopIcon className="w-6 h-6"/></button>
