import React from 'react';
import type { Ayah, QuranEdition, SurahData, FontSize, BrowsingMode } from '../types';

interface AyahRendererProps {
    ayahsToRender: Ayah[];
    surah: SurahData;
    highlightAyahNumber: number | null;
    onWordClick: (query: string, editionIdentifier: string, position: { surah: number; ayah: number; wordIndex: number; }) => void;
    displayEdition: QuranEdition;
    fontSize: FontSize;
    browsingMode: BrowsingMode;
    currentlyPlayingAyahGlobalNumber: number | null;
    simpleCleanData: SurahData[];
    wordPopoverState: { ayahNumberInSurah: number; simpleText: string; triggerElement: HTMLElement; } | null;
    setWordPopoverState: (state: { ayahNumberInSurah: number; simpleText: string; triggerElement: HTMLElement; } | null) => void;
    setActivePopover: (state: { ayah: Ayah; triggerElement: HTMLElement } | null) => void;
    playingAyahRef: React.RefObject<HTMLSpanElement>;
    highlightRef: React.RefObject<HTMLSpanElement>;
    firstAyahInfo: { bismillah: string; restOfAyah: string; } | null;
}

const AyahRenderer: React.FC<AyahRendererProps> = ({
    ayahsToRender, surah, highlightAyahNumber, onWordClick, displayEdition, fontSize, browsingMode,
    currentlyPlayingAyahGlobalNumber, simpleCleanData, wordPopoverState, setWordPopoverState,
    setActivePopover, playingAyahRef, highlightRef, firstAyahInfo
}) => {

    const isImlaei = displayEdition.identifier.includes('simple-clean');

    const cleanImlaiText = (text: string | undefined): string | undefined => {
        if (!text) return text;
        const marksToRemoveRegex = /[\u06D6-\u06ED]/g;
        return text.replace(marksToRemoveRegex, '');
    };

    return (
        <>
            {ayahsToRender.map((ayah, index) => {
                const isHighlighted = ayah.numberInSurah === highlightAyahNumber;
                const isPlaying = ayah.number === currentlyPlayingAyahGlobalNumber;

                const simpleSurah = simpleCleanData.find(s => s.number === surah.number);
                const simpleAyah = simpleSurah?.ayahs.find(a => a.numberInSurah === ayah.numberInSurah);

                const baseText = (index === 0 && firstAyahInfo) ? firstAyahInfo.restOfAyah : ayah.text;
                const textToDisplay = isImlaei ? cleanImlaiText(baseText) : baseText;

                const createUthmaniWordClickHandler = (event: React.MouseEvent<HTMLButtonElement>) => {
                    const simpleAyahText = simpleAyah?.text;
                    if (simpleAyahText) {
                        if (wordPopoverState?.ayahNumberInSurah === ayah.numberInSurah) {
                            setWordPopoverState(null);
                        } else {
                            setWordPopoverState({
                                ayahNumberInSurah: ayah.numberInSurah,
                                simpleText: simpleAyahText,
                                triggerElement: event.currentTarget,
                            });
                        }
                    }
                };

                return (
                    <span key={ayah.number} className="inline">
                        <span
                            ref={isPlaying ? playingAyahRef : (isHighlighted ? highlightRef : null)}
                            className={`inline rounded-md transition-colors duration-300 ${isPlaying ? 'bg-primary/20' : ''}`}
                        >
                            {textToDisplay?.split(' ').map((word, wordIndex, arr) => (
                                <React.Fragment key={wordIndex}>
                                    <button
                                        onClick={
                                            isImlaei
                                                ? () => onWordClick(word, displayEdition.identifier, { surah: surah.number, ayah: ayah.numberInSurah, wordIndex: wordIndex })
                                                : createUthmaniWordClickHandler
                                        }
                                        className="word-trigger bg-transparent border-none p-0 font-inherit text-inherit leading-inherit cursor-pointer hover:bg-primary/10 rounded-md transition-colors"
                                        aria-label={`إظهار خيارات البحث لكلمة: ${word}`}
                                    >
                                        {word}
                                    </button>
                                    {wordIndex < arr.length - 1 && ' '}
                                </React.Fragment>
                            ))}
                        </span>

                        <span className="relative inline-block align-middle">
                            <button
                                onClick={(e) => setActivePopover({ ayah: ayah, triggerElement: e.currentTarget })}
                                className={`popover-trigger mx-1 select-none cursor-pointer hover:opacity-80 transition-opacity ${browsingMode === 'page' ? 'ayah-marker' : 'text-sm font-sans font-bold text-primary-text rounded-md p-1 -m-1'}`}
                                aria-label={`إجراءات للآية ${ayah.numberInSurah}`}
                                aria-haspopup="true"
                            >
                                {browsingMode === 'page' ? ayah.numberInSurah : `﴿${ayah.numberInSurah}﴾`}
                            </button>
                        </span>
                    </span>
                );
            })}
        </>
    );
};

export default AyahRenderer;

import React, { useState, useEffect, useRef } from 'react';
import type { QuranFont, QuranEdition, FontSize, BrowsingMode } from '../types';
import { ArrowLeftIcon, ArrowRightIcon, HomeIcon, TextSizeIcon, PlusIcon, MinusIcon, SparklesIcon, BookOpenIcon, CheckIcon, DocumentDuplicateIcon, QueueListIcon } from './icons';

interface ToolboxProps {
    // Font Size
    fontSize: FontSize;
    onFontSizeChange: (size: FontSize) => void;
    isAudioPlayerVisible: boolean;
    // Browsing Mode
    browsingMode: BrowsingMode;
    onBrowsingModeChange: (mode: BrowsingMode) => void;
}

const Toolbox: React.FC<ToolboxProps> = ({
    fontSize, onFontSizeChange,
    isAudioPlayerVisible,
    browsingMode, onBrowsingModeChange
}) => {
    type Popover = 'size';
    const [openPopover, setOpenPopover] = useState<Popover | null>(null);
    const [isShown, setIsShown] = useState(true);
    const popoverRef = useRef<HTMLDivElement>(null);
    const lastScrollY = useRef(0);

    // Effect to handle toolbox visibility on scroll
    useEffect(() => {
        const handleScroll = () => {
            const currentScrollY = window.scrollY;
            const scrollThreshold = 20;

            // Do nothing if scroll change is insignificant
            if (Math.abs(currentScrollY - lastScrollY.current) < scrollThreshold) {
                return;
            }

            if (currentScrollY < 100) { // Always show near the top
                setIsShown(true);
            } else if (currentScrollY > lastScrollY.current) { // Scrolling down
                setIsShown(false);
                setOpenPopover(null); // Hide popovers when toolbar hides
            } else { // Scrolling up
                setIsShown(true);
            }
            lastScrollY.current = currentScrollY;
        };

        window.addEventListener('scroll', handleScroll, { passive: true });
        return () => window.removeEventListener('scroll', handleScroll);
    }, []);

    // Close popover on outside click
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (popoverRef.current && !popoverRef.current.contains(event.target as Node)) {
                setOpenPopover(null);
            }
        };
        if (openPopover) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [openPopover]);

    const handleTogglePopover = (popover: Popover) => {
        setOpenPopover(prev => (prev === popover ? null : popover));
    };

    const ToolButton: React.FC<{ onClick: () => void; label: string; children: React.ReactNode; isActive?: boolean }> = ({ onClick, label, children, isActive }) => (
        <button
            onClick={onClick}
            aria-label={label}
            title={label}
            className={`p-3 rounded-full transition-colors ${isActive ? 'bg-surface-active text-primary-text-strong' : 'text-text-muted hover:bg-surface-hover'}`}
        >
            {children}
        </button>
    );

    const PopoverContainer: React.FC<{ children: React.ReactNode; popoverId: Popover, title: string, widthClass?: string }> = ({ children, popoverId, title, widthClass = 'w-72' }) => (
        openPopover === popoverId ? (
            <div ref={popoverRef} className={`absolute bottom-full left-1/2 -translate-x-1/2 mb-3 ${widthClass} bg-surface rounded-lg shadow-2xl ring-1 ring-black/5 animate-fade-in`}
                role="dialog" aria-labelledby={`${popoverId}-title`}>
                <div className="p-3 border-b border-border-default">
                    <h3 id={`${popoverId}-title`} className="font-semibold text-text-primary">{title}</h3>
                </div>
                <div className="p-3 max-h-64 overflow-y-auto">
                    {children}
                </div>
                <div className={`absolute left-1/2 -translate-x-1/2 bottom-[-8px] w-4 h-4 bg-surface rotate-45 -z-10`}></div>
            </div>
        ) : null
    );

    return (
        <div className={`fixed left-1/2 -translate-x-1/2 z-20 transition-all duration-300 ${isAudioPlayerVisible ? 'bottom-28' : 'bottom-8'}`}>
            <div className={`relative flex items-center gap-1 bg-surface/80 backdrop-blur-md p-2 rounded-full shadow-lg border border-border-default transition-all duration-300 ${
                isShown ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-16 pointer-events-none'
            }`}>

                {/* Navigation Group */}
                <ToolButton onClick={() => window.history.back()} label="الخلف"><ArrowRightIcon className="w-5 h-5" /></ToolButton>
                <ToolButton onClick={() => window.location.hash = '#/'} label="الرئيسية"><HomeIcon className="w-5 h-5" /></ToolButton>
                <ToolButton onClick={() => window.history.forward()} label="الأمام"><ArrowLeftIcon className="w-5 h-5" /></ToolButton>

                <div className="h-6 w-px bg-border-default mx-2"></div>

                {/* Settings Group */}
                <div className="relative">
                    <ToolButton onClick={() => handleTogglePopover('size')} label="حجم الخط" isActive={openPopover === 'size'}>
                        <TextSizeIcon className="w-5 h-5" />
                    </ToolButton>
                    <PopoverContainer popoverId="size" title="تغيير حجم الخط" widthClass="w-auto">
                        <div className="flex items-center justify-center gap-2">
