import React, { useState, useMemo, useCallback, useEffect } from 'react';
import type { Ayah, QuranEdition, SurahData, FontSize } from '../types';
import { useTheme } from '../hooks/useTheme';
import { useAudioKhatmiyah } from '../hooks/useAudioKhatmiyah';
import { 
    SpinnerIcon, PlayIcon, PauseIcon, ForwardIcon, BackwardIcon, 
    HomeIcon,
    CogIcon, ClearIcon, BookOpenIcon, TextSizeIcon, QueueListIcon,
    ComputerDesktopIcon, JuzOneIcon
} from './icons';
