export const useAiAnalysis = (word: string) => {
    const [isProcessing, setIsProcessing] = useState(false);
    const [aiResult, setAiResult] = useState('');
    const [isApiKeyModalOpen, setIsApiKeyModalOpen] = useState(false);
    const [isCheckingCache, setIsCheckingCache] = useState(false);
    const [cachedAnalyses, setCachedAnalyses] = useState<AnalysisDoc[] | null>(null);
    const [selectedAnalysis, setSelectedAnalysis] = useState<AnalysisDoc | null>(null);

    const fetchAnalyses = useCallback(async (wordToFetch: string, selectFirst = false) => {
        if (!wordToFetch) return;
        setIsCheckingCache(true);
        setCachedAnalyses(null);
        setSelectedAnalysis(null);
        setAiResult('');
        try {
            const collectionRef = db.collection('qran_word_analysis_cache').doc(normalizeArabicText(wordToFetch)).collection('analyses').orderBy('createdAt', 'desc');
            const snapshot = await collectionRef.get();
            if (!snapshot.empty) {
                const analyses = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as AnalysisDoc));
                setCachedAnalyses(analyses);
                if (selectFirst && analyses.length > 0) {
                    const firstAnalysis = analyses[0];
                    setSelectedAnalysis(firstAnalysis);
                    setAiResult(firstAnalysis.result);
                }
            }
        } catch (error) {
            console.error("Error checking AI cache:", error);
        } finally {
            setIsCheckingCache(false);
        }
    }, []);

    const saveAiResultToCache = async (wordToCache: string, result: string, prompt: string) => {
        if (!wordToCache || !result) return;
        const normalizedWord = normalizeArabicText(wordToCache);
        try {
            const wordDocRef = db.collection('qran_word_analysis_cache').doc(normalizedWord);
            const analysesSubCollectionRef = wordDocRef.collection('analyses');
            await analysesSubCollectionRef.add({
                result: result,
                prompt: prompt,
                createdAt: FieldValue.serverTimestamp()
            });
            await wordDocRef.set({
                lastAnalyzedAt: FieldValue.serverTimestamp()
            }, { merge: true });
        } catch (error) {
            console.error("Failed to save AI result to cache:", error);
        }
    };

    const triggerAnalysis = async (customPrompt: string, dataString: string) => {
        if (!word) return;
        setIsProcessing(true);
        setAiResult('');

        const userApiKey = localStorage.getItem(USER_API_KEY_KEY);
        const usageCount = parseInt(localStorage.getItem(AI_USAGE_COUNT_KEY) || '0', 10);

        let apiKey = userApiKey;
        if (!apiKey) {
            if (usageCount >= 2) {
                setIsApiKeyModalOpen(true);
                setIsProcessing(false);
                return;
            }
            apiKey = process.env.API_KEY;
        }

        if (!apiKey) {
             setAiResult("خطأ: مفتاح API غير متوفر. يرجى إضافته من الإعدادات.");
             setIsProcessing(false);
             return;
        }

        try {
            const ai = new GoogleGenAI({ apiKey });
            const fullContent = `
الكلمة المراد تحليلها: "${word}"

تعليمات التحليل:
${customPrompt}

البيانات الإحصائية المستخرجة من القرآن (المثاني):
${dataString}
            `;

            const response = await ai.models.generateContentStream({
                model: 'gemini-3-pro-preview',
                contents: fullContent,
            });

            let finalResult = '';
            for await (const chunk of response) {
                if (chunk.text) {
                    finalResult += chunk.text;
                    setAiResult(prev => prev + chunk.text);
                }
            }

            if (!userApiKey) {
                localStorage.setItem(AI_USAGE_COUNT_KEY, String(usageCount + 1));
            }

            await saveAiResultToCache(word, finalResult, customPrompt);
            await fetchAnalyses(word, true);

        } catch (error) {
            console.error("AI Error:", error);
            setAiResult("حدث خطأ أثناء الاتصال بالذكاء الاصطناعي. يرجى التأكد من صلاحية مفتاح API الخاص بك والمحاولة مرة أخرى.");
        } finally {
            setIsProcessing(false);
        }
    };

    const handleApiKeySave = (key: string) => {
        localStorage.setItem(USER_API_KEY_KEY, key);
        setIsApiKeyModalOpen(false);
        // Automatically retry analysis after saving the key
        // We can't pass the prompt/data directly, so we'll let the user click again for simplicity.
        // Or we can store them in a ref if needed. For now, user re-click is fine.
    };

    // Effect to fetch analyses when the word changes
    useEffect(() => {
        if (word) {
            fetchAnalyses(word);
        } else {
            setCachedAnalyses(null);
            setSelectedAnalysis(null);
        }
    }, [word, fetchAnalyses]);

    return {
        isProcessing,
        aiResult,
        setAiResult, // Allow manual setting from cache
        isApiKeyModalOpen,
        setIsApiKeyModalOpen,
        handleApiKeySave,
        triggerAnalysis,
        isCheckingCache,
        cachedAnalyses,
        selectedAnalysis,
        setSelectedAnalysis,
    };
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { SurahData } from '../types';
import { normalizeArabicText } from '../utils/text';
import { ChartBarIcon, CheckIcon, CopyIcon, SpinnerIcon, SparklesIcon, ComputerDesktopIcon, QueueListIcon, ClearIcon, ArrowUpTrayIcon, RefreshIcon, PlusIcon } from './icons';
import { db, FieldValue } from '../firebase';
import { useAiAnalysis } from '../hooks/useAiAnalysis';
import DiscussionSection from './DiscussionSection';


interface WordAnalysisViewProps {
    simpleCleanData: SurahData[];
    initialWord?: string;
}

interface ExampleWord {
    word: string;
    count: number;
}

interface AnalysisResult {
    bigram: string;
    occurrences: number;
    examples: ExampleWord[]; 
}

interface ParsedMeaning {
    meaning: string;
    status: 'idle' | 'saving' | 'saved';
}

interface AnalysisDoc {
    id: string;
    result: string;
    prompt: string;
    createdAt: any;
}

// Simplified Prompt - No placeholders needed
const DEFAULT_AI_INSTRUCTIONS = `أنت باحث لغوي محايد ودقيق.
المطلوب منك هو استنباط المعنى الدقيق للكلمة المذكورة أعلاه بناءً حصرياً على بيانات "المثاني" (الثنائيات الحرفية) المقدمة لك في الأسفل.

التعليمات:
1. ادرس كل مقطع ثنائي (Bigram) على حدة. انظر في الكلمات التي ورد فيها هذا المقطع، وحاول استنباط "المعنى الجذري" أو "الأثر الحسي/المعنوي" المشترك.
2. اكتب بجانب كل مقطع نتيجة دراستك له باختصار.
3. في النهاية، قم بجمع هذه الاستنتاجات لتكوين "صورة شاملة" أو "تعريف دقيق" للكلمة الأصلية.

شروط صارمة:
- الحيادية التامة: لا تستخدم قواميس أو معرفتك المسبقة. اعتمد فقط على البيانات (تأثير المقاطع في الكلمات الأخرى).
- ممنوع تحريف النتائج لتتوافق مع المعنى المعروف. اذا كانت البيانات تشير لمعنى مختلف، اكتبه كما هو.

الصيغة المطلوبة للإجابة:
- تحليل المقاطع:
  * [المقطع]: [الاستنتاج]
- الخلاصة التركيبية (معنى المثاني):
  [العبارة النهائية الجامعة]`;

