                        required
                        autoFocus
                    />
                     <p className="text-xs text-text-muted mt-2">
                        يتم حفظ المفتاح في متصفحك فقط. <a href="#/manual" onClick={onClose} className="text-primary-text hover:underline">كيف أحصل على مفتاح؟</a>
                    </p>
                    <div className="flex justify-end gap-2 mt-4">
                        <button type="button" onClick={onClose} className="px-4 py-2 text-sm rounded-md bg-surface-subtle hover:bg-surface-hover">
                            إلغاء
                        </button>
