  const handleDownloadAll = () => {
      const textToDownload = formatResultsForExport(displayEditionData);
      if (!textToDownload) return;

      const blob = new Blob([textToDownload], { type: 'text/plain;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      const safeQuery = (correctedQuery || query).replace(/[^a-zA-Z0-9-ء-ي ]/g, "").trim() || 'results';
      link.download = `qran-top-search-${safeQuery}.txt`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
  };

  const handlePlayAll = () => {
    if (displayedResults.length > 0) {
      onStartPlayback(displayedResults, selectedAudioEdition);
    }
  };

  const handleSaveClick = (ayah: Ayah) => {
    onSaveAyah({
      type: 'ayah',
      id: `${ayah.surah!.number}:${ayah.numberInSurah}`,
      surah: ayah.surah!.number,
      ayah: ayah.numberInSurah,
      text: ayah.text || '',
      createdAt: Date.now(),
    });
    setActivePopover(null);
  };

  const handleCopyAyah = (ayah: Ayah) => {
    const surahName = ayah.surah?.name || '';
    const cleanSurahName = formatSurahNameForDisplay(surahName);
    const textToCopy = `"${ayah.text || ''}" (سورة ${cleanSurahName} - الآية ${ayah.numberInSurah})`;
    navigator.clipboard.writeText(textToCopy).then(() => {
        setCopiedAyah(ayah.number);
        setTimeout(() => setCopiedAyah(null), 2000);
        setActivePopover(null);
    });
  };

  const handleSearchByAyahText = (ayah: Ayah) => {
    const simpleSurah = simpleCleanData.find(s => s.number === ayah.surah!.number);
    const simpleAyah = simpleSurah?.ayahs.find(a => a.numberInSurah === ayah.numberInSurah);
    const simpleTextToSearch = simpleAyah?.text;

    if (simpleTextToSearch) {
        onNewSearch(simpleTextToSearch, 'quran-simple-clean', { surah: ayah.surah!.number, ayah: ayah.numberInSurah, wordIndex: 0 });
    } else if (ayah.text) {
        onNewSearch(ayah.text, displayEdition.identifier, { surah: ayah.surah!.number, ayah: ayah.numberInSurah, wordIndex: 0 });
    }
    setActivePopover(null);
  };

  const handlePlayFromAyah = (ayah: Ayah) => {
    const startIndex = results.findIndex(a => a.number === ayah.number);
    if (startIndex !== -1) {
        onStartPlayback(results, selectedAudioEdition, startIndex);
    }
    setActivePopover(null);
  };

  const finalQueryForChecks = correctedQuery || query;
  const shouldShowAnalysisButton = finalQueryForChecks.trim().split(/\s+/).filter(Boolean).length === 1 && searchType === 'text';

  const handleAnalysisClick = () => {
      if (finalQueryForChecks.trim()) {
