                        className="inline-flex items-center gap-2 px-4 py-2 bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-300 font-semibold rounded-md hover:bg-blue-200 dark:hover:bg-blue-800/60 transition-colors"
                    >
                        <SparklesIcon className="w-5 h-5" />
                        <span>عرض التحليل المحفوظ لهذه الكلمة</span>
                    </a>
                </div>
            )}
        </div>

        {displayedResults.length > 0 && (
          <>
            <div className="flex items-center flex-wrap gap-2 my-6 p-3 bg-surface-subtle rounded-lg border border-border-default">
                <span className="text-sm font-semibold text-text-muted ml-2">أدوات النتائج:</span>
                <div className="inline-flex items-center gap-2 border border-border-default rounded-full bg-surface p-1 shadow-sm">
                    <button onClick={handlePlayAll} disabled={isPlaybackLoading || allAudioEditions.length === 0} className="flex items-center gap-2 px-3 py-1 rounded-full text-sm text-text-secondary hover:bg-surface-hover transition-colors disabled:opacity-70 disabled:cursor-not-allowed">
                        {isPlaybackLoading ? <SpinnerIcon className="w-4 h-4"/> : <PlayIcon className="w-4 h-4"/>}
                        <span>{isPlaybackLoading ? 'تحضير...' : 'تشغيل الكل'}</span>
                    </button>
                    <div className="border-l border-border-default h-5"></div>
                    <div className="min-w-0">
                        <AudioEditionSelector 
                            audioEditions={allAudioEditions}
                            selectedAudioEdition={selectedAudioEdition}
                            onSelect={onAudioEditionChange}
                            size="sm"
                        />
                    </div>
                </div>
                {searchType === 'text' && (
                  <>
                    <button onClick={handleSaveSearch} className="flex items-center gap-2 px-3 py-1.5 rounded-full text-sm text-text-secondary bg-surface hover:bg-surface-hover border border-border-default shadow-sm transition-colors">
                        <BookmarkIcon className="w-4 h-4"/>
                        <span>حفظ البحث</span>
                    </button>
                  </>
                )}
                <button onClick={handleCopyAll} disabled={isAllCopied} className="flex items-center gap-2 px-3 py-1.5 rounded-full text-sm text-text-secondary bg-surface hover:bg-surface-hover border border-border-default shadow-sm transition-colors disabled:opacity-70">
                    {isAllCopied ? <CheckIcon className="w-4 h-4 text-green-500"/> : <DocumentDuplicateIcon className="w-4 h-4"/>}
                    <span>{isAllCopied ? 'تم النسخ!' : 'نسخ كل النتائج'}</span>
                </button>
                <button onClick={handleDownloadAll} className="flex items-center gap-2 px-3 py-1.5 rounded-full text-sm text-text-secondary bg-surface hover:bg-surface-hover border border-border-default shadow-sm transition-colors">
                    <DownloadIcon className="w-4 h-4"/>
                    <span>تحميل النتائج (txt)</span>
                </button>
            </div>
            <DiscussionSection
                topicId={normalizedQueryForDiscussion}
                wordForTopic={correctedQuery || query}
                autoOpen={autoOpenDiscussion}
                showAnalysisButton={shouldShowAnalysisButton}
                onAnalysisClick={handleAnalysisClick}
            />
          </>
        )}

        <div className="mt-6">
        {displayedResults.length > 0 ? (
            <ul className="space-y-4">
                {displayedResults.map((ayah, index) => {
                    const simpleSurah = simpleCleanData.find(s => s.number === ayah.surah?.number);
                    const simpleAyah = simpleSurah?.ayahs.find(a => a.numberInSurah === ayah.numberInSurah);
                    const simpleAyahText = simpleAyah?.text || '';

                   return (
                       <SearchResultItem 
                            key={ayah.number}
                            itemRef={itemRefs.current[index]}
                            ayah={ayah} 
                            queryWords={searchType === 'number' ? [] : queryWords}
                            onNewSearch={onNewSearch}
                            displayEdition={displayEdition}
                            displayEditionData={displayEditionData}
                            searchEdition={searchEdition}
                            fontSize={fontSize}
                            searchType={searchType}
                            isCurrentlyPlaying={ayah.number === currentlyPlayingAyahGlobalNumber}
                            pulsingWordIndex={pulsingWord?.itemIndex === index ? pulsingWord.wordIndex : -1}
                            resultIndex={index}
                            simpleAyahText={simpleAyahText}
                            onUthmaniWordClick={handleUthmaniWordClick}
                            onOpenPopover={(ayah, triggerElement) => setActivePopover({ ayah, triggerElement })}
                        />
                   );
                })}
            </ul>
        ) : (
            <div className="text-center p-10 text-lg text-text-muted">لم يتم العثور على نتائج.</div>
        )}
        </div>
      </main>

       {wordPopoverState && (
         <div 
            ref={wordPopoverRef}
            className="absolute p-3 bg-surface rounded-lg shadow-lg border border-border-default flex items-center gap-2 z-20 animate-fade-in flex-wrap leading-loose"
            style={(() => {
                if (!wordPopoverState.triggerElement) return { opacity: 0, top: 0, left: 0 };
                const rect = wordPopoverState.triggerElement.getBoundingClientRect();
                return {
                    top: `${rect.bottom + window.scrollY + 5}px`,
                    left: `${rect.left + window.scrollX + rect.width / 2}px`,
                    transform: 'translateX(-50%)',
                };
            })()}
        >
            {wordPopoverState.simpleText.split(' ').map((word, wordIndex) => {
                const originalAyah = displayedResults[wordPopoverState.resultIndex];
                if (!originalAyah?.surah) return null;

                return (
                    <button
                        key={wordIndex}
                        onClick={() => {
                            onNewSearch(word, 'quran-simple-clean', { surah: originalAyah.surah!.number, ayah: originalAyah.numberInSurah, wordIndex: wordIndex });
                            setWordPopoverState(null);
                        }}
                        className="px-2 py-1 bg-surface-subtle rounded-md hover:bg-primary/20 transition-colors"
                    >
                        {word}
                    </button>
                );
            })}
        </div>
      )}

       {activePopover && (
            <AyahActionPopover 
                activePopover={activePopover}
                onClose={() => setActivePopover(null)}
                onSave={handleSaveClick}
                onCopy={handleCopyAyah}
                onSearchText={handleSearchByAyahText}
                onSearchNumber={onSearchByAyahNumber}
                onPlayFrom={handlePlayFromAyah}
                copiedAyah={copiedAyah}
            />
       )}

    </div>
  );
};

import { useState, useEffect, useMemo, useCallback } from 'react';
import { db, FieldValue } from '../firebase';
import { generateKhatmahId, checkActionLimit, incrementActionCount } from '../utils/khatmiyah';

// --- Types ---
export interface JuzStatus {
    status: 'available' | 'reserved' | 'completed';
    by?: string;
    reservedAt?: any; // Firestore Timestamp
    completedAt?: any; // Firestore Timestamp
}

export interface Khatmah {
    id: string;
    name: string;
    createdAt: any; // Firestore Timestamp
    juz_status: { [key: number]: JuzStatus };
    visibility: 'public' | 'private';
}

export interface KhatmahHistoryItem {
    id: string;
    name: string;
}

const KHATMIYAH_HISTORY_KEY = 'qran_khatmiyah_history';

export const useKhatmiyah = (khatmiyahId: string | null) => {
    const [khatmah, setKhatmah] = useState<Khatmah | null>(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const [updatingJuz, setUpdatingJuz] = useState<number | null>(null);

    const [publicKhatmahs, setPublicKhatmahs] = useState<Khatmah[]>([]);
    const [loadingPublic, setLoadingPublic] = useState(true);

    const [history, setHistory] = useState<KhatmahHistoryItem[]>(() => {
        try {
            const stored = localStorage.getItem(KHATMIYAH_HISTORY_KEY);
            return stored ? JSON.parse(stored) : [];
        } catch {
            return [];
        }
    });

    const addKhatmahToHistory = useCallback((khatmahToAdd: KhatmahHistoryItem) => {
        setHistory(prev => {
            const existing = prev.find(h => h.id === khatmahToAdd.id);
            const filtered = prev.filter(h => h.id !== khatmahToAdd.id);
            const updatedHistory = [{... (existing || {}), ...khatmahToAdd}, ...filtered];

            if (updatedHistory.length > 20) {
                updatedHistory.pop();
            }

            localStorage.setItem(KHATMIYAH_HISTORY_KEY, JSON.stringify(updatedHistory));
            return updatedHistory;
        });
    }, []);

    const removeKhatmahFromHistory = useCallback((idToRemove: string) => {
        if (window.confirm("هل تريد إزالة هذه الختمة من قائمتك؟ لن يتم حذف الختمة نفسها.")) {
            setHistory(prev => {
                const newHistory = prev.filter(h => h.id !== idToRemove);
                localStorage.setItem(KHATMIYAH_HISTORY_KEY, JSON.stringify(newHistory));
                return newHistory;
            });
        }
    }, []);

    useEffect(() => {
        if (khatmiyahId) {
            setLoadingPublic(false);
            return;
        }

        setLoadingPublic(true);
        const unsubscribe = db.collection('khatmahs')
            .orderBy('createdAt', 'desc')
            .limit(30)
            .onSnapshot(snapshot => {
                const allRecent = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() } as Khatmah));
                const publicOnly = allRecent.filter(k => k.visibility === 'public');
                setPublicKhatmahs(publicOnly);
                setLoadingPublic(false);
            }, err => {
                console.error("Error fetching public khatmahs:", err);
                setError("فشل في تحميل الختمات العامة.");
                setLoadingPublic(false);
            });

        return () => unsubscribe();
    }, [khatmiyahId]);

    useEffect(() => {
        if (!khatmiyahId) {
            setLoading(false);
            setError(null);
            setKhatmah(null);
            return;
        }

        setLoading(true);
        const unsubscribe = db.collection('khatmahs').doc(khatmiyahId)
            .onSnapshot(doc => {
                if (doc.exists) {
                    const data = doc.data() as Omit<Khatmah, 'id'>;
                    const loadedKhatmah = { id: doc.id, ...data };
                    setKhatmah(loadedKhatmah);
                    addKhatmahToHistory({ id: loadedKhatmah.id, name: loadedKhatmah.name });
                    setError(null);
                } else {
                    setError(`الختمة بالمعرف "${khatmiyahId}" غير موجودة. تأكد من صحة الرابط أو الكود.`);
                    setKhatmah(null);
                }
                setLoading(false);
            }, err => {
                console.error("Error fetching Khatmah:", err);
                setError("حدث خطأ أثناء تحميل بيانات الختمة.");
                setLoading(false);
            });

        return () => unsubscribe();
    }, [khatmiyahId, addKhatmahToHistory]);

    const handleCreateKhatmah = async (name: string, visibility: 'public' | 'private'): Promise<string> => {
        if (!checkActionLimit('creations')) {
            throw new Error("Creation limit reached.");
        }

        const initialJuzStatus: { [key: number]: JuzStatus } = {};
        for (let i = 1; i <= 30; i++) {
            initialJuzStatus[i] = { status: 'available' };
        }

        let newId = '';
        let docExists = true;
        let attempts = 0;

        while(docExists && attempts < 10) {
            newId = generateKhatmahId();
            const docRef = db.collection('khatmahs').doc(newId);
            const docSnap = await docRef.get();
            docExists = docSnap.exists;
            attempts++;
        }

        if (docExists) {
            alert("فشل في إنشاء معرف فريد للختمة، يرجى المحاولة مرة أخرى.");
            throw new Error("Could not generate a unique ID.");
        }

        try {
            await db.collection('khatmahs').doc(newId).set({
                name: name,
                visibility: visibility,
                createdAt: new Date(),
                juz_status: initialJuzStatus
            });

            incrementActionCount('creations');
            addKhatmahToHistory({id: newId, name});
            return newId;
        } catch (err) {
            console.error("Error creating Khatmah:", err);
            alert("فشل إنشاء الختمة. يرجى المحاولة مرة أخرى.");
            throw err;
        }
    };

    const handleReserveJuz = async (juzNumber: number, name: string) => {
        if (!khatmiyahId || !name.trim()) return;

        if (!checkActionLimit('reservations')) {
            throw new Error("Reservation limit reached.");
        }

        setUpdatingJuz(juzNumber);
        const docRef = db.collection('khatmahs').doc(khatmiyahId);

        try {
            await db.runTransaction(async (transaction: any) => {
                const doc = await transaction.get(docRef);
                if (!doc.exists) throw new Error("Document does not exist!");

                const currentJuzStatus = doc.data().juz_status[juzNumber];
                if (currentJuzStatus.status !== 'available') {
                    throw new Error("This Juz has already been reserved.");
                }

                transaction.update(docRef, { 
                    [`juz_status.${juzNumber}`]: {
                        status: 'reserved',
                        by: name.trim(),
                        reservedAt: new Date()
                    }
                });
            });

            incrementActionCount('reservations');
        } catch (err) {
            console.error("Error reserving Juz:", err);
            if (!(err instanceof Error && err.message === "Reservation limit reached.")) {
                alert("فشل حجز الجزء. قد يكون شخص آخر قد حجزه قبلك.");
            }
            throw err;
        } finally {
            setUpdatingJuz(null);
        }
    };

    const handleCompleteJuz = async (juzNumber: number) => {
        if (!khatmiyahId) return;

        if (!checkActionLimit('completions')) {
            return;
        }

        setUpdatingJuz(juzNumber);
        const docRef = db.collection('khatmahs').doc(khatmiyahId);

        try {
            await db.runTransaction(async (transaction: any) => {
                const doc = await transaction.get(docRef);
                if (!doc.exists) throw new Error("Document does not exist!");

                const currentJuzStatus = doc.data().juz_status[juzNumber];
                if (currentJuzStatus.status !== 'reserved') {
                    throw new Error("This Juz is not currently reserved.");
                }

                transaction.update(docRef, {
                    [`juz_status.${juzNumber}`]: {
                        ...currentJuzStatus,
                        status: 'completed',
                        completedAt: new Date(),
                    }
                });
            });
            incrementActionCount('completions');
        } catch (err) {
            console.error("Error completing Juz:", err);
            if (!(err instanceof Error && err.message === "Completion limit reached.")) {
                alert("فشل تحديث حالة الجزء. قد يكون هناك مشكلة في الاتصال.");
            }
        } finally {
            setUpdatingJuz(null);
        }
    };

    const progress = useMemo(() => {
        if (!khatmah) return 0;
        const completedCount = Object.values(khatmah.juz_status).filter(s => (s as JuzStatus).status === 'completed').length;
        return Math.round((completedCount / 30) * 100);
    }, [khatmah]);

    return {
        khatmah,
        loading,
        error,
        updatingJuz,
        publicKhatmahs,
        loadingPublic,
        history,
        progress,
        handleCreateKhatmah,
        handleReserveJuz,
        handleCompleteJuz,
        removeKhatmahFromHistory,
    };
};

