import React, { useState } from 'react';
import { useKhatmiyah, JuzStatus } from '../hooks/useKhatmiyah';
import { SpinnerIcon, UsersIcon, PlusIcon, TrashIcon } from './icons';
import CreateKhatmahModal from './khatmiyah/CreateKhatmahModal';
import JoinKhatmahModal from './khatmiyah/JoinKhatmahModal';
import ReserveJuzModal from './khatmiyah/ReserveJuzModal';

interface KhatmiyahViewProps {
    khatmiyahId: string | null;
}

const KhatmiyahView: React.FC<KhatmiyahViewProps> = ({ khatmiyahId }) => {
    const {
        khatmah, loading, error, updatingJuz, publicKhatmahs, loadingPublic,
        history, progress, handleCreateKhatmah, handleReserveJuz,
        handleCompleteJuz, removeKhatmahFromHistory
    } = useKhatmiyah(khatmiyahId);

    const [modal, setModal] = useState<'create' | 'join' | 'reserve' | null>(null);
    const [activeJuz, setActiveJuz] = useState<number | null>(null);

    const handleJoinKhatmah = (id: string) => {
        if (id.trim()) {
            window.location.hash = `#/khatmiyah/${id.trim()}`;
            setModal(null);
        }
    };

    const handleJuzClick = (juzNumber: number, status: JuzStatus) => {
        if (updatingJuz) return;
        if (status.status === 'available') {
            setActiveJuz(juzNumber);
            setModal('reserve');
        } else if (status.status === 'reserved') {
            if (window.confirm(`هل تريد تأكيد إتمام قراءة الجزء ${juzNumber}؟`)) {
                handleCompleteJuz(juzNumber);
            }
        }
    };

    if (loading) {
        return <div className="flex justify-center p-16"><SpinnerIcon className="w-12 h-12 text-primary" /></div>;
    }

    if (error) {
        return (
            <div className="text-center p-10 bg-surface rounded-lg shadow-md max-w-lg mx-auto">
                <p className="text-red-500 font-semibold">{error}</p>
                <button onClick={() => window.location.hash = '#/khatmiyah'} className="mt-4 px-4 py-2 bg-primary text-white rounded-md">
                    العودة إلى الصفحة الرئيسية للختميات
                </button>
            </div>
        );
    }

    if (khatmah) {
        return (
            <div className="animate-fade-in w-full max-w-4xl mx-auto px-4">
                {modal === 'reserve' && activeJuz && (
                    <ReserveJuzModal
                        onClose={() => { setModal(null); setActiveJuz(null); }}
                        onReserve={(name) => handleReserveJuz(activeJuz, name)}
                        juzNumber={activeJuz}
                    />
                )}
                <header className="mb-6 text-center">
                    <h1 className="text-3xl font-bold text-primary-text-strong mb-2">{khatmah.name}</h1>
                    <div className="w-full bg-surface-subtle rounded-full h-4 border border-border-default">
                        <div
                            className="bg-green-500 h-4 rounded-full text-xs font-medium text-white text-center p-0.5 leading-none transition-all duration-500"
                            style={{ width: `${progress}%` }}
                        >
                            {progress > 10 && `${progress}%`}
                        </div>
                    </div>
                     <p className="text-sm text-text-muted mt-2">
                        {progress < 100 ? `${30 - Object.values(khatmah.juz_status).filter(s => (s as JuzStatus).status === 'completed').length} جزء متبقي` : "اكتملت الختمة، تقبل الله منكم."}
                    </p>
                </header>

                <main>
                    <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-3">
                        {Object.entries(khatmah.juz_status).map(([juzNumStr, status]) => {
                            const juzNumber = parseInt(juzNumStr, 10);
                            let statusClass = '';
                            let statusText = 'متاح';
                            switch (status.status) {
                                case 'reserved':
                                    statusClass = 'bg-yellow-100 dark:bg-yellow-900/40 border-yellow-400 text-yellow-800 dark:text-yellow-200 cursor-pointer hover:bg-yellow-200 dark:hover:bg-yellow-900/60';
                                    statusText = `محجوز (${status.by})`;
                                    break;
                                case 'completed':
                                    statusClass = 'bg-green-100 dark:bg-green-900/40 border-green-500 text-green-800 dark:text-green-300 cursor-default opacity-80';
                                    statusText = `مكتمل (${status.by})`;
                                    break;
                                default:
                                    statusClass = 'bg-surface-subtle border-border-default text-text-secondary cursor-pointer hover:bg-surface-hover hover:border-primary';
                                    break;
                            }

                            return (
                                <button
                                    key={juzNumber}
                                    onClick={() => handleJuzClick(juzNumber, status)}
                                    disabled={status.status === 'completed' || !!updatingJuz}
                                    className={`p-4 rounded-lg border-2 text-center transition-colors relative ${statusClass}`}
                                >
                                    {updatingJuz === juzNumber && <div className="absolute inset-0 bg-white/50 dark:bg-black/50 flex items-center justify-center rounded-lg"><SpinnerIcon className="w-6 h-6"/></div>}
                                    <span className="block text-2xl font-bold">{juzNumber}</span>
                                    <span className="block text-xs truncate">{statusText}</span>
                                </button>
                            );
                        })}
                    </div>
                </main>
            </div>
        );
    }

    return (
        <div className="animate-fade-in w-full max-w-4xl mx-auto px-4">
             {modal === 'create' && <CreateKhatmahModal onClose={() => setModal(null)} onCreate={handleCreateKhatmah} />}
             {modal === 'join' && <JoinKhatmahModal onClose={() => setModal(null)} onJoin={handleJoinKhatmah} />}

             <header className="text-center mb-8">
                <UsersIcon className="w-16 h-16 mx-auto text-primary mb-2"/>
                <h1 className="text-3xl font-bold text-primary-text-strong">الختمة الجماعية</h1>
                <p className="text-text-secondary mt-2">شارك في ختم القرآن الكريم مع الآخرين، أو أنشئ ختمة جديدة وادعُ أصدقاءك.</p>
            </header>

            <div className="flex flex-col sm:flex-row gap-4 mb-10">
                <button onClick={() => setModal('create')} className="flex-1 flex items-center justify-center gap-3 px-6 py-4 bg-primary text-white font-bold rounded-lg hover:bg-primary-hover transition-all duration-200 shadow-md hover:shadow-lg">
                    <PlusIcon className="w-6 h-6"/>
                    <span>إنشاء ختمة جديدة</span>
                </button>
                 <button onClick={() => setModal('join')} className="flex-1 flex items-center justify-center gap-3 px-6 py-4 bg-surface-subtle text-text-primary font-bold rounded-lg hover:bg-surface-hover transition-all duration-200 shadow-sm hover:shadow-md border border-border-default">
                    <span>الانضمام بـ "كود"</span>
                </button>
            </div>

            <div className="space-y-8">
                {history.length > 0 && (
                    <section>
                        <h2 className="text-xl font-semibold mb-4 text-text-primary">ختماتك السابقة</h2>
                        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                            {history.map(item => (
                                <div key={item.id} className="group relative">
                                    <a href={`#/khatmiyah/${item.id}`} onClick={(e) => {e.preventDefault(); window.location.hash = `#/khatmiyah/${item.id}`;}} className="block w-full p-4 bg-surface rounded-lg shadow-sm border border-border-default hover:shadow-md hover:border-primary transition-all">
                                        <p className="font-bold text-text-primary group-hover:text-primary transition-colors truncate">{item.name}</p>
                                        <p className="text-xs text-text-muted font-mono">{item.id}</p>
                                    </a>
                                    <button onClick={() => removeKhatmahFromHistory(item.id)} className="absolute top-2 left-2 p-1.5 rounded-full bg-surface-hover text-text-muted opacity-0 group-hover:opacity-100 transition-opacity hover:text-red-500 hover:bg-red-100 dark:hover:bg-red-900/50">
                                        <TrashIcon className="w-4 h-4" />
                                    </button>
                                </div>
                            ))}
                        </div>
                    </section>
                )}

                <section>
                    <h2 className="text-xl font-semibold mb-4 text-text-primary">الختمات العامة المتاحة</h2>
                    {loadingPublic ? <div className="flex justify-center p-8"><SpinnerIcon className="w-8 h-8"/></div> : (
                        publicKhatmahs.length > 0 ? (
                            <div className="space-y-3">
                                {publicKhatmahs.map(k => {
                                    const progress = Math.round(Object.values(k.juz_status).filter(s => (s as JuzStatus).status === 'completed').length / 30 * 100);
                                    return (
                                        <a key={k.id} href={`#/khatmiyah/${k.id}`} onClick={(e) => {e.preventDefault(); window.location.hash = `#/khatmiyah/${k.id}`;}} className="block p-4 bg-surface rounded-lg shadow-sm border border-border-default hover:shadow-md hover:border-primary transition-all">
                                            <div className="flex justify-between items-center">
                                                <h3 className="font-bold text-text-primary">{k.name}</h3>
                                                <span className="text-sm font-semibold text-green-600">{progress}%</span>
                                            </div>
                                            <div className="w-full bg-surface-subtle rounded-full h-2 mt-2">
                                                <div className="bg-green-500 h-2 rounded-full" style={{width: `${progress}%`}}></div>
                                            </div>
                                        </a>
                                    )
                                })}
                            </div>
                        ) : (
                            <p className="text-text-muted text-center p-6 bg-surface-subtle rounded-lg">لا توجد ختمات عامة متاحة حالياً. كن أول من ينشئ واحدة!</p>
                        )
                    )}
                </section>
            </div>
        </div>
    );
};

export default KhatmiyahView;

import React from 'react';
import type { Ayah, QuranEdition, SurahData, FontSize, BrowsingMode } from '../types';

interface AyahRendererProps {
    ayahsToRender: Ayah[];
    surah: SurahData;
    highlightAyahNumber: number | null;
    onWordClick: (query: string, editionIdentifier: string, position: { surah: number; ayah: number; wordIndex: number; }) => void;
    displayEdition: QuranEdition;
    fontSize: FontSize;
    browsingMode: BrowsingMode;
    currentlyPlayingAyahGlobalNumber: number | null;
    simpleCleanData: SurahData[];
    wordPopoverState: { ayahNumberInSurah: number; simpleText: string; triggerElement: HTMLElement; } | null;
    setWordPopoverState: (state: { ayahNumberInSurah: number; simpleText: string; triggerElement: HTMLElement; } | null) => void;
    setActivePopover: (state: { ayah: Ayah; triggerElement: HTMLElement } | null) => void;
    playingAyahRef: React.RefObject<HTMLSpanElement>;
    highlightRef: React.RefObject<HTMLSpanElement>;
    firstAyahInfo: { bismillah: string; restOfAyah: string; } | null;
}

const AyahRenderer: React.FC<AyahRendererProps> = ({
    ayahsToRender, surah, highlightAyahNumber, onWordClick, displayEdition, fontSize, browsingMode,
    currentlyPlayingAyahGlobalNumber, simpleCleanData, wordPopoverState, setWordPopoverState,
    setActivePopover, playingAyahRef, highlightRef, firstAyahInfo
}) => {

    const isImlaei = displayEdition.identifier.includes('simple-clean');

    const cleanImlaiText = (text: string | undefined): string | undefined => {
        if (!text) return text;
        const marksToRemoveRegex = /[\u06D6-\u06ED]/g;
        return text.replace(marksToRemoveRegex, '');
    };

    return (
        <>
            {ayahsToRender.map((ayah, index) => {
                const isHighlighted = ayah.numberInSurah === highlightAyahNumber;
                const isPlaying = ayah.number === currentlyPlayingAyahGlobalNumber;

                const simpleSurah = simpleCleanData.find(s => s.number === surah.number);
                const simpleAyah = simpleSurah?.ayahs.find(a => a.numberInSurah === ayah.numberInSurah);

                const baseText = (index === 0 && firstAyahInfo) ? firstAyahInfo.restOfAyah : ayah.text;
                const textToDisplay = isImlaei ? cleanImlaiText(baseText) : baseText;

                const createUthmaniWordClickHandler = (event: React.MouseEvent<HTMLButtonElement>) => {
                    const simpleAyahText = simpleAyah?.text;
                    if (simpleAyahText) {
                        if (wordPopoverState?.ayahNumberInSurah === ayah.numberInSurah) {
                            setWordPopoverState(null);
                        } else {
                            setWordPopoverState({
                                ayahNumberInSurah: ayah.numberInSurah,
                                simpleText: simpleAyahText,
                                triggerElement: event.currentTarget,
                            });
                        }
                    }
                };

                return (
                    <span key={ayah.number} className="inline">
                        <span
                            ref={isPlaying ? playingAyahRef : (isHighlighted ? highlightRef : null)}
                            className={`inline rounded-md transition-colors duration-300 ${isPlaying ? 'bg-primary/20' : ''}`}
                        >
                            {textToDisplay?.split(' ').map((word, wordIndex, arr) => (
                                <React.Fragment key={wordIndex}>
                                    <button
                                        onClick={
                                            isImlaei
                                                ? () => onWordClick(word, displayEdition.identifier, { surah: surah.number, ayah: ayah.numberInSurah, wordIndex: wordIndex })
                                                : createUthmaniWordClickHandler
                                        }
                                        className="word-trigger bg-transparent border-none p-0 font-inherit text-inherit leading-inherit cursor-pointer hover:bg-primary/10 rounded-md transition-colors"
                                        aria-label={`إظهار خيارات البحث لكلمة: ${word}`}
                                    >
                                        {word}
                                    </button>
                                    {wordIndex < arr.length - 1 && ' '}
                                </React.Fragment>
                            ))}
                        </span>

                        <span className="relative inline-block align-middle">
                            <button
                                onClick={(e) => setActivePopover({ ayah: ayah, triggerElement: e.currentTarget })}
                                className={`popover-trigger mx-1 select-none cursor-pointer hover:opacity-80 transition-opacity ${browsingMode === 'page' ? 'ayah-marker' : 'text-sm font-sans font-bold text-primary-text rounded-md p-1 -m-1'}`}
                                aria-label={`إجراءات للآية ${ayah.numberInSurah}`}
                                aria-haspopup="true"
                            >
                                {browsingMode === 'page' ? ayah.numberInSurah : `﴿${ayah.numberInSurah}﴾`}
                            </button>
                        </span>
                    </span>
                );
            })}
        </>
    );
};

export default AyahRenderer;

import React, { useEffect, useRef, useState, useMemo } from 'react';
import type { SurahData, QuranEdition, QuranFont, SavedAyahItem, Ayah, FontSize, BrowsingMode } from '../types';
import { PlayIcon, SpinnerIcon, ArrowLeftIcon, ArrowRightIcon } from './icons';
import AudioEditionSelector from './AudioEditionSelector';
import AyahActionPopover from './AyahActionPopover';
import AyahRenderer from './AyahRenderer';
import { formatSurahNameForDisplay, normalizeArabicText } from '../utils/text';

interface SurahDetailViewProps {
  surah: SurahData;
  highlightAyahNumber: number | null;
  onWordClick: (query: string, editionIdentifier: string, position: { surah: number; ayah: number; wordIndex: number; }) => void;
  displayEdition: QuranEdition;
  fontSize: FontSize;
  browsingMode: BrowsingMode;
  onSaveAyah: (item: SavedAyahItem) => void;
  onSearchByAyahNumber: (ayahNumber: number) => void;
  // --- Props for audio playback ---
  currentlyPlayingAyahGlobalNumber: number | null;
  isPlaybackLoading: boolean;
  onStartPlayback: (ayahs: Ayah[], audioEditionIdentifier: string, startIndex?: number) => void;
  allAudioEditions: QuranEdition[];
  selectedAudioEdition: string;
  onAudioEditionChange: (identifier: string) => void;
  // --- Prop for word popover ---
  simpleCleanData: SurahData[];
  hizbQuarterStartMap: Map<number, number>;
}

const SurahDetailView: React.FC<SurahDetailViewProps> = ({ 
  surah, highlightAyahNumber, onWordClick, displayEdition, fontSize, browsingMode,
  onSaveAyah, onSearchByAyahNumber,
  currentlyPlayingAyahGlobalNumber, isPlaybackLoading, onStartPlayback,
  allAudioEditions, selectedAudioEdition, onAudioEditionChange,
  simpleCleanData, hizbQuarterStartMap
}) => {
  const highlightRef = useRef<HTMLSpanElement>(null);
  const playingAyahRef = useRef<HTMLSpanElement>(null);
  const wordPopoverRef = useRef<HTMLDivElement>(null);

  const [activePopover, setActivePopover] = useState<{ ayah: Ayah; triggerElement: HTMLElement } | null>(null);
  const [copiedAyah, setCopiedAyah] = useState<number | null>(null);
  const [currentPage, setCurrentPage] = useState<number>(1);

  const [wordPopoverState, setWordPopoverState] = useState<{
    ayahNumberInSurah: number;
    simpleText: string;
    triggerElement: HTMLElement;
  } | null>(null);

  const [touchStartX, setTouchStartX] = useState<number | null>(null);
  const [touchCurrentX, setTouchCurrentX] = useState<number | null>(null);

  const prevSurahNumber = useRef<number | null>(null);

  const { ayahsByPage, firstPage, lastPage, getPageForAyahNumber } = useMemo(() => {
    const map = new Map<number, Ayah[]>();
    const ayahNumToPageMap = new Map<number, number>();
    if (!surah || !surah.ayahs || surah.ayahs.length === 0) {
        return { ayahsByPage: map, firstPage: 1, lastPage: 1, getPageForAyahNumber: (n: number) => undefined };
    }
    let minPage = Infinity;
    let maxPage = -Infinity;
    for (const ayah of surah.ayahs) {
        if (ayah.page) {
            if (!map.has(ayah.page)) {
                map.set(ayah.page, []);
            }
            map.get(ayah.page)!.push(ayah);
            minPage = Math.min(minPage, ayah.page);
            maxPage = Math.max(maxPage, ayah.page);
            ayahNumToPageMap.set(ayah.numberInSurah, ayah.page);
        }
    }
    const getPageForAyahNumber = (num: number) => ayahNumToPageMap.get(num);
    return { ayahsByPage: map, firstPage: minPage === Infinity ? 1 : minPage, lastPage: maxPage === -Infinity ? 1 : maxPage, getPageForAyahNumber };
  }, [surah]);

  useEffect(() => {
    let targetPage: number | undefined;

    if (highlightAyahNumber) {
        targetPage = getPageForAyahNumber(highlightAyahNumber);
    } else if (currentlyPlayingAyahGlobalNumber) {
        const playingAyah = surah.ayahs.find(a => a.number === currentlyPlayingAyahGlobalNumber);
        if (playingAyah) {
            targetPage = getPageForAyahNumber(playingAyah.numberInSurah);
        }
    }

    setCurrentPage(targetPage || firstPage);
  }, [surah.number, highlightAyahNumber, currentlyPlayingAyahGlobalNumber, getPageForAyahNumber, firstPage]);


  useEffect(() => {
    const currentSurahNumber = surah.number;
    const isNewSurahView = prevSurahNumber.current !== currentSurahNumber;

    if (isNewSurahView) {
        prevSurahNumber.current = currentSurahNumber;
    }

    let elementToScroll: HTMLElement | null = null;
    let shouldPulse = false;

    if (currentlyPlayingAyahGlobalNumber !== null && surah.ayahs.some(a => a.number === currentlyPlayingAyahGlobalNumber)) {
        elementToScroll = playingAyahRef.current;
        shouldPulse = false;
    }
    else if (isNewSurahView && highlightAyahNumber) {
        elementToScroll = highlightRef.current;
        shouldPulse = true;
    }

    if (elementToScroll) {
        const scrollTimer = setTimeout(() => {
            elementToScroll?.scrollIntoView({
                behavior: 'smooth',
                block: 'center',
            });

            if (shouldPulse) {
                elementToScroll?.classList.add('animate-highlight-pulse');
                setTimeout(() => {
                    elementToScroll?.classList.remove('animate-highlight-pulse');
                }, 3000);
            }
        }, 150); // Delay to allow page transition to finish

        return () => clearTimeout(scrollTimer);
    } else if (isNewSurahView && browsingMode === 'full') {
        window.scrollTo(0, 0);
    }
  }, [highlightAyahNumber, currentlyPlayingAyahGlobalNumber, surah.number, browsingMode, currentPage]);


  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
        const target = event.target as Node;
        if (!(target as HTMLElement).closest('.popover-trigger, .popover-content')) {
            setActivePopover(null);
        }
        if (wordPopoverRef.current && !wordPopoverRef.current.contains(target)) {
            if (!(event.target as HTMLElement).closest('.word-trigger')) {
                setWordPopoverState(null);
            }
        }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
        document.removeEventListener("mousedown", handleClickOutside);
    };
  }, []);

  const handlePlaySurah = () => {
    onStartPlayback([], selectedAudioEdition);
  };

  if (displayEdition.format === 'audio') {
    return (
      <div className="animate-fade-in w-full max-w-4xl mx-auto px-4">
        <main className="bg-surface p-6 sm:p-8 rounded-lg shadow-md transition-colors duration-300">
          <h3 className="text-xl font-bold mb-4 text-center text-primary-text">{displayEdition.name}</h3>
          <div className="flex flex-col gap-2">
            {surah.ayahs.map(ayah => (
              ayah.audio ? (
                <div key={ayah.number} className="flex items-center gap-4 py-2 px-3 my-1 bg-surface-subtle rounded-lg">
                  <span className="font-bold text-primary-text">الآية {ayah.numberInSurah}</span>
                  <audio
                    controls
                    src={ayah.audio}
                    className="w-full h-10"
                    preload="metadata"
                    title={`الاستماع للآية ${ayah.numberInSurah}`}
                  >
                    متصفحك لا يدعم عنصر الصوت.
                  </audio>
                </div>
              ) : null
            ))}
          </div>
        </main>
      </div>
    );
  }

  const getQuranTextStyle = () => {
    const isImlaei = displayEdition.identifier.includes('simple-clean');

    if (displayEdition.type === 'quran' && displayEdition.direction === 'rtl') {
      return {
        className: `${isImlaei ? 'imlai-font' : 'uthmani-font'} quran-text-${fontSize}`,
      };
    }

    return { className: 'font-quran text-2xl' };
  }

  const { className: quranTextClass } = getQuranTextStyle();

  const handleSaveClick = (ayah: Ayah) => {
    onSaveAyah({
      type: 'ayah',
      id: `${ayah.surah?.number || surah.number}:${ayah.numberInSurah}`,
      surah: ayah.surah?.number || surah.number,
      ayah: ayah.numberInSurah,
      text: ayah.text || '',
      createdAt: Date.now(),
    });
    setActivePopover(null);
  };

  const handleCopyAyah = (ayah: Ayah) => {
    const surahName = ayah.surah?.name || surah.name;
    const cleanSurahName = formatSurahNameForDisplay(surahName);
    const textToCopy = `"${ayah.text || ''}" (سورة ${cleanSurahName} - الآية ${ayah.numberInSurah})`;
    navigator.clipboard.writeText(textToCopy).then(() => {
        setCopiedAyah(ayah.number);
        setTimeout(() => setCopiedAyah(null), 2000);
        setActivePopover(null);
    });
  };

  const handleSearchByAyahText = (ayah: Ayah) => {
    const simpleSurah = simpleCleanData.find(s => s.number === (ayah.surah?.number || surah.number));
    const simpleAyah = simpleSurah?.ayahs.find(a => a.numberInSurah === ayah.numberInSurah);
    const simpleTextToSearch = simpleAyah?.text;

    if (simpleTextToSearch) {
        onWordClick(simpleTextToSearch, 'quran-simple-clean', { surah: surah.number, ayah: ayah.numberInSurah, wordIndex: 0 });
    } else if (ayah.text) {
        onWordClick(ayah.text, displayEdition.identifier, { surah: surah.number, ayah: ayah.numberInSurah, wordIndex: 0 });
    }
    setActivePopover(null);
  };

  const handlePlayFromAyah = (ayah: Ayah) => {
    const startIndex = surah.ayahs.findIndex(a => a.numberInSurah === ayah.numberInSurah);
    if (startIndex !== -1) {
        onStartPlayback([], selectedAudioEdition, startIndex);
    }
    setActivePopover(null);
  };

  const handleNextPage = () => {
    setCurrentPage(p => {
        const nextPage = p < lastPage ? p + 1 : p;
        if (nextPage !== p) window.scrollTo({ top: 0, behavior: 'smooth' });
        return nextPage;
    });
  };

  const handlePrevPage = () => {
      setCurrentPage(p => {
          const prevPage = p > firstPage ? p - 1 : p;
          if (prevPage !== p) window.scrollTo({ top: 0, behavior: 'smooth' });
          return prevPage;
      });
  };

  const SWIPE_THRESHOLD = 50;

  const handleTouchStart = (e: React.TouchEvent) => {
      if (browsingMode !== 'page') return;
      setTouchStartX(e.targetTouches[0].clientX);
      setTouchCurrentX(e.targetTouches[0].clientX);
  };

  const handleTouchMove = (e: React.TouchEvent) => {
      if (touchStartX === null || browsingMode !== 'page') return;
      setTouchCurrentX(e.targetTouches[0].clientX);
  };

  const handleTouchEnd = () => {
      if (touchStartX === null || touchCurrentX === null || browsingMode !== 'page') return;

      const deltaX = touchStartX - touchCurrentX;

      if (Math.abs(deltaX) > SWIPE_THRESHOLD) {
          if (deltaX > 0) { 
              if (currentPage < lastPage) {
                  handleNextPage();
              }
          } else { 
              if (currentPage > firstPage) {
                  handlePrevPage();
              }
          }
      }

      setTouchStartX(null);
      setTouchCurrentX(null);
  };

  const swipeTranslateX = useMemo(() => {
      if (touchStartX === null || touchCurrentX === null || browsingMode !== 'page') {
          return 0;
      }
      const deltaX = touchCurrentX - touchStartX;

      if ((deltaX < 0 && currentPage >= lastPage) || (deltaX > 0 && currentPage <= firstPage)) {
          return deltaX / 3;
      }
      return deltaX;
  }, [touchStartX, touchCurrentX, browsingMode, currentPage, firstPage, lastPage]);

  const ayahsToRender = useMemo(() => browsingMode === 'page'
      ? (ayahsByPage.get(currentPage) || [])
      : surah.ayahs, [browsingMode, ayahsByPage, currentPage, surah.ayahs]);

  const pageInfo = useMemo(() => {
    if (browsingMode !== 'page' || !hizbQuarterStartMap || ayahsToRender.length === 0) return null;

    const firstAyah = ayahsToRender[0];
    let surahName = firstAyah.surah?.name || surah.name;
    surahName = surahName.replace(/^سُورَةُ\s*/, '').trim();

    const juzNumber = firstAyah.juz;
    const hizbNumber = firstAyah.hizbQuarter ? Math.floor((firstAyah.hizbQuarter - 1) / 4) + 1 : null;

    const markers: {label: string}[] = [];
    const processedQuarters = new Set<number>();

    if (hizbNumber) {
        const startOfHizbQuarter = (hizbNumber - 1) * 4 + 1;
        if(hizbQuarterStartMap.get(startOfHizbQuarter) === firstAyah.number) {
            markers.push({ label: `الحزب ${hizbNumber}`});
        }
    }

    for(const ayah of ayahsToRender) {
        if(ayah.hizbQuarter && hizbQuarterStartMap.get(ayah.hizbQuarter) === ayah.number) {
            if (processedQuarters.has(ayah.hizbQuarter)) continue;

            const quarterType = (ayah.hizbQuarter - 1) % 4;
            if (quarterType === 1) markers.push({ label: 'ربع الحزب'});
            else if (quarterType === 2) markers.push({ label: 'نصف الحزب'});
            else if (quarterType === 3) markers.push({ label: 'ثلاثة أرباع الحزب'});

            processedQuarters.add(ayah.hizbQuarter);
        }
    }

    return {
        surahName,
        juzNumber,
        markers,
        side: currentPage % 2 === 0 ? 'left' : 'right'
    };
  }, [currentPage, browsingMode, ayahsToRender, hizbQuarterStartMap, surah.name]);

  const bismillahInfo = useMemo(() => {
    const isApplicable = surah.number !== 1 && surah.number !== 9 && 
                         displayEdition.type === 'quran' && displayEdition.direction === 'rtl' &&
                         (browsingMode === 'full' || currentPage === firstPage);

    if (!isApplicable || ayahsToRender.length === 0) return null;

    const firstAyah = ayahsToRender[0];
    if (!firstAyah.text) return null;

    const normalizedText = normalizeArabicText(firstAyah.text);
    const NORMALIZED_BISMILLAH = 'بسم الله الرحمن الرحيم';

    if (normalizedText.startsWith(NORMALIZED_BISMILLAH)) {
        const uthmaniTerminator = 'ٱلرَّحِيمِ';
        const simpleTerminator = 'الرحيم';
        let bismillahPart = '';
        let restOfAyahPart = '';

        const uthmaniIndex = firstAyah.text.indexOf(uthmaniTerminator);
        if (uthmaniIndex > -1 && uthmaniIndex < 35) {
            const splitPoint = uthmaniIndex + uthmaniTerminator.length;
            bismillahPart = firstAyah.text.substring(0, splitPoint);
            restOfAyahPart = firstAyah.text.substring(splitPoint);
        } else {
            const simpleIndex = firstAyah.text.indexOf(simpleTerminator);
            if (simpleIndex > -1 && simpleIndex < 35) {
                const splitPoint = simpleIndex + simpleTerminator.length;
                bismillahPart = firstAyah.text.substring(0, splitPoint);
                restOfAyahPart = firstAyah.text.substring(splitPoint);
            }
        }

        if (bismillahPart && restOfAyahPart.trim()) {
            return {
                bismillah: bismillahPart.trim(),
                restOfAyah: restOfAyahPart.trim()
            };
        } else if (bismillahPart && !restOfAyahPart.trim()) {
            return null;
        }
    }

    return null;
  }, [surah.number, displayEdition, browsingMode, currentPage, firstPage, ayahsToRender]);

  return (
    <div className="animate-fade-in w-full max-w-4xl mx-auto px-4">
      {displayEdition.type === 'quran' && displayEdition.direction === 'rtl' && (
        <div className="w-full max-w-4xl mx-auto mb-4 flex items-stretch justify-center gap-3">
            <div className="flex-grow">
                <AudioEditionSelector
                    audioEditions={allAudioEditions}
                    selectedAudioEdition={selectedAudioEdition}
                    onSelect={onAudioEditionChange}
                />
            </div>
            <button
                onClick={handlePlaySurah}
                disabled={isPlaybackLoading || allAudioEditions.length === 0}
                className="flex items-center gap-3 px-6 py-3 bg-surface border-2 border-primary text-primary-text rounded-lg shadow-sm hover:shadow-md hover:bg-surface-hover transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary disabled:opacity-60 disabled:cursor-not-allowed flex-shrink-0"
                aria-label="استماع للسورة"
            >
                {isPlaybackLoading ? <SpinnerIcon className="w-6 h-6"/> : <PlayIcon className="w-6 h-6"/>}
                <span className="text-lg font-semibold hidden sm:inline">{isPlaybackLoading ? 'جاري التحضير...' : 'استماع'}</span>
            </button>
        </div>
      )}
      <div className="overflow-hidden rounded-lg">
        {browsingMode === 'page' && !displayEdition.identifier.includes('simple-clean') ? (
             <div
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                onTouchEnd={handleTouchEnd}
                style={{
                    transform: `translateX(${swipeTranslateX}px)`,
                    transition: touchStartX === null ? 'transform 0.3s ease-out' : 'none',
                }}
             >
                <div className="mushaf-page" style={{ touchAction: 'pan-y' }}>
                    {pageInfo?.markers.map((marker, index) => (
                         <div key={index} className={`hizb-marker ${pageInfo.side}`}>{marker.label}</div>
                    ))}
                    <header className="mushaf-header">
                        <span>{pageInfo?.juzNumber && `الجزء ${pageInfo.juzNumber}`}</span>
                        <span>{pageInfo?.surahName && `سورة ${pageInfo.surahName}`}</span>
                    </header>

                    {bismillahInfo && (
                        <div className="text-center mb-8 font-bismillah text-2xl text-primary-text-strong">
                            {bismillahInfo.bismillah}
                        </div>
                    )}
                    <main dir={displayEdition.direction} className={`text-text-primary ${quranTextClass} text-justify`}>
                        <AyahRenderer {...{ ayahsToRender, surah, highlightAyahNumber, onWordClick, displayEdition, fontSize, browsingMode, currentlyPlayingAyahGlobalNumber, simpleCleanData, wordPopoverState, setWordPopoverState, setActivePopover, playingAyahRef, highlightRef }} firstAyahInfo={bismillahInfo} />
                    </main>

                    <footer className="mushaf-footer">
                        <span>{currentPage}</span>
                    </footer>
                </div>
            </div>
        ) : (
            <main
                onTouchStart={handleTouchStart}
                onTouchMove={handleTouchMove}
                onTouchEnd={handleTouchEnd}
                style={{
                    transform: `translateX(${swipeTranslateX}px)`,
                    transition: touchStartX === null ? 'transform 0.3s ease-out' : 'none',
                    touchAction: browsingMode === 'page' ? 'pan-y' : 'auto',
                }}
                className={`bg-surface p-6 sm:p-8 rounded-lg shadow-md transition-colors duration-300 ${browsingMode === 'page' ? 'cursor-grab active:cursor-grabbing' : ''}`}
            >
                {browsingMode === 'page' && lastPage > firstPage && (
                    <div className="text-center mb-6 -mt-2">
                        <span className="font-mono text-sm font-semibold text-text-muted select-none">
                            {currentPage}
                        </span>
                    </div>
                )}
                {bismillahInfo && (
                    <div className="text-center mb-8 font-bismillah text-2xl text-primary-text-strong">
                        {bismillahInfo.bismillah}
                    </div>
                )}
                <div dir={displayEdition.direction} className={`text-text-primary ${quranTextClass} ${displayEdition.direction === 'ltr' ? 'text-left' : 'text-right'}`}>
                     <AyahRenderer {...{ ayahsToRender, surah, highlightAyahNumber, onWordClick, displayEdition, fontSize, browsingMode, currentlyPlayingAyahGlobalNumber, simpleCleanData, wordPopoverState, setWordPopoverState, setActivePopover, playingAyahRef, highlightRef }} firstAyahInfo={bismillahInfo} />
                </div>
            </main>
        )}
      </div>

      {browsingMode === 'page' && lastPage > firstPage && (
          <div className="mt-6 flex items-center justify-between p-2 bg-surface rounded-full shadow-md border border-border-default">
              <button 
                  onClick={handlePrevPage} 
                  disabled={currentPage <= firstPage}
                  className="flex items-center gap-2 px-4 py-2 rounded-full text-text-secondary hover:bg-surface-hover disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                  <ArrowRightIcon className="w-5 h-5" />
                  <span className="font-semibold hidden sm:inline">الصفحة السابقة</span>
              </button>
              <div className="font-bold text-lg text-text-primary font-mono select-none">
                  {currentPage}
              </div>
              <button 
                  onClick={handleNextPage} 
                  disabled={currentPage >= lastPage}
                  className="flex items-center gap-2 px-4 py-2 rounded-full text-text-secondary hover:bg-surface-hover disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
              >
                  <span className="font-semibold hidden sm:inline">الصفحة التالية</span>
                  <ArrowLeftIcon className="w-5 h-5" />
              </button>
          </div>
      )}

      {wordPopoverState && (
         <div 
            ref={wordPopoverRef}
            className="absolute p-3 bg-surface rounded-lg shadow-lg border border-border-default flex items-center gap-2 z-20 animate-fade-in flex-wrap leading-loose"
            style={(() => {
                if (!wordPopoverState.triggerElement) return { opacity: 0, top: 0, left: 0 };
                const rect = wordPopoverState.triggerElement.getBoundingClientRect();
                return {
                    top: `${rect.bottom + window.scrollY + 5}px`,
                    left: `${rect.left + window.scrollX + rect.width / 2}px`,
                    transform: 'translateX(-50%)',
                };
            })()}
        >
            {wordPopoverState.simpleText.split(' ').map((word, index) => (
                <button
                    key={index}
                    onClick={() => {
                        onWordClick(word, 'quran-simple-clean', { surah: surah.number, ayah: wordPopoverState.ayahNumberInSurah, wordIndex: index });
                        setWordPopoverState(null);
                    }}
                    className="px-2 py-1 bg-surface-subtle rounded-md hover:bg-primary/20 transition-colors"
                >
                    {word}
                </button>
            ))}
        </div>
      )}

      {activePopover && (
        <AyahActionPopover 
            activePopover={activePopover}
            onClose={() => setActivePopover(null)}
            onSave={handleSaveClick}
            onCopy={handleCopyAyah}
            onSearchText={handleSearchByAyahText}
            onSearchNumber={onSearchByAyahNumber}
            onPlayFrom={handlePlayFromAyah}
            copiedAyah={copiedAyah}
        />
      )}

    </div>
  );
};

export default SurahDetailView;

import React, { useState } from 'react';
import { SpinnerIcon, UploadIcon, DownloadIcon } from '../icons';

interface TadabburGatewayProps {
    onExportNotebook: () => Promise<string>;
    onImportNotebook: (code: string) => Promise<void>;
}

const TadabburGateway: React.FC<TadabburGatewayProps> = ({ onExportNotebook, onImportNotebook }) => {
    const [exportCode, setExportCode] = useState<string | null>(null);
    const [isExporting, setIsExporting] = useState(false);
    const [exportError, setExportError] = useState<string | null>(null);

    const [importCode, setImportCode] = useState('');
    const [isImporting, setIsImporting] = useState(false);
    const [importMessage, setImportMessage] = useState<{ type: 'success' | 'error', text: string } | null>(null);

    const handleExport = async () => {
        setIsExporting(true);
        setExportError(null);
        setExportCode(null);
        setImportMessage(null);
        try {
            const code = await onExportNotebook();
            setExportCode(code);
        } catch (err) {
            setExportError(err instanceof Error ? err.message : 'حدث خطأ غير متوقع');
        } finally {
            setIsExporting(false);
        }
    };

    const handleImport = async (e: React.FormEvent) => {
        e.preventDefault();
        setIsImporting(true);
        setImportMessage(null);
        setExportError(null);
        setExportCode(null);
        try {
            await onImportNotebook(importCode);
            setImportMessage({ type: 'success', text: 'تم استيراد الدفتر بنجاح وحذف النسخة من الخادم.' });
            setImportCode('');
        } catch (err) {
            setImportMessage({ type: 'error', text: err instanceof Error ? err.message : 'حدث خطأ غير متوقع' });
        } finally {
            setIsImporting(false);
        }
    };

    return (
        <div className="animate-fade-in">
            <h2 className="text-2xl font-semibold mb-2 text-text-primary">بوابة دفتر التدبر</h2>
            <p className="text-text-secondary mb-8">استخدم هذه الواجهة لنقل بياناتك المحفوظة بين الأجهزة المختلفة.</p>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="p-5 bg-surface-subtle rounded-lg border border-border-default flex flex-col">
                    <h3 className="text-xl font-semibold mb-2 text-text-primary">تصدير دفتر التدبر</h3>
                    <p className="text-sm text-text-secondary mb-4 flex-grow">
