import React, { useState, useMemo, useCallback, useEffect } from 'react';
import type { Ayah, QuranEdition, SurahData, FontSize } from '../types';
import { useTheme } from '../hooks/useTheme';
import { useAudioKhatmiyah } from '../hooks/useAudioKhatmiyah';
import { 
    SpinnerIcon, PlayIcon, PauseIcon, ForwardIcon, BackwardIcon, 
    HomeIcon, BookOpenIcon, ComputerDesktopIcon
} from './icons';
import AudioEditionSelector from './AudioEditionSelector';
import JuzSelectionModal from './khatmiyah/JuzSelectionModal';
import PlaybackModeModal from './khatmiyah/PlaybackModeModal';
import SettingsModal from './khatmiyah/SettingsModal';

// --- Types ---
type PlaybackMode = 'continuous' | 'single' | 'selection';

interface AudioKhatmiyahViewProps {
    allAyahs: Ayah[];
    allAudioEditions: QuranEdition[];
    initialAyahNumber: number;
    onSaveProgress: (ayahNumber: number) => void;
    selectedAudioEdition: string;
    onAudioEditionChange: (id: string) => void;
    allQuranData: { [key: string]: SurahData[] } | null;
    fetchCustomEditionData: (id: string) => void;
    fontSize: FontSize;
    onFontSizeChange: (size: FontSize) => void;
    activeEditions: QuranEdition[];
    selectedEdition: string;
    onEditionChange: (id: string) => void;
}

// --- Main Component ---
const AudioKhatmiyahView: React.FC<AudioKhatmiyahViewProps> = ({
    allAyahs, allAudioEditions, initialAyahNumber, onSaveProgress,
    selectedAudioEdition, onAudioEditionChange, allQuranData, fetchCustomEditionData,
    fontSize, onFontSizeChange,
    activeEditions, selectedEdition, onEditionChange
}) => {
    const { cycleTheme, emoji, name, nextThemeName } = useTheme();

    const [controlsVisible, setControlsVisible] = useState(true);
    const [isSettingsOpen, setIsSettingsOpen] = useState(false);
    const [isJuzSelectorOpen, setIsJuzSelectorOpen] = useState(false);
    const [isModeSelectorOpen, setIsModeSelectorOpen] = useState(false);
    const [juzModalMode, setJuzModalMode] = useState<'jump' | 'selection'>('jump');

    const juzStartAyahs = useMemo(() => {
        if (!allAyahs || allAyahs.length === 0) return [];
        const juzMap = new Map<number, number>();
        for (const ayah of allAyahs) {
            if (ayah.juz && !juzMap.has(ayah.juz)) {
                juzMap.set(ayah.juz, ayah.number);
            }
        }
        return Array.from(juzMap.entries())
            .sort((a, b) => a[0] - b[0])
            .map(([juz, ayahNumber]) => ({ juz, ayahNumber }));
    }, [allAyahs]);

    const {
        audioRef, currentAyah, displayedText, isPlaying, isLoading, isBuffering,
        audioDuration, audioProgress, currentWordIndex,
        handlePlayPause, handleNextAyah, handlePrevAyah, handleAudioEnded,
        setCurrentAyahNumber, setAudioDuration, setIsLoading, setIsBuffering, setIsPlaying,
        playbackMode, setPlaybackMode, playbackSelection, setPlaybackSelection
    } = useAudioKhatmiyah(
        allAyahs, initialAyahNumber, onSaveProgress, selectedAudioEdition, allAudioEditions,
        allQuranData, fetchCustomEditionData, selectedEdition, juzStartAyahs
    );

    const displayEditionDetails = useMemo(() => activeEditions.find(e => e.identifier === selectedEdition), [activeEditions, selectedEdition]);

    const handleScreenTap = () => {
        if (isPlaying) setControlsVisible(prev => !prev);
    };

    useEffect(() => {
        if (!isPlaying) setControlsVisible(true);
    }, [isPlaying]);

    useEffect(() => {
        if (!allQuranData?.[selectedEdition]) {
            fetchCustomEditionData(selectedEdition);
        }
    }, [selectedEdition, allQuranData, fetchCustomEditionData]);

    const handleJuzSelect = (ayahNumber: number) => {
        setCurrentAyahNumber(ayahNumber);
        setIsJuzSelectorOpen(false);
        if (!isPlaying) setIsPlaying(true);
    };

    const handleSelectionConfirm = (selectedJuzs: number[]) => {
        if (selectedJuzs.length === 0) return;
        setPlaybackMode('selection');
        setPlaybackSelection(selectedJuzs);
        const startAyahNumber = juzStartAyahs.find(j => j.juz === selectedJuzs[0])?.ayahNumber;
        if (startAyahNumber) {
            setCurrentAyahNumber(startAyahNumber);
        }
        setIsJuzSelectorOpen(false);
        if (!isPlaying) setIsPlaying(true);
    };

    const getQuranTextStyle = useCallback(() => {
        const isImlaei = displayEditionDetails?.identifier.includes('simple-clean');
        if (displayEditionDetails?.type === 'quran' && displayEditionDetails?.direction === 'rtl') {
            return {
                className: `${isImlaei ? 'imlai-font' : 'uthmani-font'} quran-text-${fontSize}`,
            };
        }
        return { 
            className: `font-sans text-2xl md:text-3xl lg:text-4xl`, 
            style: { lineHeight: 1.8 } 
        };
    }, [displayEditionDetails, fontSize]);

    const { className: quranTextClass } = getQuranTextStyle();
    const canHighlight = displayEditionDetails?.type === 'quran' && displayEditionDetails?.direction === 'rtl';

    const formatJuzSelection = (juzs: number[]): string => {
        if (!juzs || juzs.length === 0) return '';
        if (juzs.length === 1) return `${juzs[0]}`;
        const sorted = [...juzs].sort((a,b) => a - b);
        const ranges: string[] = [];
        let start = sorted[0]; let end = sorted[0];
        for (let i = 1; i < sorted.length; i++) {
            if (sorted[i] === end + 1) end = sorted[i];
            else { ranges.push(start === end ? `${start}` : `${start}-${end}`); start = sorted[i]; end = sorted[i]; }
        }
        ranges.push(start === end ? `${start}` : `${start}-${end}`);
        return ranges.join(', ');
    };

    const getPlaybackScopeDescription = () => {
        if (playbackMode === 'single' && currentAyah?.juz) return `الجزء ${currentAyah.juz} فقط`;
        if (playbackMode === 'selection' && playbackSelection) {
            const isRange = playbackSelection.every((juz, i) => i === 0 || juz === playbackSelection[i-1] + 1);
            if (isRange && playbackSelection.length > 1) return `من الجزء ${playbackSelection[0]} إلى ${playbackSelection[playbackSelection.length - 1]}`;
            return `أجزاء مختارة: ${formatJuzSelection(playbackSelection)}`;
        }
        return 'ختمة كاملة';
    };

    if (!currentAyah) {
        return <div className="flex flex-col gap-4 justify-center items-center h-screen bg-gray-900 text-white"><SpinnerIcon className="w-10 h-10"/> <p>جاري تحميل بيانات الختمة...</p></div>;
    }

    return (
        <div className="bg-background text-text-primary fixed inset-0 flex flex-col font-sans" onClick={handleScreenTap}>
            {isJuzSelectorOpen && <JuzSelectionModal onClose={() => setIsJuzSelectorOpen(false)} juzStartAyahs={juzStartAyahs} onJuzSelect={handleJuzSelect} onSelectionConfirm={handleSelectionConfirm} mode={juzModalMode} />}
            {isModeSelectorOpen && <PlaybackModeModal onClose={() => setIsModeSelectorOpen(false)} onModeSelect={(mode: PlaybackMode) => { setPlaybackMode(mode); setPlaybackSelection(null); if (mode === 'single' && !isPlaying) setIsPlaying(true); }} onCustomSelectionStart={() => { setIsModeSelectorOpen(false); setJuzModalMode('selection'); setIsJuzSelectorOpen(true); }} />}
            {isSettingsOpen && <SettingsModal onClose={() => setIsSettingsOpen(false)} fontSize={fontSize} onFontSizeChange={onFontSizeChange} activeEditions={activeEditions} selectedEdition={selectedEdition} onEditionChange={onEditionChange} />}

            <audio ref={audioRef} onLoadedMetadata={() => setAudioDuration(audioRef.current?.duration || 0)} onCanPlay={() => { setIsLoading(false); setIsBuffering(false); if(isPlaying) audioRef.current?.play(); }} onPlay={() => setIsPlaying(true)} onPause={() => { if (audioRef.current && Math.abs(audioRef.current.currentTime - audioRef.current.duration) > 0.1) setIsPlaying(false); }} onEnded={handleAudioEnded} onWaiting={() => setIsBuffering(true)} className="hidden" />

            <header className={`flex-shrink-0 p-3 text-center bg-surface/80 backdrop-blur-md shadow-md z-10 transition-all duration-300 ${controlsVisible ? 'opacity-100' : 'opacity-0 -translate-y-full'}`}>
                <a href="#/" onClick={(e) => { e.preventDefault(); window.location.hash = '#/'; }} title="العودة للرئيسية" aria-label="العودة للرئيسية" className="absolute top-3 left-3 p-2 rounded-full bg-surface-subtle hover:bg-surface-hover">
                    <HomeIcon className="w-6 h-6"/>
                </a>
                <h1 className="text-xl font-bold text-primary-text-strong">سورة {currentAyah.surah?.name}</h1>
                <div className="text-sm text-text-muted font-semibold flex justify-center gap-4">
                    <span>الآية: {currentAyah.numberInSurah}</span>
                    <span>الجزء: {currentAyah.juz}</span>
                    <span>الصفحة: {currentAyah.page}</span>
                </div>
            </header>

            <main className="flex-grow flex items-center justify-center p-4">
                <div className="text-center w-full">
                    {(isLoading && !displayedText) ? <div className="flex flex-col gap-4 items-center"><SpinnerIcon className="w-12 h-12 text-primary"/><p className="text-lg">جاري تحميل الآية...</p></div>
                    : <p className={`select-none ${quranTextClass}`} dir={displayEditionDetails?.direction || 'rtl'}>
                        {canHighlight ? displayedText.split(' ').map((word, index) => <span key={index} className={`transition-colors duration-200 ${index === currentWordIndex ? 'text-primary' : ''}`}>{word}{' '}</span>) : displayedText}
                       </p>}
                </div>
            </main>

            <footer className={`flex-shrink-0 p-4 bg-surface/80 backdrop-blur-md shadow-[0_-4px_30px_rgba(0,0,0,0.1)] z-10 transition-all duration-300 ${controlsVisible ? 'opacity-100' : 'opacity-0 translate-y-full'}`}>
                <div className="w-full h-1.5 bg-surface-subtle rounded-full mb-4"><div className="h-1.5 bg-primary rounded-full transition-all" style={{ width: audioDuration > 0 ? `${(audioProgress / audioDuration) * 100}%` : '0%'}}></div></div>
                <div className="flex items-center justify-between gap-4">
                    <div className="flex-1 min-w-0 flex flex-col gap-1 items-start">
                        <AudioEditionSelector audioEditions={allAudioEditions} selectedAudioEdition={selectedAudioEdition} onSelect={onAudioEditionChange} size="sm" />
                        <span className="text-xs font-semibold text-text-muted px-2">{getPlaybackScopeDescription()}</span>
                    </div>
                    <div className="flex items-center gap-2 sm:gap-4 flex-shrink-0">
                        <button onClick={handlePrevAyah} className="p-2 text-text-secondary hover:text-text-primary transition-colors"><BackwardIcon className="w-7 h-7" /></button>
                        <button onClick={handlePlayPause} className="p-4 bg-primary text-white rounded-full shadow-lg hover:bg-primary-hover transition-transform hover:scale-105">
                             {isBuffering ? <SpinnerIcon className="w-8 h-8"/> : (isPlaying ? <PauseIcon className="w-8 h-8" /> : <PlayIcon className="w-8 h-8" />)}
                        </button>
                        <button onClick={handleNextAyah} className="p-2 text-text-secondary hover:text-text-primary transition-colors"><ForwardIcon className="w-7 h-7" /></button>
                    </div>
                    <div className="flex-1 flex justify-end items-center gap-2">
                        <button onClick={() => { setIsModeSelectorOpen(true); }} title="تحديد نطاق القراءة" className={`p-2 rounded-full transition-colors text-text-muted hover:bg-surface-hover`}><BookOpenIcon className="w-6 h-6"/></button>
                        <div className="h-6 w-px bg-border-default mx-1"></div>
                        <button onClick={() => setIsSettingsOpen(true)} title="إعدادات العرض" className="p-2 rounded-full text-text-muted hover:bg-surface-hover transition-colors"><ComputerDesktopIcon className="w-6 h-6"/></button>
                        <button onClick={cycleTheme} title={`الوضع الحالي: ${name}. اضغط للتغيير إلى وضع ${nextThemeName}.`} className="p-2 rounded-full text-text-muted hover:bg-surface-hover transition-colors w-10 h-10 flex items-center justify-center text-xl">
                            <span role="img" aria-label={name} className="leading-none select-none">{emoji}</span>
                        </button>
                    </div>
                </div>
            </footer>
        </div>
    );
};

export default AudioKhatmiyahView;

import React, { useState } from 'react';
import type { SavedItem } from '../../types';
import { TrashIcon, SearchIcon, BookOpenIcon, PencilIcon, CheckIcon } from '../icons';
import { timeAgo } from '../../utils/date';

interface SavedItemCardProps { 
    item: SavedItem, 
    onDelete: () => void,
    onUpdateNotes: (notes: string) => void,
}

const SavedItemCard: React.FC<SavedItemCardProps> = ({ item, onDelete, onUpdateNotes }) => {
    const [isEditingNotes, setIsEditingNotes] = useState(false);
    const [noteText, setNoteText] = useState(item.notes || '');

    const handleClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
        e.preventDefault();
        window.location.hash = e.currentTarget.getAttribute('href')!;
    };

    const handleSaveNote = () => {
        onUpdateNotes(noteText.trim());
        setIsEditingNotes(false);
    };

    const handleCancelEdit = () => {
        setNoteText(item.notes || '');
        setIsEditingNotes(false);
    };

    return (
        <li className="bg-surface-subtle p-4 rounded-xl shadow-sm transition-shadow duration-200 hover:shadow-lg flex flex-col gap-3">
            <div className="flex items-start gap-4">
                <div className="flex-shrink-0 text-primary mt-1">
                    {item.type === 'ayah' ? <BookOpenIcon className="w-5 h-5"/> : <SearchIcon className="w-5 h-5"/>}
                </div>
                <div className="flex-grow">
                    {item.type === 'ayah' && (
                        <a href={`#/surah/${item.surah}?ayah=${item.ayah}`} onClick={handleClick} className="block hover:underline">
                            <p className="font-quran text-lg text-text-primary">{item.text}</p>
                            <p className="text-sm font-bold text-primary-text mt-1 font-quran-title">سورة {item.surah} : الآية {item.ayah}</p>
                        </a>
                    )}
                    {item.type === 'search' && (
                         <a href={`#/search/${encodeURIComponent(item.query)}`} onClick={handleClick} className="block hover:underline">
                            <p className="font-semibold text-lg text-text-primary">بحث عن: "{item.query}"</p>
                        </a>
                    )}
                    <p className="text-xs text-text-subtle mt-2">{timeAgo(item.createdAt)}</p>
                </div>
                 <button 
                    onClick={onDelete} 
                    className="p-2 -m-2 rounded-full text-text-subtle hover:text-red-600 hover:bg-red-100 dark:hover:bg-red-900/50 transition-colors flex-shrink-0"
                    title="حذف العنصر"
                >
                    <TrashIcon className="w-5 h-5" />
                </button>
            </div>

            {/* --- Tadabbur Notes Section --- */}
            <div className="border-t border-border-default pt-3">
                {isEditingNotes ? (
                    <div>
                        <textarea
                            value={noteText}
                            onChange={(e) => setNoteText(e.target.value)}
                            placeholder="اكتب تدبرك هنا..."
                            className="w-full p-2 border border-border-default rounded-md bg-surface focus:outline-none focus:ring-2 focus:ring-primary transition-colors"
                            rows={4}
                            autoFocus
                        />
                        <div className="flex justify-end gap-2 mt-2">
                            <button onClick={handleCancelEdit} className="px-4 py-2 text-sm rounded-md bg-surface-subtle hover:bg-surface-hover transition-colors">
                                إلغاء
                            </button>
                            <button onClick={handleSaveNote} className="px-4 py-2 text-sm text-white rounded-md bg-primary hover:bg-primary-hover flex items-center gap-2">
                                <CheckIcon className="w-4 h-4" />
                                <span>حفظ التدبر</span>
                            </button>
                        </div>
                    </div>
                ) : (
                    <div className="flex justify-between items-start gap-2">
                        {item.notes ? (
                            <blockquote className="text-text-secondary whitespace-pre-wrap flex-grow italic border-r-4 border-primary pr-4 py-1">
                                {item.notes}
                            </blockquote>
                        ) : (
                            <p className="text-sm text-text-muted flex-grow py-1">لا توجد ملاحظات.</p>
                        )}
                        <button 
                            onClick={() => setIsEditingNotes(true)} 
                            className="p-2 -m-2 rounded-full text-text-subtle hover:text-blue-600 hover:bg-blue-100 dark:hover:bg-blue-900/50 transition-colors flex-shrink-0" 
                            title={item.notes ? "تعديل التدبر" : "إضافة تدبر"}
                        >
                            <PencilIcon className="w-5 h-5" />
                        </button>
                    </div>
                )}
            </div>
        </li>
    );
};

export default SavedItemCard;

import React from 'react';
import type { Collections, Collection } from '../../types';
import { BookmarkIcon, UploadIcon } from '../icons';
import { timeAgo } from '../../utils/date';

interface CollectionListViewProps {
    collections: Collections;
}

const CollectionListView: React.FC<CollectionListViewProps> = ({ collections }) => {
    const collectionList = Object.values(collections).sort((a: Collection, b: Collection) => b.createdAt - a.createdAt);

    const handleLinkClick = (e: React.MouseEvent<HTMLAnchorElement>) => {
        e.preventDefault();
        window.location.hash = e.currentTarget.getAttribute('href')!;
    };

    return (
        <div className="animate-fade-in w-full max-w-4xl mx-auto px-4">
            <div className="mb-8 p-6 bg-surface rounded-lg shadow-md flex flex-col sm:flex-row items-center justify-between gap-4">
                <div>
                    <h2 className="text-xl font-bold text-text-secondary">نقل دفتر التدبر</h2>
                    <p className="text-text-muted mt-1">هل تريد نقل بياناتك المحفوظة إلى جهاز آخر أو استيرادها؟</p>
                </div>
                <a 
                    href="#/settings?tab=tadabbur"
                    onClick={handleLinkClick}
                    className="flex items-center gap-2 px-5 py-3 bg-primary text-white font-semibold rounded-md hover:bg-primary-hover transition-colors flex-shrink-0"
                >
                    <UploadIcon className="w-5 h-5" />
                    <span>الذهاب إلى بوابة الاستيراد والتصدير</span>
                </a>
            </div>

            <main>
                {collectionList.length > 0 ? (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
                        {collectionList.map((collection: Collection) => (
                            <a 
                                key={collection.id}
                                href={`#/saved/${collection.id}`}
                                onClick={handleLinkClick}
                                className="block p-5 bg-surface rounded-lg shadow-sm hover:shadow-xl hover:border-primary border-2 border-transparent transition-all duration-200 group"
                            >
                                <h2 className="text-xl font-bold text-text-primary group-hover:text-primary transition-colors truncate">{collection.name}</h2>
                                <p className="text-sm text-text-muted mt-1">{collection.items.length} عنصر</p>
                                <p className="text-xs text-text-subtle mt-3">{timeAgo(collection.createdAt)}</p>
                            </a>
