<content>< ![CDATA[import React, { useEffect, useRef, useState, useMemo } from 'react'; 
import type { SurahData, QuranEdition, QuranFont, SavedAyahItem, Ayah, FontSize, Brows ingMode } from '../types';
import { PlayIcon, SpinnerIcon, ArrowLeftIcon, ArrowRightIcon } from './ icons';
import AudioEditionSelector from './AudioEditionSelector';
